window.__D("text/hemshech-ayin-beis/c006",{"p":[[3601330629,"על אור האה' האלקי' כו', וע\"כ נשאר הטבעי' כמו שהיתה כו', וכמו עד\"מ מים שנכנסים בכלי המגבילם מכל צד שהכלי מסבב להמים מכל צד, כן עד\"מ אור האה' האלקי' מתיישבת בתוך כלי הלב ונסתתרת בהם עד שכלי הלב הטבעי' מקיפים אותה מכל צד ונשארת בעצם טבעי' שלה כמו שהוא כו'. והגם שמה שנתפסת בלב זהו ברוחני' כלי הלב, והיינו מה שהלב חפצה באלקו' (רק שהיא בהגבלה בכלי הלב כפי מה שיכולה לשאת כו'), ומרווה צמאונו רק בהאור האלקי המאיר לו (אם בהאה' עצמה או בקיום המצות כו' כנ\"ל), והוא חפץ ומתעסק רק בעניני אלקי' וזה טוב לנפשו כו'. הענין הוא עפמ\"ש בסש\"ב פכ\"ט דבצדיקים הנה\"א הוא האדם והגוף נק' רק בשר אדם וכמו זר נחשב כו', אבל בבינונים הנפש החיונית המלובשת בדמו ובשרו הוא האדם כו', וע\"כ בצדיקים שאינם נתפסים בגשם ועבודתם הוא בהנשמה שלהם כו', הנה תפיסת האה' מה שנתפסת בהכחות דמוח ולב הכל הוא בנה\"א כו', שאין בזה שום תערובות חומרי' כלל כו', דמאחר שהעבודה היא רק מצד הנשמה הרי גם הכלים התופסים את האה' הוא הנה\"א לבד כו', ולהיות\nדעבודתם הוא בבחי' פנימי' המוחין והמדות ובפרט בבחי' אה' בתענוגים כו', ה\"ז פועל על הטבעי' שמתהפך לאלקו' ממש כו' וכמ\"ש בסש\"ב פ\"ט. אבל בבינונים שהן נתפסים בגשם הרי בעבודתם יש תערובות החומרי' כו', וע\"ה שמרגיש היטב את הטוב דאלקות וזה טוב לו הנה יש בזה גופא תערובות חומרי' שא\"ז רק טוב אלקי כ\"א יש בזה תערובות חומריות (א חומריות'ער טוב), ולהיות שמרווה צמאונו בהטוב (עס בלייבט ניט קיין ניט גוט, נאר עם איז גוט און דער גוט איז דאך א חומריות'ער), וע\"כ עצם הטבעי' נשאר בלי שינוי בעצם המהות כו', ואין הכוונה שאינם פועלים מאומה ח\"ו בהנה\"ט שהרי בעבודתם פועלים הכנעה וביטול בהנה\"ט במדות הטבעי' כו' (הן בהעדר ההמשכה וההטי' לעניני' החומרי' שזהו חלישות הכחות הטבעי' כו', וכבינוני המתפלל כל היום שהנה\"ב הוא כישן כו', וע\"י העדר עניני החומרי' ה\"ה נחלש יותר כו' וכמ\"ש במ\"א, והן בזה שגם הוא יחפוץ באלקות והיינו שגם הנה\"ט מוצא טוב יותר בעניני אלקות כו'), רק שכ\"ז הוא בהתפשטות שלו לבד לא בעצם מהותו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והענין הוא דהנה הקטרת הקטורת הוא בהיכל בחי' אצי', וע\"כ גם המשכת האו\"מ הוא השייך אל הפנימי, ובעבודה הו\"ע רעו\"ד המתגלה בנשמה מצ\"ע ע\"י התבוננות והרגש ההפלאה, שזהו בחי' או\"י דנשמה מקיף דחי', ולהיותו בחי' או\"מ ה\"ז מהפך מהות הנה\"ב, משא\"כ באהבה שבטו\"ד שמתיישבת בלב, ומרווה צמאונו בהאהבה והקירוב לאלקות, ובאמת אין כאן גילוי פנימי ממש גם לא בההתבוננות וכ\"ש בהאהבה, רק בתו\"מ שאח\"כ, דבנשמות הגבוהות הוא בבחי' גילוי אור ובפנימי ממש, ובבחי' דביקות עוד יותר מכמו בתפלה, והאור עליון יותר, ובכל אדם ה\"ז רק מהרושם, ומ\"מ מאיר האור ובפנימיות שמרווה צמאונו, וע\"כ הלב החומרי מכסה ע\"ז, ומשו\"ז אינו משתנה בעצם, והגם שזהו שמרווה צמאונו רק באלקות, מ\"מ גם הרוחני הוא הרגש חומרי בבינונים, וע\"כ הביטול הוא רק בבחי' אתכפי' בהתפשטות הנה\"ב.</span>\n<b>רכא)</b> אמנם בחי' רעו\"ד שהיא אה' הבלתי מוגבלת שאינו נכנס תוך הלב אדרבה הוא עודף על הלב ומקיפה כו', ואינו מרווה צמאונו באור האה' כו',"],[3601330630,"ה\"ז פועל על הטבעי' שתתבטל בעצם מהותה עד שיוכל להתהפך עי\"ז מאכזרי לרחמני ומתכלית הגסות לתכלית השפלות כו' וכה\"ג מפני שמתבטל ומשתנה בעצם מהותו כו'. וי\"ל בזה עד\"מ בגוף האדם הרי למע' מהפרסא הן כל כחות הנעלים כמו המוחין שבראש והמדות שבלב כו', ובד\"כ החיות שבלב וריאה ה\"ז עיקר פנימי' החיות כו', ולמטה מהפרסא הן אברי המזון שהן בתכלית הגסות ונמצא בהם פסולת וצואה כו', וזהו מפני שהכחות שבמוח ולב ואברי הנשימה הן בבחי' תפיסא והתלבשות בהכלים שלהם ואינם מתפשטים לחוץ מהכלים שלהם רק הארה לבד כו', וע\"כ אינם פועלים בהאברים להתבטל בעצם מהותם לגבי הכחות פנימי' כו', ומ\"מ פועלים בהתפשטות שלהם, וכידוע דבעת התגלות הכחות פנימי' וכמו בהטרדא באיזה שכל עמוק או באיזה מדה אין כלי העכול פועלים, ועיקר פעולתם הוא בעת השינה כו', והיינו הביטול בהתפשטות לא בעצם המהות כו', והיינו מפני שהכחות נתפסים במקומן בהכלים שלהם ואינם יוצאים חוץ למקומן רק הארה לבד, ע\"כ אינם פועלים רק בהתפשטות הכחות חיצוני' לא שינוי בעצם מהותם כו'. אך כח\nהרצון הרי פועל בכל האברים גם היפך טבעם, כמו לשום רגלו במים קרים ביותר או במים חמים ביותר כו', ובד\"כ כל שינוי הטבע לגמרי בעצם מהות הכחות אין שום מונע ומעכב על הרצון, וזהו לפי שאינו נתפס באיזה כלי והעצם הוא שנמשך בכל מקום כו' (וכמשנת\"ל פנ\"א ונ\"ב), ע\"כ הוא פועל בכל האברים שינוי הטבע כו'. וי\"ל הדוגמא מזה למע' בהאורות דע\"ס דאצי' דע\"ה דא\"ס להתפשטותן ה\"ז רק במדרי' דאצי' אבל לא בבי\"ע, דעולמות בי\"ע הן בבחי' פירוד וכמ\"ש ומשם יפרד כו', ויש גם תערובות טו\"ר כו', והיינו מפני שאורות דאצי' הן שבאו בבחי' מדה וגבול והן בבחי' תפיסא והתלבשות בכלים דאצי' כו', וע\"כ אינו מאיר האור בעולמות בי\"ע רק הארה לבד כו', וע\"ה שפועל ביטול בבי\"ע ה\"ה רק בבחי' ביטול היש לבד כו'. אבל אור הא\"ס שלפני האצי' הרי המשכתו והתפשטותו גם בבי\"ע כמו באצי' כו' (והיינו שאפשר להיות בגילוי בבי\"ע כמו באצי' כו', משא\"כ אור האצי' בכדי שיהי' הגילוי בבי\"ע צ\"ל דוקא ע\"י גילוי אור עליון שלמעלה מאצי' ובי\"ע, וכמ\"ש במ\"א בענין קי\"ס שהי' חבור אצי' ובי\"ע\nכו', שהי' ע\"י הרוח קדים דוקא כו'), ופועל הביטול בבי\"ע בבחי' ביטול המהות כו'. וכנודע בענין כל אשר חפץ ה' עשה שזהו להיות הביטול בעולמות כו' וכמ\"ש בתו\"א ד\"ה מזוזה מימין, והכוונה שם על הביטול במהות היש כו', שהרי גם ההארה דבחי' דבר ה' פועל ג\"כ הביטול בהנברא כו', וענין הצורה שמבחי' חפץ ה' הוא להיות הביטול בעצם המהות כו' וכמ\"ש במ\"א, והיינו מפני שהאור הוא למע' מהתלבשות בכלים ואינו בבחי' תפיסא ע\"כ הוא נמשך ומאיר בכ\"מ כו'. וכמו\"כ בעבודה שבשעת התפלה ה\"ה מתבונן באלקות ומתפעל באהוי\"ר כו', ואחר התפלה מתעלם אור ההתפעלות ולא נשאר רק רשימו לבד והוא המעשה בפו\"מ במצות מעשי' כו', וכמו\"כ בשעת התפלה אין בזה ביטול מהות הנה\"ב גם בשעת התפלה רק בהתפשטותו לבד כו', והיינו מפני שהאהוי\"ר הן בבחי' תפיסא בכלי הלב ע\"כ א\"ז מאיר בגילוי כ\"כ להיות ביטול מהות הטבעי' כו', אבל ברעו\"ד שא\"ז בבחי' התלבשות ותפיסא בכלי הלב ה\"ז מאיר ומתגלה יותר עד שפועל ביטול מהות הטבעי' כו'. אך לפי הנ\"ל הוא שההתגלות פועל ממילא ביטול המהות, וכאן\nהכוונה שזה נוגע אל החומרי' והטבעי', דע\"ה שהאה' היא מצד הנשמה עצמה מ\"מ ה\"ז נוגע אל הטבעי' ועי\"ז נעשה ביטול"],[3601330631,"המהות כו'. ויובן זאת יותר עד\"מ בהשפעת השכל שהשכל של הרב הוא למע' הרבה משכל התלמיד גם באותה השפע שמשפיע לו, ואם משפיע לו השכל במדה וגבול כפי ערך השגת התלמיד הנה מתהפך השכל במוח התלמיד כפי גסות השגתו וה\"ה בהשגה מגושמת כו', וע\"ה שבריבוי ההשפעה והקבלה מזדכך כלי מוחו כו', מ\"מ אינו מזדכך בעצם מהותו ונשאר בהגשמתו בעצם כו', אבל אם משפיע לו למע' מערך כלי מוחו שלא תוכל להתפס בכלי מוחו שיגשמנה ה\"ז פועל ביטול במהות כלי מוחו שמזדכך עי\"ז בעצם מהותו להיות בבחי' דקות ההשגה כו', וכמו שעי\"ז ה\"ה נעשה בבחי' כלי גם כשמקודם לא הי' כלי כלל להשכלות אלו, הנה ע\"י שמשפיע לו באופן כזה שאינו נתפס בכלי מוחו רק יודע ומקבל יוקר הענין (די רייכקייט פון דער זאך) ה\"ה נעשה בבחי' כלי כו', כמו\"כ זיכוך ודקות כלי המוח בעצם המהות נעשה ג\"כ ע\"י השפעה שלמע' מכלי המוח כו', וזהו דוקא מפני שאינו יכול לסבול ולקבל ה\"ז פועל השפלות בכלי מוחו שמתבטלים עי\"ז בעצם מהותם כו'. וכמו\"כ ברעו\"ד דלפי שהאהבה אין לה התיישבות בכלי הלב הטבעי ה\"ז פועל\nבו ההשפלה והביטול (אראפגיפאלינקייט) ומתבטל עי\"ז מהות הטבעי' שלו כו', וזהו דהאה\"ר ע\"ה שבאה מצד התעוררות הנשמה מצ\"ע מ\"מ ה\"ז נוגע אל החומרי' ופועל ביטול המהות כו', אמנם להיות שזהו הרעו\"ד שבאה בהנשמה מצ\"ע ה\"ז רק בבחי' מקיף דחי' לבד וממשיך מלמע' ג\"כ רק גילוי בחי' האו\"מ כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם רעו\"ד שאין הלב מכיל ואינו מרווה צמאונו, משנה עצם המהות, ועד\"מ כחות הפנימים להיותם נתפסים בכלים ורק הארתן מתפשטת באברים החיצונים פועלים בהם רק לעכב התפשטותן, והרצון שהעצם נמשך פועל גם בהיפוך הטבע, והדוגמא למעלה דע\"ס א\"ס להתפשטותן ורק באצי', ובבי\"ע נמשך רק הארה (אם לא ע\"י כח עליון), ואור א\"ס מאיר גם בבי\"ע ופועל בהם הביטול, וכ\"ה בעבודה באה' שבטו\"ד וברעו\"ד, ויותר יובן מהשפעת השכל שלפ\"ע חושי המקבל לא יוצא מהגשמתו, וע\"י השפעת שכליים שלמעלה מחושיו ה\"ה מזדכך בעצם הגשמתו.</span>\n<b>רכב)</b> וכ\"ז הוא בקטרת שבהיכל שהו\"ע רעו\"ד שזה ממשיך מלמע' בחי' או\"מ אבל הוא בחי' חיצוני' הכתר כמשנת\"ל פרי\"ח, אמנם הקטרת דיוהכ\"פ שמכניסין בקה\"ק הו\"ע התשו', וכדאי' במד\"ר שה\"ש ע\"פ אשכול הכופר א\"ר יצחק וכסה ענן הקטרת הכיסוי הזה אין אנו יודעים מהו עד שבא דוד ופירשו נשאת עון עמך כסית כל חטאתם סלה, הרי דענן הקטרת הו\"ע התשו' שעי\"ז ממשיכים בחי' עצמו' א\"ס ממש היינו בחי' פנימי' הכתר כו'. והענין דהנה באד\"ר דק\"ל ב' אי' דא מארי' דחוטמא מחד נוקבא חיין ומחד נוקבא חיין דחיין כו', והוא דמנקב הימין נפק חיין ומנקב השמאל נפיק חיין דחיין (ובס' קול ברמה כ' להיפך אך בכתבים אי' כנ\"ל), והן ב' מקיפים דחי' ויחידה כו', דהנה החוטם הוא כלי הריח וריח בד\"כ הוא בחי' מקיף כנ\"ל פרי\"ז, רק שמנקב הימיני נמשך חיין הוא בחי' מקיף דאו\"י שזהו בחי' מקיף דחי', ומנקב השמאלי בחי' מקיף דאו\"ח בחינת יחידה כו'. והענין דהנה הבחיי כ' ע\"פ וייצר דהחוטם הוא כלי לנשמה דמשם היא נכנסת ומשם היא יוצאת, ולכן מי שנפל עליו מפולת צריכים לבדוק אותו עד חוטמו כדאי' בגמ' יומא ד' פ\"ה ע\"א, דגם אם החיות אינו ניכר בלבו מ\"מ יכול להיות שיש"],[3601330632,"חיות בחוטם וכדפרש\"י שם, ושם בגמ' ובסוטה דמ\"ו ע\"ב דלענין חיותא הכל מודים דעיקר חיותא באפי' הוא כו', וי\"ל שזהו לפי שהחוטם הוא שער המוחין (וכ\"מ בגמ' שם), דכמו שהפה הוא שער הלב וזהו שהדבור הוא מהפה שבא מהבל הלב כו', כמו\"כ החוטם שער המוחין כו', וידוע דכללו' חיות הנפש הוא בהמוח שבראש וע\"כ עיקר חיותא באפי' הוא כו'. והנה מה שהחוטם הוא שער המוחין היינו בחי' עצמי' המוחין, שהרי הדבור הוא ג\"כ שער המוחין שכל התגלו' שכל היא ע\"י הדבור, רק שזהו חיצוני' השכל וכידוע דשכל גלוי הוא מחיצוני' החכ' כו', וא\"כ מה שהחוטם הוא שער המוחין היינו בחי' עצמו' המוחין כו'. וכנודע ההפרש בין השפעת השכל להשפעת הטפה דהשפעת השכל הוא רק הארה לבד, ובהטפה נמשך עצמות המוחין ממש להוליד בדומה לו כו', כמו\"כ הוא ההפרש בין הפה והחוטם, דהפה הוא כלי לגילוי בחי' חיצוני' הנפש וחיצוני' החכ' כו', והחוטם הוא שער עצמי' המוחין דשם קישור וחבור עצם הנשמה ממש כו'. אמנם ההמשכה משם יש בזה ב' מדרי' והן חיין וחיין דחיין כו', ובחי' חיין שבנקב הימני\nזהו בחי' או\"י, והיינו גילוי כללו' חיות הנפש להחיות את הגוף כו', וז\"ע הנשימה שהוא הוראת החיות כו', דכשם שהחיות שבלב הוא בבחי' דפיקא דהיינו רצו\"ש כו' כמ\"ש במ\"א הטעם ע\"ז ועמשית\"ל, והוא החיות שבא בבחי' או\"פ באברי הגוף שזהו מהלב דלבא פליג לכל שייפין כו', דהחיות מהמוח בא בלב בדם שבו והלב שולח הדם עם החיות לכל האברים שזהו החיות פנימי כו', כמו\"כ החיות שבחוטם הוא בבחי' נשימה ברצו\"ש לפי שהוא ג\"כ החיות שבא בהתגלות להחיות כו', רק שזהו החיות כללי מקור החיות דאו\"פ כו', וע\"כ כ\"ז שיש רוח חיים באפיו דהיינו שלא נסתלק לגמרי בעצם הנפש ממש יכולים להחזיר ולהמשיכו בגילוי כו'. אמנם נקב השמאלי הוא חיין דחיין שזהו מעצם הנשמה ממש בעצם התקשרותה בבחי' עצמו' המוחין כו' (וכמו השפעה עצמי' מעצמי' המוחין שנמשך בזה עצמו' הנשמה כו'), והוא בנקב השמאלי דוקא דהיינו מה שנמשך ע\"י או\"ח דוקא כו'. ויובן הענין למע' עפמשנת\"ל פ' ר\"ד בענין קוטרא עילאה שזהו בחי' קשר הא\"ס ע\"י בחי' עתיק שהוא העתקת העצמו' כו', ומה שנמשך מזה בעולמות הן\nבחי' אורות דאריך כו' כמשנת\"ל פרי\"ט, וזהו מה שנמשך מבחי' או\"י להיות בבחי' מקור לעולמות כו', ובאופן ההמשכה והגילוי יש בזה ב' אופנים, אם ההמשכה היא בחי' האו\"פ לבד, והוא מה שנמשך ע\"י העבודה שע\"פ טו\"ד כו' (שז\"ע הקרבנות בכלל כו'), או שההמשכה הוא גילוי המקיף ממש והוא ע\"י רעו\"ד כו' (שז\"ע הקטרת כו'), וכ\"ז הוא שנמשך מבחי' נקב הימני בבחי' או\"י, להיות דגם רעו\"ד היא עבודה שבס' והדרגה מפני שג\"ז הוא התעוררות הנשמה מצ\"ע רק שפועלת בנה\"ט בבחי' שינוי המהות כו' כנ\"ל. והנה החוטם הוא שער המוחין (לא לבחי' מקיפים דנפש כ\"א לבחי' המוחין כו'), ונת\"ל שזהו עצמו' המוחין והיינו בחי' מו\"ס כו', ובנקב הימני נמשך מבחי' חיצוני' דמו\"ס שבבחי' המשכה נעלמת כו', אמנם נקב השמאלי דבו חיין דחיין הוא מבחי' עצמי' מו\"ס, וכמ\"ש באד\"ר שם ומהא נוקבא אתער ונפיק רוחא ממו\"ס כו', ובביאור האדרא דהיינו רוחא דעתיקא דרך מו\"ס כו' (וכמ\"ש באד\"ר שם רוחא דעתיקא דעתיקין דנפיק ממו\"ס לנוקבא דחוטמא כו'), ושם שזהו בחי' אוירא דע\"ג קרומא והיינו בחי' עצמיות\nמו\"ס כו' וכמ\"ש במ\"א, וזהו דמנקב זה נפיק חיין דחיין היינו התגלו' בחי' א\"ס סדכ\"ס שסתום ונעלם בעצם כו'. וזהו"],[3601330633,"שנמשך ע\"י התשו' דוקא דבע\"ת משכין לי' בחילא יתיר בכח או\"ח דוקא כו', וכמארז\"ל דבמקום שבע\"ת עומדים צ\"ג אינם יכולים לעמוד דצ\"ג בעבודה שלהם גם בבחי' אה' בתענוגים א\"י לעמוד במקום בע\"ת כו', דזהו כלל גדול דצער ומרירות הנפש מגיע למע' מעונג הנפש, דגם בחי' עונג עצמי אינו מגיע בעצמו' הנפש כמו הצער והמרירות מההיפך כו', וכמ\"ש מן המיצר קראתי מן המיצר והדוחק דוקא מה שצר לו מאד מהריחוק מהאלקות ובפרט בחטאים ועוונות, וזה דוקא מגיע בעצם נקודת נפשו ומגיע למע' בפנימי' ועצמו' א\"ס כו'. וכמו עד\"מ לדלג חפירה גדולה שצ\"ל בכח עצמו' הנפש שזהו דוקא כאשר בורח מן המות ר\"ל כמו במלחמה וכה\"ג שאז מתגלה כח עצמו' הנפש לדלג כו', וכמו\"כ המיצר הגדול (דער ניט גוט) מהחטא ועון זהו דוקא אשר מביא ומגלה עצם הנשמה בבחינת הזזת כל עצמותה כו', וזהו דוקא שמגיע בפנימי' ועצמי' א\"ס כו', דכאשר מן המיצר קראתי אז ענני במרחב י\"ה בבחי' מרחב העצמי דא\"ס כו', וכמ\"ש ממעמקים קראתיך מבחי' עומק לעומק, דעומק ופנימי' הנפש מגיע בבחי' עומק ופנימי' א\"ס כו'.\n<b>ועוד</b> זאת שבכאן הרע נהפך לטוב והיינו רע גמור לא רק בירורי נוגה כ\"א שרע גמור נהפך לטוב ממש כו', דבתשובה זו הרי זדונות נעשות כזכיות כו', ונת\"ל פרט\"ז דכאשר דבר חריף וקיוהא נהפך למאכל טוב וערב הרי העריבות בזה יותר באין ערוך מהדבר הערב בעצם כו', והיינו דרע גמור כשנהפך לטוב ממש ה\"ז ריח חזק שמגיע בבחי' חוטמא דעתיק בחי' פנימי' עתיק ופנימי' ועצמי' מו\"ס כו'. והו\"ע שמן הטוב שלמע' משמן המנורה שהוא בחי' שמן משחת קדש שלמע' מהחכ' דהיינו בחי' ח\"ס, אבל הוא בחי' חיצוני' דח\"ס שבבחי' מקור לחכ' בחי' מקיף דאו\"י כו', אבל שמן הטוב הוא בחי' מוחא דעתיקא בחי' עצמי' ח\"ס בחי' מקיף דאו\"ח שסתום ונעלם בעצם כו', ומגיעים לזה דוקא ע\"י תשו' בבחי' או\"ח הבא מן הריחוק דאו\"ח חוזר לקדמותו כו'. וזהו דגבי משיח כתי' והריחו ביראת ה' דמורח ודאין כו', וידוע דמשיח הוא בחי' פנימי' עתיק כו', אמנם מה שדאין היינו בחי' החכ' דהרי כל דין ומשפט הוא מבחי' החכ' כו', וכתיב בו לא למראה עיניו ישפוט ולא למשמע אזניו כו', דהיינו לא בבחי' חו\"ב כ\"א\nמבחי' ח\"ס כו', ומה שמריח ודאין היינו בחי' עצמי' ח\"ס שבזה בחי' פנימי' עתיק ומגיעים לזה ע\"י התשו' דוקא, דא\"א להגיע לבחי' עצמו' ממש כ\"א בכח או\"ח דוקא כו'. וזהו דמשיחא אתא לאתבא צדיקייא בתיובתא דבכדי שצדיקים יזכו להגילוי דמשיח זהו ע\"י התשו' דוקא כו', והיינו לפי שזהו בחי' עצמו' א\"ס בחי' פנימי' עתיק כו', וא\"א להגיע לזה כ\"א בכח או\"ח דוקא כו', וזהו דבענן הקטרת דיו\"כ דוקא שז\"ע התשו' כתי' כי בענן אראה בעצמותי כו'. וזהו ב' המדרי' דח\"ס, בחי' חיצוני' ח\"ס בחי' מקיף דאו\"י שבבחי' מקור לחכ', והו\"ע שמן המנורה שנמשך ע\"י ריח הקטרת בחי' רעו\"ד שעי\"ז נעשה ג\"כ ביטול מהות הנה\"ב כו', אבל בחי' פנימי' ח\"ס זהו בחי' פנימי' עתיק והו\"ע שמן הטוב דעתיקא כו', ולכן להגיע לזה זהו דוקא ריח הקטרת דיו\"כ שהו\"ע התשו' שבאה מן המיצר דוקא בכח או\"ח כו', שבזה ממשיכים בחי' פנימי' ועצמי' א\"ס בחי' עצמי' מו\"ס שבזה בחי' פנימי' עתיק כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ויאמר ה' אל אברם לך לך, דהנה ידוע דאברם הוא אב רם שכל הנעלם מכל רעיון בחי' מו\"ס כו', אמנם בכדי להמשיך בחי' פנימי'"],[3601330634,"ועצמי' מו\"ס בחי' מוחא דעתיקא ממש כו', עז\"א לך לך שיגיע לשרשו ומקורו והיינו לשרש ומקור נשמתו בחי' מקיף דיחידה כו'. ועז\"א מארצך פי' מארציות וחומרי' וכנ\"ל דלהגיע לבחי' מקיף דיחידה בבחי' הזזה עצמי' זהו שבא מן המנגד בכח או\"ח דוקא כו', וזהו לך לך מארצך שההילוך יהי' מהארציות והחומריות שעי\"ז יגיע לבחי' שרש ומקור העצמי דנשמה כו'. וזהו ג\"כ מה שא' במדרש משל לצלוחית של אפופלסימון כו' שיהי' ריחה נודף דהיינו ריח הקטרת שהו\"ע ריח התשו' כו', ובאאע\"ה הי' זה ענין הנסיונות שעי\"ז בא לבחי' מקיף דיחידה כו', וזהו טלטל עצמך ממקום למקום להיות בחי' ההילוך אך שיהי' בכח או\"ח דהיינו מארצך דוקא כו'. ועי\"ז שמך מתגדל דענין הגדלת השם הוא המשכת בחי' שמו העצמי בחי' העלם העצמי דא\"ס כו' דעד שלא נבה\"ע הי' הוא ושמו לבד, ונת\"ל פרט\"ז שז\"ע שם א' שלמע' מהז' שמות והוא שרש בחי' ש' מ\"ה דתיקון כו', וי\"ל ג\"כ דהגדלת השם הוא שיהי' הגדלת השם מבחי' שמו העצמי כו'. וזהו ואגדלה שמך שזהו מעלה גדולה באברהם כו', וכ\"ז הוא ע\"י ההילוך בבחי' או\"ח\nכו'. וזהו ויאמר ה' אל אברם בחי' שכל הנעלם כו', לך לך לשרשך ומקורך העצמי והו\"ע טלטל עצמך כו', ויהי' ההילוך מארצך בכח או\"ח כו', ועי\"ז שמך מתגדל דבחי' שמו העצמי יאיר בגילוי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם קטרת דיוה\"כ בקה\"ק הו\"ע התשובה שממשיך מפנימיות הכתר, דהנה אי' באד\"ר מארי דחוטמא מחד נוקבא חיין ומחד נוקבא חיין דחיין, חוטם הוא כלי הנשמה, וזהו שהוא שער המוחין, והיינו עצמות המוחין (ופה שער לחיצוניות המוחין) דשם קישור עצם הנשמה, ומשם נמשך ב' המשכות, חיין הוא כללות החיות, וזהו הנשמה כמו הדפיקא בהאו\"פ, חיין דחיין עצמיות הנשמה. והדוגמא למעלה חיין מקיף דאו\"י חיות כללי דעולמות, והגילוי או שמאיר המקיף או שמוסיף אור בפנימי, וחיין דחיין מקיף דאו\"ח פנימיות עתיק ע\"י עצמיות מו\"ס בחי' אוירא, וזהו דבמקום שבע\"ת עומדים צ\"ג גם ברעו\"ד א\"י לעמוד, ועי\"ז גם זדונות נעשים זכיות, וזהו שמן משחת קדש למע' מחיצוניות ח\"ס, וז\"ע משיח דמורח ודאין עצמיות ח\"ס, וע\"כ אתא לאתבא צדיקייא בתיובתא. וזהו ויאמר ה' אל אברם אב רם דבכדי להגיע לעצמות ח\"ס לך לך מקיף דיחידה, ואגדלה שמך בחי' שם א' וי\"ל מבחי' שמו העצמי.</span>"],[3601330635,"<h3>בס\"ד. ש\"פ וירא, תרד\"ע</h3>\n<b>וה'</b> אמר המכסה אני מאברהם אשר אני עושה, ואברהם היו יהי' לגוי גדול ועצום כו', וצ\"ל מאחר שאו' אשר אני עושה ה\"ז גילוי דכל עשי' הוא התגלות דבר, וא\"כ מהו\"ע המכסה אני מה שייך כיסוי בדבר דעבידא לגלוי' כו'. ובמד\"ר אמרו ע\"ז הה\"ד סוד ה' ליראיו, וא\"מ מהו הסוד ה' שבזה מאחר דעבידא לגלוי' כו', ואם מפני ההעלם שקודם הגילוי הרי ידוע דההעלם שקודם להגילוי אינו העלם באמת"],[3601330636,"שה\"ה גילוי בעצם רק שהוא נעלם מהמקבלים שא\"ז העלם באמת, וא\"כ מהו\"ע המכסה אני כו'. ובמד\"ר פ' נשא אי' נתן האלקי' את העולם לאברהם שנא' וה' אמר המכסה אני מאברהם כו', וצ\"ל היכן מרומז במ\"ש וה' אמר המכסה אני שנתן את העולם לאברהם כו', וגם מהו\"ע שנתן לו את העולם כו'. גם צ\"ל דלכאו' מהו ההתחדשות בזה הלא כתיב והארץ נתן לבנ\"א, א\"כ מהו ההתחדשות שנתן האלקי' את העולם לאברהם כו'. גם צ\"ל מ\"ש ואברהם היו יהי' כו', דמשמעות הענין שהן שייכים זל\"ז דלפי שהמכסה אני מאברהם כו' ע\"כ ואברהם היו יהי' לגוי גדול, וצ\"ל מהו שייכות הענינים זל\"ז כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דבח\"ס יש ב' מדרי' חיצוני' ופנימי', דחיצוני' ח\"ס הוא בבחי' מקור לחכ' דאצי' כו', וג\"ז הוא למע' מבחי' החכ' והוא בבחי' מקיף כו' (דעם היותו בחי' פנימי ה\"ז מ\"מ בחי' מקיף והיינו מקיף דאו\"י כו'), ולכן ההמשכה היא ע\"י ריח הקטרת דוקא שעי\"ז נמשך בחי' שמן המנורה כו', דריח הוא בחי' מקיף כו', אמנם בחי' פנימי' ח\"ס הוא בחי' מוחא דעתיקא ממש בחי' פנימי' עתיק כו'. וזהו בחי' מקיף דאו\"ח שסתום ונעלם בעצם כו'. וההמשכה היא ע\"י הקטרת דיוה\"כ שהו\"ע התשו' כו'.\n<b>רכג)</b> וע\"פ כל הנ\"ל יובן איך שעיקר הממוצע בין המאציל אל הנאצלים (וכן בין עצמות א\"ס לנש\"י) הוא בחי' ח\"ס דוקא, וכמשנת\"ל פקצ\"ו דא\"א לומר דמה שהכתר הוא בחי' ממוצע זהו רק בהב' מדרי' דעתיק ואריך, שהרי עתיק הוא ממש בחי' תחתונה שבעצמות (מקצת מן העצם כו') שהוא בחי' עצמות כו', וע\"כ הוא בבחינת העתקה לגמרי מן הנאצלים גם מבחי' אריך כו', וכמו\"כ גם בחי' אריך שהוא ראש ומקור הנאצלים אינו ממהות הנאצלים שהן בחי' חכ' וא\"א הוא בחי' רצון כו' ואיך הוא בבחי' ממוצע כו', ובפרט שעיקר ענין הממוצע הוא שעי\"ז יהי' חבור ושייכות להנאצלים אל העצמות כו', ואיך יכול להיות זאת ע\"י ממוצע כזה דבחי' העליונה שבו היא בבחי' הבדלה לגמרי מן הנאצלים ובחי' תחתונה ג\"כ אינו כמהות הנאצלים כו'. אך עיקר הממוצע הוא בחי' ח\"ס שזהו בחי' חכ' כמהות הנאצלים והוא בבחי' מקור לחכ' דאצי' כו', ועם היותו בבחי' מקור מ\"מ ה\"ז בבחי' הבדלה מהחכ', דאבא יונק ממזלא בחי' שערות לבד שהן הארה דהארה כו', וכמשנת\"ל פ' ר\"ד ור\"ח, וזהו בחי' חיצוני' דח\"ס, אבל\nפנימי' דח\"ס הוא בחי' מוחא דעתיקא ממש שמלובש בזה בחי' פנימי' עתיק ממש כו' וכמשנת\"ל פר\"ג, וע\"כ בכדי להגיע לזה הוא בכח או\"ח דתשו' דוקא כו' וכמשנת\"ל פרכ\"ב, ובכללות הוא בחי' חכ' רק שהוא בבחי' חכ' מובדלת דלא בחכ' ידיעא כו', והיינו שאינו בחי' עצמו' שהרי העצמו' אינו בגדר חכ' כו', וגם לא בחי' הנאצלים שה\"ה מובדל מן החכ' כו', ויש בו מבחי' העצמו' ממש בבחי' הפנימי' והעצמי' שלו וגם יש בו מן הנאצלים שה\"ה בבחי' חכ' עכ\"פ כו'. וע\"כ הוא בבחי' ממוצע בין המאציל אל הנאצלי' ושעי\"ז יוכל להיות חבור הנאצלים עם העצמות, וכמו\"כ חבור וקישור נש\"י אל העצמו' כו', והיינו דבממוצע כזה להיותו בחי' חכ' עכ\"פ ביכולת לבא ולהגיע גם לבחי' העליונה שבו כו', ועי\"ז מגיע גם לבחי' העצמו' שלמע' מבחי' ממוצע כו'. והענין הוא דהנה כמשנת\"ל פקצ\"ח בהב' מדרי' שבחכ' כח ההפלאה וכח הירידה דהא בהא תלי' דלפי אופן ההפלאה לפי אופן כזה הוא כח הירידה כו', כמו\"כ הוא גם בהב' מדרי' שבח\"ס דע\"ה שבחי' הפנימי' מובדל בערך מן החיצוני'"],[3601330637,"שאינה בבחי' מקור לחכ' כו', מ\"מ לפעמים נמשך מבחי' הפנימי' ושנעשה עי\"ז שלימות יתרה בבחי' החכ' כו'. והענין הוא דהנה בחי' פנימי' ח\"ס זהו בחי' אוירא שע\"ג קרומא דחפי' על מוחא וכמ\"ש בע\"ח שער א\"א פ\"ג, שזהו בחי' מוח סתום מאד והוא בחי' מוחא דעתיקא שלמע' מבחי' מוחא דאריך (וזהו בחי' חיצוני' ופנימי' דמו\"ס כו'), דדעת דעתיק אחזי נהורא בהאי אוירא כו', וידוע דדעת הוא בחי' התקשרות ובחי' דעת דעתיק שבאוירא הוא שמקשר ומחבר בחי' ח\"ס (היינו חיצוני' ח\"ס) לבא לידי גילוי כו'. וכמו עד\"מ כשאדם משכיל ומחדש איזה השכלה חדשה זהו המשכה שנמשך ממקור השכל הנק' משכיל, ולפעמים אינו נופל לו שכל מלמע' מהשכל (והיינו שאין הגילוי מוכרח להיות כו', ובד\"כ כל הגילוים שבנפש אינם שמוכרחים הגילוים כו' וכמ\"ש במ\"א, וידוע דבכדי שיהי' גילוי השכל הוא ע\"י הרצון כו', אך לפעמים גם הרצון אינו מועיל דהגם שרוצה להתחכם מ\"מ אינו מתחכם כו', או שלא יש התגלות הרצון שגם גילוי הרצון אינו מוכרח, וא\"א להכריח את הרצון כו' וכמ\"ש במ\"א), הרי בהכרח לומר שיש\nדבר שלמע' מבחי' מקור השכל המשכיל שהוא המקשרו ומחברו לבא לידי גילוי בשכל כו' (וי\"ל שזהו בדרך הכרח שמכריח את כח המשכיל לבא לידי שכל כו', שז\"ע הדעת שהוא ההתקשרות בדרך הכרח כו', דכאשר יש לו רצון הרי ההתקשרות הוא מצד הרצון כו' (וג\"ז הוא ע\"י הדעת), אך עיקר ענין ההתקשרות שמצד הדעת הוא שמכריח א\"ע להתקשר כו' וכמ\"ש במ\"א, והיינו דמה שהדעת עושה התחברות כח המשכיל כו' א\"ז בבחי' מקור שהוא בהדרגה, כ\"א הוא כמו כח עליון שפועל שלא בהדרגה כו'). והנה כח המשכיל זהו הנק' ח\"ס והבחי' שלמע' מזה זהו בחי' אוירא שע\"ג קרומא כו', שהוא המקשר ומחבר בחי' ח\"ס לבא לידי גילוי כו', והו\"ע עסק התו' בדרך קב\"ע שגם שאין לו רצון הוא מכריח א\"ע, וכאשר מכריח עצמו ה\"ה נותן עצמו אל הלימוד כו', דאין הכוונה שההכרח הוא רק חיצוני וכאלו כפאו כו', כ\"א שמכריח עצמו ונותן א\"ע בכל עצמותו אל הלימוד כו' (שז\"ע הדעת שמקשר את העצמות ומשו\"ז שייך בזה הכרח כו' וכמ\"ש במ\"א), ועי\"ז ג\"כ באים גילוים מכח המשכיל, אך שרש הגילוים הם מלמע' מכח המשכיל והיינו\nדשרשם הוא מבחי' אוירא הנ\"ל וממילא הגילוים המה נעלים ביותר כו', וה\"ז ע\"ד ב' הכחות הנ\"ל שבחכ' כמו\"כ הוא בח\"ס דהתגלות מבחי' חיצוני' ח\"ס בא בכח בחי' הפנימי' וממילא יש בזה מבחי' הפנימי' שזהו שלימות יתירה בגילוי החכ' כו' (ובחכ' הגלוי' נת\"ל פקצ\"ח דכשלא יש כח ההפלאה גם כח הירידה הוא חסר כו', וכאן בח\"ס הוא שמוסיף שלימות כו'). אך העיקר מה שאפשר לבא גם להפנימי' דח\"ס א\"ז רק מה שהפנימי' מוסיף אור בהחיצוני' וההתגלות היא רק חיצוני' ח\"ס כו' (ובאמת גם בהנ\"ל הוא התגלות מבחי' הפנימי' כו'), כ\"א הכוונה שיהי' התגלות בחי' פנימי' ח\"ס ממש כו', וזהו בכח או\"ח דוקא.\n<span data-k=\"ks\"><b>קיצור.</b> ומכל הנ\"ל יובן דח\"ס הוא בחי' הממוצע, דחיצוניותו מקור לחכ, ופנימיותו הוא פנימיות עתיק ממש שסתום בעצם, ומ\"מ הוא חכ', והיינו שאינו עצמות ממש שה\"ה חכ', ואינו מהנאצלים שה\"ה סתום בעצם, ומ\"מ הוא כמהות הנאצלים בחי' חכ', וע\"כ יכולים לבוא לבחי' העצמיות דח\"ס, ועי\"ז להגיע לבחי העצמיות, והענין הוא דפנימיות מו\"ס הוא בחי' אוירא דעת הנעלם, והוא</span>"],[3601330638,"<b>המכריח</b> את כח המשכיל להשכיל, והו\"ע עסק התורה בקב\"ע שנותן עצמו לזה, וגילוי ההשכלות שרשם מבחי' אוירא, וגם דבכח או\"ח יכול להיות גילוי בחי' פנימיות ח\"ס.\n<b>רכד)</b> והענין הוא דהנה מ\"ש בזהר בענין כי עשית פלא כסויא ולבושא דנהורא דעתיקא, נת\"ל פקצ\"ב דבחי' עתיק להיות שאינו בבחי' אחיזה בכלי וה\"ה כמו אור בלא כלי ע\"כ אינו בבחי' העלם כ\"כ כו', ומתעלם ע\"י החכ' דוקא מפני שכל מדרי' חכ' ה\"ה בבחי' אחיזה בכלי כו', והנה הכיסוי דחכ' א\"ז כמו הלבוש שמכסה כ\"א מה שהתענוג נעשה בחי' חכ' כו', דפנימי' ועצמי' החכ' דהיינו בחי' פנימי' ח\"ס הוא בחי' התענוג העצמי שנעשה בחי' חכ' כו' וכמשנת\"ל פר\"ג, ובזה הוא מתעלם במה שנעשה בחי' חכ' כו', וממילא מובן דבחי' הכיסוי אין זה רק שמכסה ומעלים על איזה כח שלמע' ממנו, וכמו כל כח תחתון שמלביש להכח עליון ומעלים עליו כמו בעו\"ע וכה\"ג, שהן כחות מובדלים זמ\"ז ובזה שמלביש אותו הוא מעלים עליו כו', דההעלם הזה אינו העלם עצמי דהיינו לומר שהכח העליון בא בשינוי המהות ונעשה כח התחתון כ\"א מה שמתלבש בו כו', וממילא א\"ז עצמו' כח העליון כ\"א הארה ממנו כו', וכח התחתון שמעלים עליו א\"ז העלם גמור, דגם לאחר ההעלם מאיר הארת הכח העליון כו', משא\"כ בההעלם\nדחכ' שמעלים על התענוג אינו באופן כזה מאחר שענין ההעלם הוא שהתענוג עצמו הוא נעשה בחי' חכ' ובזה הוא מתעלם כו', הרי הכיסוי וההעלם הזה הוא עצמי, והיינו שזהו עצמי' התענוג ממש ונעשה בחי' חכ' ובזה מתעלם בחי' התענוג העצמי והוא בבחי' העלם גמור כו'. וזהו\"ע בחי' הסתימות דפנימי' ח\"ס שסתום ונעלם בעצם כו', וכמשנת\"ל פר\"ז דבחי' פנימי' חכ' סתימאה הוא בחי' מקיף דאו\"ח שסתום בעצם כו', דלכאו' א\"מ מאחר שזהו מה שמעלים ומכסה על בחי' עתיק (כפשטיות ל' הזהר וכמשנת\"ל פקצ\"ב שמכסה כו'), איך הוא בחי' סתום בעצם מאחר שזהו רק כמו לבוש המעלים כו'. וע\"פ הנ\"ל ניחא שא\"ז כמו לבוש כו', כ\"א שזהו העלם עצמי והיינו שזהו עצמי' עתיק ממש שנעשה בחי' ח\"ס ובזה דוקא הוא מתעלם כו', הרי בחי' ח\"ס היא כמו עתיק ממש בבחי' הסתימות שסתום בעצם כו'. והנה מבחי' הסתימה הזאת נמשך כח ההסתר ע\"ד ואוהבו שוחרו מוסר שמסתיר ומעלים האה' העצומה בבחי' הבן יקיר לי אפרים, דמים רבים לא יוכלו לכבות את האה' כו' וכתיב כי עזה כמות אה' דבחי' אהבתי אתכם אמר ה' כו',\nועכ\"ז מכסה האה' לגמרי בכח חכמתו ית' ומראה ההיפך כו', דתכלית הכוונה בזה הוא בכדי לתקן ולהטיב עי\"ז בהטבה יתירה כו'. וכידוע דפנימי' האה' מתגלה בההיפך דוקא, וכמו עד\"מ האב האוהב את בנו מצד הטבע שהיא אה' עצמי' דאה' זו ישנו בלבו בתמידות רק שהיא בהעלם כו', וכאשר הבן נופל לארץ או מתטנף וכדומה אזי ירגז ויכעס עליו האב מאד על אשר הושפל ונמאס כ\"כ ומייסר אותו ע\"ז, וכ\"ז הוא שהאה' הכריחה אותו לזה כי אם לא הי' אוהבו לא הי' איכפת לו כלל מה שנשפל כמו שלא יכעוס על בן חברו כו', רק מצד עוצם אהבתו אליו הוא מתרגז כו' מפני שנוגע הדבר ללבו כו', וכל שהבן יקר יותר יותר יגיע ללבו כו', הרי הגם שהחיצוני' הוא גבו' ורוגז הנה בזה דוקא הוא פנימי' עוז האה' כו'. ויובן בזה שהגבו' אינו כמו לבוש אל האה' שבאופן כזה הוא דוקא בהשפעה שמצד האה' כו', וכמו האב שמצד אהבתו לבנו ה\"ה משפיע לו"],[3601330639,"שצריך להעלים בזה האה' והחסד שלא יתגלה ביותר בכדי שתהי' ההשפעה לפ\"ע הבן מה שיוכל לקבל כו', וכן לפעמים צריך להעלים האה' אליו כו', שבזה הגבו' היא רק לבוש אל האה' כו', דבאמת הגבו' אינו גבו' אמית' שה\"ה רק להעלים בכדי שיהי' התגלות האה' באופן שתוכל להתקבל כו', וההעלם בזה אינו העלם גמור גם אם מעלים אהבתו ממנו כו', והאה' היא רק חיצוני' האה' כו'. משא\"כ ברוגז הנ\"ל ה\"ז גבו' ממש דהרי מתרגז ומתכעס בשעת מעשה שהוא בכעס עליו, אך סבת הכעס הוא האה' עצמי', הרי שעצם מהותה של הגבו' היא אה' לא שהיא רק לבוש אל האה' כ\"א עצם מהותה היא האה' ודוקא האה' עצמי' ממש, רק שבאה בציור הגבו' אבל עצם מהותה היא האה' עצמי' כו', ובהסיר החיצוני' מתגלה הפנימי', והוא מפני כי אדרבה הגבו' הזאת מביאה את האה' עצמי' בהתגלות דבלא זה ה\"ה בהעלם בלבו (ומה שמתגלה הוא רק הארה חיצוני' כו'), ובזה בא האה' עצמי' בהתגלות רק שבא בציור הגבו' וע\"כ בהסיר הציור החיצוני מתגלה הפנימי' כו', והיינו כאשר הבן מקבל זאת באה' ומתתקן עי\"ז דאז מתגלה פנימי' האה' באה' יתירה דבחי' אה' עצמי' ממש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> דהנה כיסוי דבחי' חכ' על בחי' עתיק נת' שזהו שהתענוג נעשה חכ', ולא כמו כח תחתון שמלביש ומעלים כח בבחי' לבוש לבד, כ\"א שנעשה חכ' וזהו ההעלם שהוא חכ', וא\"כ ה\"ז העלם עצמי, ומזה נמשך כח ההסתר, וכמו ואוהבו שחרו מוסר שהגבו' היא תוקף האהבה עצמיות שבא בציור הגבו' (ולבוש הגבו' הוא בהשפעה העלם בשביל הגילוי), וע\"כ כשהבן מקבל מוסר ומתתקן מתגלה האהבה עצמיות.</span>\n<b>רכה)</b> והדוגמא מזה יובן בענין הגלות בריבוי העלמות והסתרים ביותר שזהו משום דהבן יקיר לי אפרים באה' גדולה ועצומה ביותר בבחי' התקשרות עצמי' שז\"ע אהבתי אתכם כו', וכתיב ואוהב את יעקב, וידוע שזהו בבחי' עצמו' א\"ס שלמע' מבחי' תהו ותיקון (שהן שם בבחי' אחים כו', וכמ\"ש הלא אח עשו ליעקב דבהתגלות הרי תהו ותיקון מובדלים זמ\"ז לגמרי וא\"כ מה שהם אחים היינו בעצמות אוא\"ס כו' וכמ\"ש במ\"א, ובבחי' ומדרי' זו) הנה בבחי' הפנימי' והעצמי' ואוהב את יעקב כו', וע\"כ נוגע מאד הלכלוך שלהם שזהו מצד פנימי' האה' כו', ומשו\"ז הן כל ההעלמות וההסתרים מפני שנוגע בפנימי' כו', דבעצם מהותם הוא האה' עצמי' דוקא כו', וכמ\"ש הפרד\"ס ש\"ה פ\"ג בשם הבהיר המים הרו וילדו אפלה מורה כי עלת וסבת הגבו' שהיא אפלה היא החסד שהן המים, והיינו דסבת הגבו' שהוא ההסתר הגדול הוא האה' עצמי' כו'. והכח ההעלם הזה שרשו מח\"ס כמ\"ש הרמ\"ז ר\"פ פנחס, וי\"ל דהנה בחי' פנימי' ח\"ס זהו בחי' כשמן הטוב שהוא בחי' הטוב העצמי שלמע' באין ערוך מכל הגילוים כו', והוא\nבבחי' סתימות בעצם שאינו גם בבחי' מקור לגילוים כו', וע\"כ משם הוא דוקא כח ההעלם שהוא טוב בעצם ובהתגלות הוא בבחי' הסתר לגמרי, אבל תכליתו ופנימיותו והיינו עצם מהותו הוא עצם הטוב כו'. וע\"י העבודה בבחי' ההעלם הזה והיינו שגם בריבוי העלמות וההסתרים יהי' חזק בקיום התורה והמצות ולעמוד נגד כל מונע ששום דבר מהריבוי מניעות ועיכובים דזה\"ג לא ימנע אותו מעסק התו' וקיום המצות כו',"],[3601330640,"ובפרט ע\"י העבודה בההעלמות עצמן שיתהפכו לטוב, והיינו שהאדם ממתיק הגבו' שלו שהוא היצה\"ר שיתהפך לאלקו' כו', והוא שהתוקף והעוז דנה\"ב מתהפך לקדושה הן בתשו' בחילא יתיר שצר לו בנה\"ט שלו והוא בא לידי תשו' כו' שהצעקה בזה היא פנימי' ועצמי' ביותר כו' (עמשית\"ל), והן בבחי' תוקף האה' והרצוא ותוקף התענוג על אלקות כו', והו\"ע לבי ובשרי ירננו שהלב והבשר הגשמי מרנן בבחי' אתהפכא ממש כו', והוא שהנה\"ב אין לו שום טוב אחר כ\"א רק הטוב דאלקות ובזה הוא מתענג בעצם כו'. שעי\"ז מתגלה בחי' סתימות העצמי דבחי' עצמו' ח\"ס כו', והוא שבחי' פלא נעשה בבחי' אלף כו', וכמ\"ש ושאבתם מים בששון ות\"י ותקבלון אולפן חדת כו', והיינו שבחי' פלא דח\"ס יהי' לעתיד בבחי' אולפן ולימוד כו', שזהו לימוד חדש לגמרי, דהרי עכשיו כל ענין הלימוד הוא בהאור והגילוי לבד אבל העצם אינו בבחי' לימוד כו', ולעתיד יהי' עצמו' ח\"ס בבחי' לימוד כו', וזהו דוקא ע\"י ההסתר דגלות ששרשו מבחי' ח\"ס (דהסתר הזה אינו רק כמו ההגבלות בס' השתל' בס' המשכת האור שמתמעט ממדרי' למדרי'\nשהוא ג\"כ בחי' הסתר כו', וכן המסכים והפרסאות שבס' השתל' המעלימים ומסתירים כו', אבל זהו רק כמו הלבוש שמעלים את האור דמ\"מ הרי יש בזה קצת אור וגילוי כו', משא\"כ ההסתר דג' הוא חשך עצמי כו' ושרשו מבחי' סתום בעצם כו'), ועי\"ז יהי' גילוי בחי' עצמו' ח\"ס כו'. וכמו במ\"ת הי' צ\"ל תחלה גלות מצרים ומבו' בתו\"א ד\"ה וידבר אלקי' כו' וארא כו' שזהו לפי שהמשכת האור הוא בבחי' מטי ולא מטי דתחלה הוא בחי' לא מטי ואח\"כ בחי' מטי, דבחי' לא מטי הו\"ע הצמצום הראשון שהוא בחי' סילוק האור והעדרו כו', וכמ\"ש בד\"ה פתח אליהו דלכן נק' מקו\"פ שהוא בחי' העדר האור לגמרי שאינו ניכר האור מורגש אפי' בכח כו', שזהו התגברות בחי' החשך וההעלם על האור והגילוי כו', וכמו גולל אור מפני חשך כו' (והיינו שהחשך אינו רק העלם האור כ\"א הוא חשך בעצם וגולל אור מפני החשך הזה כו'), ואח\"כ גולל החשך מפני האור להיות בחי' הגילוי כו', והו\"ע והחיות רצו\"ש דמלמעלמ\"ט תחלה הוא ולא מטי כו' וכמ\"ש במ\"א, וכפי ערך השוב שהוא הגילוי כך הוא בחי' הרצוא בתחלה והיינו דכאשר\nההמשכה היא בחי' הארה לבד הנה הרצוא הוא בבחי' העלם האור לבד כו', וכאשר ההמשכה הוא התגלות אור עצמי הרצוא שבתחלה הוא ג\"כ בבחי' חשך והעלם בעצם כו' (והצמצום הראשון הגם דגילוי הקו שאח\"כ הוא רק הארה לבד כנודע, י\"ל מפני שהי' תחלת הגילוי בעולם קודם שהי' התהוות ההשתל' כו' הי' צ\"ל בבחי' העדר האור כו', או י\"ל שזהו בשביל המשכת בחי' פנימי' הקו כו', דע\"ה שמה שנתגלה הוא בחי' הארה לבד מ\"מ הרי הצמצום הי' בכרי שיהי' המשכת האור העצמי כו', וכמ\"ש בעה\"מ דתכלית הכוונה בהצמצום הוא בכדי שיהי' אח\"כ בחי' הגילוי כמו קוה\"צ כו', ומבו' במ\"א שזהו למע' הרבה מכמו שהי' אוא\"ס ממלא מקום החלל לפה\"צ כו', והו\"ע נתאווה הקב\"ה להיות לו דירה כו', שהוא גילוי בחי' עצמו' א\"ס ממש בבחי' פנימי' הקו כו', והוא ע\"י העבודה בבחי' ההעלם וכמו בעסק התו' בקבעומ\"ש כו', וכמ\"ש מזה באורך בדרוש יו\"ט של ר\"ה רס\"ו), ולכן הי' מתחלה זמן הגלות ושליטת מצרים מפני הסתלקות החיות למע' כו' (דבחי' סילוק הוא אינו העלם לבד והוא בחי' התגברות החשך כו' כנ\"ל, דעי\"ז הי'\nלמטה שליטת מצרים שהי' שעבוד קשה ביותר כנודע), ועי\"ז דוקא הי' גילוי מ\"ת כו'. וכמו\"כ גלות האחרון הוא בחי' ההסתר בכדי שיהי' הגילוי"],[3601330641,"דמשיח שזהו שיתגלה בחי' עדן עילאה סתימאה בחי' מוחא דעתיקא ממש שזהו בחי' עצמי' ח\"ס כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והדוגמא מזה הוא הסתר הגלות משום האהבה עצמיות דואוהב את יעקב, ושרשו ממו\"ס כשמן הטוב, טוב הסתום בעצם, מזה החשך עצמי דגלות, וע\"י העבודה בתו\"מ בזה\"ג, והעיקר באתהפכא דחשך, בתשו' דנה\"ב, ולבי ובשרי ירננו, שעי\"ז פלא נעשה אלף, אולפן חדת לימוד מהות אלקות, וכמו גלות מצרים הקדמה למ\"ת, דלא מטי הוא הצמצום סילוק האור לגמרי שאינו נרגש אפי' בכח, ועי\"ז מטי גילוי אור עצמי דתורה (והצמצום עיקר הכוונה להיות גילוי פנימיות הקו), וכן גלות האחרון להיות גילוי עדן עילאה סתימאה לעתיד.</span>\n<b>רכו)</b> וזהו מ\"ש בזהר פ' בלק ע\"פ כי עשית פלא כסויא ולבושא כו', ד\"א כי עשית פלא כי עשית אלף, והיינו שהפלא יהי' בבחי' אלף וגילוי שהפלא בעצמו יתגלה כו', וזהו ע\"י ההסתר שנעשה מהכסוי והפלא הזה ועי\"ז יהי' גילוי בחי' פלא עצמו כו', ויהי' הגילוי ביתר שאת וביתר עז מבמ\"ת וכמ\"ש כי עין בעין יראו בבחי' ראיית המהות ממש דבמ\"ת הי' רק שומעין את הנראה כו' שבחי' מהות הא\"ס הי' אצלם בבחי' שמיעה לבד כו', ולימוהמ\"ש יהי' בבחי' ראי' ממש כו', וכ\"ז הוא ע\"י העבודה עכשיו בההעלמות וההסתרים כו'. והענין הוא דהנה ידוע דירידת הנשמה למטה הוא רק לברר את הגוף ונה\"ב כו', דהרי הנשמה עצמה להיותה מבחי' עצמי' אלקו', וכידוע ההפרש בין כל הנבראים גם מלאכים העליונים לנשמות, דכל הנבראים שרש התהוותם הוא מבחי' חיצוני' הכלים וחיצוני' האור שבבחי' מקור לעולמות שזהו בחי' הארה לבד כו', ושרש הנשמות היא בבחי' פנימי' הכלים ועצמי' האור שלמע' מבחי' מקור כו', וע\"כ יש הפרש בעצם התהוותן דהנשמות הם בחי' אלקות ממש כו' וכמ\"ש במ\"א, ולכן הנשמה\nכמו שהיא למע' השגתה היא בבחי' השגת המהות ממש לא רק השגת המציאות לבד כו', וכמו שבאצי' שמושג מהות אלקות כנודע, והיינו לפי שאצי' הוא אלקות דבנבראים א\"א להיות גילוי המהות שלא יהיו אז במציאות נבראים כו', אבל אצי' להיותו אלקות מושג שם מהות אלקות כו', וכמו\"כ הנשמה להיותה אלקות השגתה היא בבחי' השגת המהות דהיינו ראיית המהות כו', וזהו שמקומה הוא בג\"ע דשם הוא בחי' מהות אלקות כו', דזהו ההפרש בין ג\"ע לעולמות דהעולמות הן מז\"ת שבאים בבחי' התלבשות כו', ובג\"ע מאיר ג\"ר שהוא גילוי המהות כו' וכמ\"ש במ\"א, וירדה למטה בכדי להראות גם להגוף ונה\"ב בחי' גילוי אוא\"ס, והוא ע\"י ההתבוננות בהתהוות יש מאין איך שכל מה שנתהווה הוא מכח אלקי המהווה אותו כי אין דבר עושה א\"ע ואינו חי מעצמו כ\"א מכח אלקי המהווה אותו ומחי' אותו כו', שזה יכול להיות גם בהשגת הנה\"ב רק שזהו בבחי' השגת המציאות לבד שהרי אינו רואה מהות האין האלקי המהווה כו', דאלמלא נתנה רשות לעין לראות לא הי' רואה את היש כלל כו' (דכ\"ה בראיית הנשמות הגבוהות למטה שראייתם\nמצד הנשמה ה\"ה רואין את האין האלקי כו'), רק שמשיג שהדבר הוא כך שהתהוותם הוא מהאין האלקי וצ\"ל ביטול היש לאין כו', דכ\"ז הוא בחי' השגת המציאות כו'. אמנם יש בזה יתרון מע' דע\"ה שהידיעה וההשגה בהאלקות הוא בבחי' ידיעת המציאות לבד אך עצם השגת הדבר"],[3601330642,"שכך הוא ה\"ז בבחי' ראי' ממש כו', שהרי מתאמת מאד איך שאין הדבר עושה א\"ע, וזה מתאמת ביותר למטה דוקא בהתאמתות חושיות שה\"ה נפסדים ורואה הפסד הדברים בכל עת כו', הרי בהכרח לו' שהם הווים כו', דכל דבר הנפסד בהכרח שאין קיומו מצ\"ע כו' ואין מציאותו מעצמו כו', וגם מובן דכל דבר יש ומציאות הרי בהכרח שהתהוותו הוא בדרך אין ערוך כי אא\"ל יש מיש אם לא שיהי' אין כו', והיינו שנתהוו דבר מלא דבר כו', דכ\"ז הוא למטה בבחי' ראי' חושי' ממש כו', וכמו\"כ בכל ענין בבחי' השגה אלקי' במוחש שהן מהדברים התחתונים דוקא, שמהמשל יודעים את הנמשל ביותר להיות שהמשל הוא נראה ונרגש מאד בבחי' ראי' ממש כו', וידוע דהמשל הוא הוא הנמשל כו', וע\"כ זהו דוקא הידיעה במוחש איך ומה הוא כו'. וזהו מ\"ש ומבשרי אחזה אלק' מבשרי הוא הנה\"ב דכאשר תזדכך להכיר את בוראה בהתהוות יש מאין וכה\"ג כנ\"ל, או' ע\"ז אחזה אלק' שהוא בבחי' ראיית המהות, רק שנק' אחזה שהוא תרגום של ראי' דהיינו רק השגה חושי' ולא ראי' חושי' ממש, שהרי אינו רואה ממש את המהות דאלקות רק ע\"י\nהתאמתות וראיית הנמשל בהמשל נעשה ידיעתו בהנמשל בבחי' השגה חושי' כו', אבל א\"ז השגה בבחי' ידיעת המציאות לבד כ\"א השגה חושי' ממש כאלו רואה בעיניו כו', כי למטה שרואה הפסדות כל הדברים כנ\"ל הנה ההשגה מתאמתת אצלו כאלו רואה בעיניו ממש כו', וזהו מבשרי אחזה אלק' דהנה\"ב כאשר מזדכך יש בו ההשגה אלקי' כאלו רואה כו', ועי\"ז בהנשמה הוא בבחי' ראיית המהות ממש מצד מהות הנשמה עצמה שהיא אלקות כו'. וזהו מ\"ש אתה הראת לדעת דהתגלות הנשמה למטה הוא רק להראות לעיני בשר הגופני איך שה' הוא אלקי' כו', וגם לדעת הוא ל' שבירה וכמו ויודע בהם את אנשי סוכות שעי\"ז נעשה השבירה דחומרי' הנה\"ב כו', דכאשר אצלו מתאמת ענין התהוות היש מאין ואחדות ה' וכן כל עניני אלקי בבחי' ראי' חושי' כו', ה\"ה מתבטל בעצם מהותו כו', וכמו האגוז כששוברים הקליפה מתגלה הפרי, כמו\"כ ע\"י שבירת הנה\"ב מתגלה הפרי הוא הנה\"א בבחי' ראיית המהות ממש כו', שהרי בנה\"ב הגם שהדבר מתאמת אצלו בבחי' ראי' חושי' ממש הרי כ\"ז הוא רק בהשגה לבד דהיינו השגה מוחשי' בענין האלקי אבל לא\nבבחי' ראי' ממש בעצם האלקות כו', ועי\"ז נעשה בהנשמה בחי' ראי' ממש במהות אלקות כו'. אמנם גם בהנשמה יהי' עי\"ז יתרון גדול לגבי כמו שהיתה בג\"ע שהי' בה ג\"כ ראיית המהות ה\"ז מ\"מ רק בבחי' ההארה לבד, דגם ג\"ר אינן בחי' עצמו' אוא\"ס כו' כנודע, וע\"י ירידתה למטה שפועלת להראות הנה\"ב להכיר את בוראה כו', עי\"ז בהנשמה הוא בחי' ראיית המהות בבחי' מהוע\"צ א\"ס והיינו בחי' פנימי' ח\"ס שזהו פנימי' עתיק כו' (והוא שהפלא נעשה אלף בבחי' לימוד אבל לא בבחי' לימוד דהשגה כ\"א בבחי' ראיית המהות כו', וזהו שלימוהמ\"ש לא ילמדו איש את רעהו שזה שייך בבחי' השגת המציאות אבל בראיית המהות אינו שייך לימוד כו' וכמ\"ש במ\"א, וזה יהי' הלימוד דמשיח שיראה בחי' מהות הדבר כו' וכמ\"ש במ\"א).\n<span data-k=\"ks\"><b>קיצור.</b> וזהו מ\"ש בזהר כי עשית אלף שפלא נעשה אלף, והענין דהנה הנשמה היא מפנימיות הכלים, וע\"כ היא אלקות בעצם, והשגתה למעלה הוא מהות אלקות, לכן מקומה בג\"ע בחי' אצי', וירדה למטה להראות להנה\"ב גילוי אוא\"ס, והוא בהתהוות היש מאין אלקי שמושג גם בנה\"ב ובהשגה מוחשית, וכן</span>"],[3601330643,"<b>בכל</b> השגה אלקית ממשל גשמי שבאמת המשל הוא הנמשל, וזהו מבשרי דהיינו הגשמי, אחזה אלק' דבנה\"ב הוא בבחי' השגה חושיות, ובנשמה ראיית המהות, וזהו הראת לדעת ל' שבירה דנה\"ב שעי\"ז מתגלה ראיית המהות דנשמה, וביותר מכמו שהיא בג\"ע שזהו ראיית מהות אלקות.\n<b>רכז)</b> וזהו כי עין בעין יראו ב' העינים הללו, הא' עין דמחזה הגוף ונה\"ב בהתבוננות התהוות יש מאין וכה\"ג בבחי' השגה חושי' כו' כנ\"ל, ועין הב' הוא עין וראיית הנשמה בבחי' ראיית המהות במהוע\"צ א\"ס ב\"ה כו', שע\"י העין דנה\"ב עי\"ז הוא בחי' העין והראי' דנה\"א כו'. וי\"ל דלעתיד יהי' בגוף בחי' ראיית המהות, וכידוע שלעתיד יהי' הגוף בחי' אוא\"ס הסובב והנשמה תקבל מהגוף כו', א\"כ צ\"ל שגם בהגוף יהי' בחי' ראיית המהות כו', וי\"ל עפמ\"ש במ\"א דראי' חושי' ה\"ז למע' מראי' השכל כו', וראי' חושי' שייכה בהגוף ונה\"ב דוקא כו', והנה\"א תקבל ראי' זו מהנה\"ב לאחר שמתברר ומזדכך ע\"י הנה\"א להיות בה השגה מוחשי' כנ\"ל כו', וכ\"ז הוא ע\"י בחי' ח\"ס שהיא בחי' חכ' וידיעה, ומ\"מ היא בחי' עצמו' א\"ס דהיינו בחי' פנימי' עתיק כו', ולהיות שהיא בבחי' כיסוי שבה בחי' עתיק מתעלם כו', והיא בבחי' העלם עצמי היינו בחי' סתום בעצם כו', ע\"כ מזה הוא דוקא בחי' ההעלם שלמטה כו', דמעתיק עצמו להיות שאינו בבחי' העלם כ\"כ כמשנת\"ל פקצ\"ב אא\"ל בחי' העלם כזה כו',\nכ\"א ע\"י שנעשה בחי' ח\"ס שהוא בחי' כיסוי לעתיק שבזה מתעלם כו' וההעלם הוא העלם עצמי כו' כמשנת\"ל פרכ\"ד, ע\"כ מזה דוקא הוא בחי' ההעלם שלמטה כו' שע\"י העבודה בההעלם הזה באים לבחי' פנימי' ועצמי' ח\"ס כו', וזהו שע\"י הממוצע דח\"ס דוקא באים הנשמות וכן הנאצלים לבחי' העליונה שבהממוצע כו', ועי\"ז באים ג\"כ לבחי' עצמו' א\"ס שלמע' מבחי' ממוצע, וכמ\"ש ולא ילמדו כו' כי כולם ידעו אותי אותי ממש וכמו ויקחו לי אותי אתם לוקחים כו', דאמיתי' הדבר הזה יהי' לעתיד כו'. והענין הוא דהנה כתיב בן פורת יוסף בן פורת עלי עין, ומבו' במ\"א דקאי על זמן ימוהמ\"ש ותחה\"מ דמ\"ש בן פורת יוסף קאי על זמן ימוהמ\"ש שיהי' בחי' תוס' וריבוי אור שע\"י הבירורים כו' כנ\"ל, ובן פורת עלי עין קאי על זמן תחה\"מ דאין דומה לך לתחה\"מ שיתעלו בבחי' עצמו' ממש, והיינו עלי עין למע' גם מבחי' עין בעין כו', דלימוהמ\"ש יהי' כי עין בעין כנ\"ל ובתחה\"מ יהי' עלי עין כו'. וי\"ל ענין עלי עין הו\"ע השגה כו' (ועמ\"ש הפנ\"י בפי' עלי עין ע\"ד חכם עדיף מנביא כו'), דהנה השגה דעכשיו היא\nבבחי' מציאות לבד דבמהות הדבר אינו שייך השגה כ\"א ראי' כו', וכידוע ההפרש בין ראי' לשמיעה כו', אך ההשגה דלעתיד ידוע שתהי' השגת המהות ממש וכמו ויבין כל יצור כי אתה יצרתו ויבין דוקא בבחי' השגה, וההשגה תהי' כי אתה יצרתו בבחי' המהות כו', וי\"ל דהנה חו\"ב שניהם מקורם מבחי' ח\"ס כנודע, ומבחי' חיצוני' ח\"ס הוא שהשגה היא בבחי' מציאות לבד ורק ראי' היא בבחי' המהות כו', אבל בבחי' פנימי' ח\"ס שם גם ההשגה היא בבחי' עצמו' ומהות הדבר, דלהיות שבכללות בחי' פנימי' ח\"ס הוא בחי' עצמות דבר גם ההשגה דשם היא בבחי' השגת המהות כו', ועכשיו אין אנו יודעים איך הוא השגת המהות כי יהי' בבחי' התחדשות כו' (רק מעין ציור בזה יכול להיות מענין השגה מוחשי' שנת\"ל). וזהו עלי עין כי יש מע' בהשגה על הראי' שהיא בבחי' תפיסא"],[3601330644,"בפנימי' יותר מהראי' כו', וכאשר ההשגה היא רק בבחי' מציאות לבד הרי מ\"מ הראי' שהיא במהות הדבר ה\"ז למע' מהשגה כו', אך כאשר גם ההשגה תהי' במהות הדבר תהי' למע' מבחי' הראי' כו', וזהו עלי עין למע' מבחי' עין כו', וזה יהי' בתחה\"מ דאין דומה לך כו', וכמ\"ש ונחי' לפניו לפניו ממש שתהי' השגה בבחי' מהוע\"צ כו', כי הנשמות יהיו בבחי' עצמי' וההשגה תהי' עצמי' כו', והוא שיתעלו הנשמות ויהיו בבחי' העליונה שבהממוצע דהיינו בחי' עצמות ח\"ס כו' (ובשרשו הוא בחי' העלם העצמי כו', והיינו מה שהעצמו' נושא הכל בעצמו כו'), ותהי' ההשגה במהוע\"צ א\"ס כו', והיינו אחר שיתעלו בימוהמ\"ש בבחי' פנימי' ועצמי' ח\"ס שתהי' ההשגה בבחי' השגת המהות דבחי' פנימיות ח\"ס, יתעלו בתחה\"מ שתהי' ההשגה בבחי' מהוע\"צ א\"ס כו', וזהו אין דומה לך לך ממש כו'. וידוע דהשגה הוא בחי' יש וכמ\"ש להנחיל אוהבי יש, הנה לעתיד תהי' בבחי' יש האמיתי דבחי' עצמות א\"ס כו' (וי\"ל דראי' היא בחי' אין אמיתי והשגה בחי' יש האמיתי כו') (וגם בחי' ראי' חושי' שנת\"ל י\"ל שתהי' בתחה\"מ דוקא\nכו'), וכ\"ז הוא ע\"י העבודה דעכשיו בבחינת ההעלם דמבשרי אחזה כו' בחי' השגה חושי' כנ\"ל, עי\"ז יהי' לעתיד בתחה\"מ השגת המהות ממש כו'. וזהו שח\"ס הוא עיקר הממוצע שעי\"ז יכול להיות חבור הנאצלים והנשמות עם המאציל ב\"ה שיכולים לבא לבחי' העליונה שבהממוצע, ועי\"ז באים לבחי' העצמו' בבחי' השגת המהות כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש וה' אמר המכסה אני מאברהם, דהכוונה שיהי' התגלות בחי' הכיסוי וההעלם כו', וזהו אשר אני עושה, דהנה עשי' ע\"ה שזה גילוי היינו רק התגלות הדבר, אבל בעצם ה\"ז בבחי' העלם לגמרי שהרי בעשי' אין בזה שום גילוי והוא בחי' העלם עצמי כו', ושרש הדבר הוא מבחי' הסתימות העצמי דעצמי' ח\"ס ובחי' העלם העצמי דא\"ס כו' כנ\"ל, ועז\"א המכסה אני שיתגלה בחי' כיסוי הזה כו'. דהנה אברהם הוא בחי' גילוי הקו כנודע ממ\"ש מי העיר ממזרח א\"ת העיר אלא האיר כו', ופי' המכסה אני מאברהם היינו שבהקו יהי' גילוי בחי' ההעלם העצמי דא\"ס כו', וזהו ג\"כ ענין סוד ה' ליראיו, דפי' סוד ה' היינו בחי' העלם העצמי כו' (ועמ\"ש בדרוש יו\"ט של ר\"ה רס\"ו בענין ואמת ה' כו'), שזהו באמת סוד סתום וחתום בעצם כו', ואברהם שהוא בחי' הגילוי כנ\"ל שהוא בחי' אור הקו כו' יתגלה בו בחי' סוד ה' הנ\"ל וזהו בבחי' פנימי' הקו כו', דמ\"ש מי העיר ממזרח זהו בחי' פנימי' הקו כו', וכנודע דחיצוני' הקו שרשו מבחי' מל' דא\"ס ופנימי' הקו הוא מבחי' ת\"ת הנעלם שז\"ע\nמזרח כו' וכמ\"ש במ\"א. וזהו ג\"כ מש\"א במד\"ר האלקי' נתן את העולם לאברהם שניתן לו ההעלם כו', וא\"ז מ\"ש והארץ נתן לבנ\"א דהיינו לברר בירורים מלמטה למע' כו', ומש\"א האלקי' נתן את העולם היינו בחי' העלם העצמי כו', וע\"י הבירורים דמלמטלמ\"ע ג\"כ מגיעים לבחי' העלם העצמי כו' כנ\"ל, ובאברהם הי' זה ע\"י הנסיונות כו', וכמשנת\"ל ספרכ\"ב בענין לך לך מארצך מבחי' החומרי' ובכח או\"ח כו', ועי\"ז המכסה אני שנתגלה לו בחי' העלם העצמי כו'. וז\"ש אח\"כ ואברהם היו יהי' לגוי גדול ועצום שע\"י התגלות בחי' העלם העצמי תהי' ההתפשטות בבחי' ריבוי עד אין שיעור כו', וכידוע בענין אנת הוא חד ולא בחושבן כו', וכמשנת\"ל (ד\"ה שיר המעלות) שע\"י העומק והפנימי' יותר באה ההתגלות ביותר כו', ומכ\"ש שע\"י התגלות העצמי יהי' הגילוי בריבוי עד אין קץ ושיעור כו',"],[3601330645,"וזהו שע\"י המכסה אני כו' עי\"ז ואברהם יהי' לגוי גדול ועצום וכמו ויעצמו במאד מאד כו', והיינו שע\"י התגלות העצמות יהי' ההתפשטות גדול ועצום מאד כו'. וזהו וה' אמר המכסה אני מאברהם כו', דבאברהם שהוא בחי' גילוי הקו יהי' התגלות בחי' סתימות העצמי דח\"ס ובחי' העלם העצמי דא\"ס כו', ואברהם היו יהי' לגוי גדול כו', שע\"י התגלות העלם העצמי יהי' ההתגלות בבחי' ריבוי עד אין שיעור כו', וזהו היו יהי' לגוי גדול ועצום כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו כי עין בעין עין דנה\"ב ועין דנה\"א, וי\"ל שגם בהגוף יהי' ראיית המהות, והו\"ע ראי' חושיות, והוא ע\"י העבודה בההסתר שזהו מפנימיות ח\"ס דוקא, ועי\"ז יתעלו להיות ידעו אותי בתחה\"מ, והו\"ע עלי עין, וי\"ל שזהו השגה שיש בזה יתרון על הראי' בתפיסת הענין, ויהי' לעתיד השגת המהות במהות הא\"ס, וזהו ואין דומה לך, ונחי' לפניו, וי\"ל ראי' באין האמיתי, והשגה ביש האמיתי, וי\"ל דעליית הנשמות יהי' בעצמות ח\"ס וההשגה תהי' במהות הא\"ס, וי\"ל דבימוהמ\"ש תהי' השגה במהות עצמות ח\"ס, ובתחה\"מ במהות הא\"ס, וזהו חבור המאציל עם הנאצלים ונשמות ע\"י ח\"ס. וזהו וה' אמר המכסה אני גילוי בחי' הכיסוי, מאברהם גילוי הקו, מי העיר ממזרח ת\"ת הנעלם, נתן האלקי' העולם לאברהם שניתן לו ההעלם, וזהו יהי' לגוי גדול ועצום גילוי העלם העצמי.</span>"],[3601330646,"<h3>בס\"ד. ש\"פ במדבר, עח\"ש, תרד\"ע</h3>\n<b>ואהי'</b> אצלו אמון ואהי' שעשועים יום יום משחקת לפניו כו', הנה זהו מא' התו' שאומרת ואהי' אצלו אמון כו', ופרש\"י אמון גדולה אצלו ל' האמונים עלי תולע, וכן פי' במצ\"ד הייתי מגודלת אצלו, והיינו שהתו' נתגדלה ונתאמנה אצל הקב\"ה, ולפ\"ז תי' אמון הוא ל' נפעל שהתו' נתאמנה כו', ובמד\"ר פ' בראשית פ\"א אי' א\"ת אמון אלא אומן התורה אומרת אני הייתי כלי אומנתו של הקב\"ה כו', ולפ\"ז אמון הוא ל' אומן ל' פועל שהקב\"ה פועל ע\"י התו' כו'. וצ\"ל מה הם ב' הענינים בתורה מה שהתורה נתגדלה ונתאמנה אצל הקב\"ה, ומה שהקב\"ה פועל ע\"י התורה כו'. גם צ\"ל מ\"ש ואהי' אצלו אמון דהול\"ל והייתי אצלו וכמש\"א הייתי מגודלת הייתי כלי אומנתו כו', מהו אומרו ואהי' שזהו ל' עתיד והוה כו'. ובזהר פ' אחרי דס\"ב ב' אי' דואהי' אצלו אמון ואהי' שעשועים זהו ע\"ד אהי' אשר אהי', וצ\"ל מה שייכות הב' פעמים אהי' לואהי' אצלו אמון ואהי' שעשועים כו'. והנה בפרטי' חשיב כאן ה' ענינים בתו' ואהי' אצלו אמון, ואהי' שעשועים יום יום, משחקת לפניו בכל עת, משחקת בתבל ארצו,\nושעשועי את בנ\"א, והוא כמו שהתו' ירדה ונמשכה בהה' מדרי' דכתר וחו\"ב וז\"א ומל' עד שירדה לבי\"ע. דמ\"ש ואהי' אצלו אמון היינו התו' כמו שהיא בכתר, ואהי' שעשועים יום יום הוא חו\"ב, משחקת לפניו בכל עת משחקת בתבל ארצו הן ז\"א ומל', ושעשועי את בנ\"א היינו כמו שירדה בבי\"ע כו', דכל הה' מדרי' הן בתענוג רק מ\"ש ואהי' אצלו אמון זהו כמו שהתו' היא בבחי' שעשועי' העצמי'"],[3601330647,"דא\"ס בחי' שעשועי המלך בעצמותו כו', והד' מדרי' הן בבחי' המשכות והארות התענוג כו', אמנם גם בחי' שעשועים העצמי' נמשכים בכל המדרי', וזהו כללות הענין מה שהתו' אומרת אני הייתי כלי אומנתו של הקב\"ה היינו המשכת בחי' שעשועים העצמיים בכל המדרי' דהשתל' כו'. ולהבין ענין ואהי' אצלו אמון, ואיך שהשעשועים העצמי' נמשכים בכל המדרי', ילה\"ק מ\"ש ה' אלקי אתה ארוממך אודה שמך כו', ואי' בזהר פ' בלק דקצ\"ג ע\"ב דה' אלקי אתה כולל כל הע\"ס דאצי' הוי' אלקי הן חו\"ב אתה הוא חסד ומל', ואו' ע\"ז ארוממך שצריכים לרומם כללות ההשתל' בעצמו' אוא\"ס כו', דהנה פסוק זה אמר ישעי' בנבואה כעין הקדמה להנבואה שא' אח\"כ ושמת מעיר לגל שזהו ביטול מל' דנוגה כו', ובכדי שיהי' ביטול מל' דנוגה בבחי' ביטול לגמרי זהו דוקא ע\"י המשכת אור חדש מעצמו' א\"ס כו', ובכדי שתהי' ההמשכה צ\"ל תחלה העלאה, וזהו ארוממך לרומם כללו' ההשתל' בעצמו' א\"ס ועי\"ז נמשך האור חדש, שז\"ע אודה שמך דאודה הוא בחי' המשכה וההמשכה הוא בשמך בבחי' המל' ועי\"ז יהי' ביטול מל' דנוגה כו'.\n<b>ואח\"כ</b> מבאר אופן ההמשכה דהאור חדש במ\"ש כי עשית פלא עצות מרחוק אמונת אומן, דהנה כי עשית פלא קאי על בחי' החכ' כו', ואי' בזהר שם כי עשית פלא כסויא ולבושא לאתלבשא נהורא סתימא עתיקא כו', והיינו כמו שהחכ' עולה לגבי הכתר ומעלמת את אור הכתר כו', וכמו שאנ\"ר דמי שהוא במוחין דגדלות ביכולתו להעלים את התענוג אפי' תענוג עצמי כו', וזהו מפני שהחכ' היא תענוג בעצם מהותה רק שבא במהות אחר בכח החכ' אבל באמת מהותו הוא כח התענוג, וע\"כ יש בכח החכ' להעלים על התענוג כו', וזהו בבחי' ח\"ס דלפעמים היא עולה ולפעמים יורדת והיינו דלפעמים היא מתעלמת ולפעמים יורדת להיות מקור על הגילוי כו', וכמו שהיא מתעלמת למע' ה\"ה מעלמת על הכתר כו', ואז החכ' נק' פלא דהרי הכתר הוא בחי' פלא וע\"כ כאשר החכ' מעלמת על הכתר גם היא נק' פלא כו'.\n<b>רכח)</b> עוד שם בזהר ד\"א כי עשית פלא כי עשית אלף, ומהו אלף הא תנינן אלף בית אלף בינה, אבל דיוקנא דאלף איהו תלת סטרין, ראשית דרזא עילאה דאדם קדמאה בגין דבדיוקנא דאלף אית תרין דרועין חד מכאן וחד מכאן וגופא באמצעיתא וכולא רזא חדא, ובג\"כ אלף חושבן אחד והיינו כי עשית פלא ע\"כ. ומש\"א ד\"א היינו משום דכאן מפרש מ\"ש כי עשית פלא באופן אחר ממה שפי' קודם, דהנה לפי' הראשון הרי מה שהחכ' נק' פלא הוא מפני שהיא כסויא ולבושא לאתלבשא לנהורא סתימא כו', דהיינו מפני שמלבשת ומעלמת אור הכתר כו', ויתפרש הענין בבחינת חכ' סתימאה שהיא בבחי' סתימות והעלם כו', ומתעלם בה אור הכתר כו', אבל א\"ז בבחי' החכ' מצ\"ע דאדרבה החכ' מצ\"ע היא בחי' גילוי וכמ\"ש אאלפך חכ' שהיא בבחי' אולפנא ולימוד דהיינו בחי' הגילוי כו', דזהו כל בחי' החכ' להיות בחי' גילוי אור כו'. וכמו בנפש הרי ראשית הגילוי הוא כח החכ' כו', דגילוי הוא בחי' או\"פ דוקא והוא כח החכ', דהרי תענוג הוא בבחי' העלם בנפש, וכידוע ההפרש בין תענוג לשמחה דשמחה הוא בגילוי והוא\nמן השגה דוקא, אבל תענוג הוא בהעלם כו', וכאשר התענוג מתגלה ה\"ז עושה עלי' וסילוק בהכחות, דזהו גם בתענוג המשיב את הנפש שהוא התענוג דאו\"י וכ\"ש בתענוג דאו\"ח כו', הרי א\"ז גילוי עדיין כו', ורצון הוא בבחי' מרוצה שהוא המשכה וגילוי כו', הרי אינו"],[3601330648,"או\"פ כו', וראשית הגילוי בבחי' או\"פ הוא כח החכ' כו'. וכמו\"כ הוא למע' דבחי' החכ' הוא בחי' גילוי כו', וכידוע שהחכ' נק' אור וכמ\"ש ויהי אור דא נהורא קדמאה כו' הרי החכ' מצ\"ע היא בחי' אור וגילוי כו', וכתי' והחכמה תחי' כו' שהחיות הוא בחי' גילוי דוקא כו', והיינו דהתחלת הע\"ס דאצי' הן מבחי' החכ' לפי שהוא ראשית הגילוי כו'. דענין האצי' הוא להיות גילוי אוא\"ס כו', וכמ\"ש בזהר דאצי' הע\"ס דאצי' הוא בגין דישתמודעון בי' כו', ובפרד\"ס כ' אצי' שמו של הא\"ס מורה על עצמותו כו' וכמ\"ש במ\"א, וע\"כ התחלת האצי' הוא מבחי' החכ' שהיא ראשית הגילוי כו'. וכמו\"כ גם בחי' ח\"ס הרי מצד שהיא בחי' חכ' ה\"ה בחי' מקור הגילוי כו', ולכן באמת התחלת אצי' הוא מח\"ס כו' וכמ\"ש הרמ\"ז פ' אמור דפ\"ח (וכ\"ה כללות ענין החכ' גם בשרשו ומקורו הראשון בעצמו' אוא\"ס שהו\"ע מה שבידיעת עצמו יודע כו', ה\"ז בבחי' גילוי לעצמותו עכ\"פ כו', דגילוי הידיעה לעצמותו הוא בכדי להיות הידיעה בעולמו' כו', דהרי לכאו' א\"מ מה נתחדש בידיעה זו בעצמותו שהרי לעצמותו ידוע גם קודם\nשנאצלה הידיעה הכלולה בעצמותו כו', מאחר שזהו רק מה שבידיעת עצמו יודע הרי כשנאצלה הידיעה היא רק לעצמו ובעצמותו הרי ידוע גם קודם שנאצלה כו'. אך הענין הוא דקודם שנאצלה הידיעה הי' הידיעה בהעלם בעצמותו ולא הי' אז גילוי ידיעה כלל כו', ונאצלה החכ' בבחי' התכללות בעצמותו להיות הידיעה בגילוי בעצמותו עכ\"פ בכדי שתהי' אצי' בחי' החכ' בחי' הידיעה בנשמות ובעולמות כו' ועמשנת\"ל פמ\"ז). הרי דבחי' החכ' הוא בחי' הגילוי כו', דבחי' כתר הוא בחי' העלם דעש\"ז נק' חשך להיותו בבחי' העלם אבל חכ' הוא בחי' אור וגילוי כו', וי\"ל דכתר וחכ' זהו אצי' בחי' חשך ואור כו', וכידוע שהחשך אינו רק העדר האור כ\"א היא בריאה בפ\"ע ולמע' מן האור וכמ\"ש יוצר אור ובורא חשך כו', י\"ל דבשרשן זהו בחי' כתר וחכ' שהו\"ע חשך ואור חומר וצורה כו' (וכמו\"כ הוא בעבודה דהביטול שמבחי' הכתר הוא הביטול שלמעלה מטו\"ד לגמרי וכמו ברעו\"ד שהוא בבחי' רצ\"פ כו' (וכן בענין אמונה פשוטה כו'), והביטול שמצד החכ' ה\"ז ביטול שמצד הידיעה כו', דע\"ה שזהו ביטול אמיתי לפי שא\"ז\nהביטול שמצד השגה שהוא ביטול היש בלבד, שהרי השגה היא רק בבחי' המציאות דאלקו' והיא העבודה דרוב הנשמות בהשגה והתבוננות באלקות שעי\"ז היא היציאה מן הישות כו', דבהעדר עבודה ה\"ה נמשך אחרי החומרי' והישות כו', וע\"י העבודה נעשה ביטול היש שנעשה בבחי' קירוב לאלקו' וחפץ באלקו' כו', והביטול דחכ' להיות שזהו מבחי' ראיית מהות אלקו' ה\"ז בבחי' ביטול אמיתי כו', מ\"מ ה\"ז ביטול שמצד הידיעה דוקא כו', וכמ\"ש זה אלי ואנוהו אני והוא דהביטול הוא בבחי' אני והוא חד כו', ומ\"מ זהו דוקא ע\"י שזה אלי בבחי' ידיעה כו', וכמשנת\"ל פל\"ח ופקס\"ג). וא\"כ מה שהחכ' נק' פלא א\"ז מצ\"ע רק מפני שמעלמת לאור הכתר כו', והנה לעיל פרכ\"ד נת' דהעלם זה שהחכ' מעלמת אור הכתר א\"ז כמו לבוש המעלים כ\"א מה שהעונג נעשה בחי' חכ' ובזה הוא מתעלם כו', וא\"כ ההעלם הוא בבחי' העלם עצמי ובבחי' סתום מצ\"ע כו', והיינו שהחכ' הוא במדרי' הכתר ממש שהיא בבחי' העלם בעצם כו', הנה בד\"כ העיקר הוא בבחי' ח\"ס (ועמשנת\"ל סד\"ה דרשו), וג\"ז ה\"ה בבחי' עליונה דח\"ס כמו שהיא מצד עצמו'\nהמאציל כו', אבל בבחי' תחתונה דח\"ס וכ\"ש בחי' חכ' הגלוי' דאצי' לא יתכן לקרות בשם פלא כו'. וכאן מפרש דהחכ' נק' פלא מצ\"ע דוקא, והכוונה דוקא בבחי' הגילוי והיינו"],[3601330649,"דבחי' הגילוי דחכ' נק' פלא, וז\"ש כי עשית פלא כי עשית אלף דבחי' אולפנא ולימוד דחכ' הוא בחי' פלא, ומפרש ע\"ז אלף בית אלף בינה שזהו בחי' הגילוי דחכ' שבא מיסוד אבא לבינה (וכמו עד\"מ נקודת ההשכלה שזהו בחי' שכל גלוי שבאה לידי השגה דבינה כו') ה\"ז מבחי' פלא דוקא כו'. ולכאו' א\"מ איך הוא פלא מאחר שהוא בחי' גילוי ואם הוא בבחי' פלא הרי פלא מורה על ההסתר ואיך יהי' מזה הגילוי ובבחי' המשכה אל הבינה כו', אך זהו שמבאר באומרו אבל דיוקנא דאל\"ף איהו תלת סטרין כו', דהנה ידוע דציור תמונת האל\"ף יש בו ב' יודי\"ן יו\"ד א' למע' ויו\"ד א' למטה וקו באמצע המחבר ב' היודי\"ן כו', והנה יו\"ד העליון הוא בחי' חכ' שבחכ' שמקבל מאור הכתר וכמ\"ש והחכ' מאין תמצא כו', והוא בחי' נקודה עילאה דחכ' כו', ויו\"ד התחתון הוא בחי' יסוד אבא והוא מה שהחכ' הוא בבחי' משפיע בבחי' נקודה אל הבינה כו', והיינו אלף בינה כו', והקו שבאמצע הוא ו\"ק דאבא והוא הקו שדומה לוא\"ו כו', ונמצא כל ציור תמונת האל\"ף מראשו לסופו הוא בבחי' החכ' רק שיו\"ד העליון בחכ' שבחכ'\nוהוי\"ו שהוא הקו הוא בו\"ק שבה והיו\"ד התחתון בחי' יסוד שבה כו', ועז\"א כי עשית פלא דבחי' החכ' כמו שהיא בבחי' אל\"ף דהיינו בחי' גילוי דוקא ה\"ה בבחי' פלא כו'. והענין הוא דהנה ידוע דחכ' הוא בחי' כח מ\"ה ומ\"ה הוא ש' הוי' במילוי אלפין וכמא' מלגאו איהו ש' מ\"ה כו', שזהו הוי' דאלפי\"ן והיינו דאל\"ף דחכ' הוא בחי' מ\"ה כו', ובחי' מ\"ה שבחכ' זהו בחי' פלא כו' (והיינו בחי' מ\"ה שבגילוי החכ' לא בחי' מ\"ה דחכ' שזהו בחי' עליונה שבחכ' וכמ\"ש במ\"א, כ\"א הכוונה על בחי' מ\"ה שבגילוי החכ' כו').\n<span data-k=\"ks\"><b>קיצור.</b> עו\"ש ד\"א כי עשית פלא כי עשית אלף, א\"ב אלף בינה, הנה חכ' היא ראשית הגילוי, גילוי הוא או\"פ, ותענוג הוא העלם, וחכ' גילוי ונק' אור וחיות, ואצי' שהוא גילוי ראשיתו חכ', גם ידיעת עצמו הוא הידיעה בעצמותו בכדי שתהי' ידיעה בעולמות, כתר וחכ' אצילות חשך ואור, ובעבודה כתר למעלה מטו\"ד וחכ' ביטול אמיתי שמצד הידיעה, ומפרש הזהר כאן דבחי' גילוי דחכ' אלף בינה, יסוד אבא הוא בחי' פלא, וזהו שהחכ' היא בחי' מ\"ה ש' הוי' באלפי\"ן, והציור דאלף ב' יודי\"ן וקו שהן חכ' שבחכ' ומדות שבחכ' ויסוד אבא והכל הוא בחי' פלא.</span>\n<b>רכט)</b> וביאור הענין ילהק\"ת ענין שם מ\"ה מהו, דהנה כללו' ענין ש' מ\"ה הוא לחבר שני הפכים כמו חו\"ג או משפיע ומקבל כו', דמשפיע ומקבל הן ג\"כ כמו הפכים זמ\"ז כנודע, וזהו דאדם בגימט' מ\"ה וידוע דאדם הוא בחי' התכללו' ההפכים, שזהו ההפרש בין האדם לכל הבע\"ח, וכמ\"ש הרמב\"ם בהשמונה פרקים שלו דכל הנמצאים יש להם פעל א' או ב' פעלים אבל האדם משתנה לכמה פעולות כו', הרי שהאדם כלול מכמה הפכים וכמשנת\"ל פקס\"ו, ולכן אדם בגימט' מ\"ה דענין ש' מ\"ה הוא לעשות התכללו' והתחברות ההפכים כו'. וזהו ג\"כ ענין מלגאו איהו ש' מ\"ה דאיהו אורח האצי' והיינו בחי' אור הקו שעושה ההתכללות בע\"ס דאצי' וכמא' אנת הוא דקשיר לון ומייחד לון כו', דהע\"ס הן מדרי' מובדלות זמ\"ז והן הפכים זמ\"ז כו' והקו הוא מייחד ומחבר אותן כו'. דהנה הקו בכלל נק' אורח האצי', וכמ\"ש בבה\"ז פ' וישלח במאה\"ז ע\"פ כי ישרים דרכי הוי' דהקו הוא כמשל הדרך הגדול הנמשך מאוא\"ס ב\"ה ויש דרכים קטנים שהוא ההמשכה לכל"],[3601330650,"ספי' בפרט כו', וכדאי' בע\"ח דהמשכת הקו הוא מהאוא\"ס שלפה\"צ והוא כעין צנור הנמשך מאוא\"ס כו', וכמו הצנור המקלח מים מהנהר דמהנהר עצמו א\"א למלאות הכלים מפני שהי' שוטף לגמרי, כ\"א ע\"י הצנור שבעברו בשטח הארץ ה\"ה ממלא הכלים הנמצאים סביביו, והוא ע\"י צנורות קטנים שנמשכים לכל כלי בפרט. וכמו\"כ הוא בדוגמא בבחי' הקו שיש צנורות פרטים שהן המשכות אורות פרטים וכמו אור החכ' נמשך בצנור מיוחד, ואור הבינה בצנור מיוחד כו' (ונר' שם דהצנורות פרטים הן מקורי האורות, וכמו המזלות דונוצר ונקה שהן מקורי חו\"ב כידוע ז\"ע הצנורות וי\"ל דזהו מש\"ש וכ\"ז בבחינת האורות וגם בבחי' הכלים כו', והיינו שהצנורות, הן מקור האורות והן למע' עדיין מהתלבשות בכלים כו', ואח\"כ היא ההמשכה וההתלבשות בהכלים שזהו עוד צמצום כו', ותמיד נמשך השפע ממקורי האורות אל האורות ומהאורות אל הכלים כו', ועמשנת\"ל פכ\"ט שיש ג' מדרי' באורות כו' הא' האור כמו שהוא במקורו טרם שמתגלה כו', הב' כמו שהוא מתגלה ממקורו כו', והג' כמו שמתלבש בהכלים כו', ולעיל פל\"א שהמדרי' הב'\nהיא הקו כו', ולפי המבו' כאן י\"ל שזהו הצנורות פרטים הנמשכים מן הקו כו'), והקו בכלל הוא אורח האצי' היינו בחי' הדרך והצנור הגדול שהוא למע' עדיין מבחי' התחלקות אורות פרטים לפי שהוא דבוק באוא\"ס שלפה\"צ כו', ע\"כ אין בו עדיין התחלקות אורות כו'. והגם שנת\"ל שם שהקו הוא בחי' התגלות הפרטים מהע\"ס הגנוזות כו' (דהקו עשוי מנקודות כו'), הרי נת' שם דבהקו מאיר בחי' פשיטות דהע\"ס הגנוזות ולכן הספי' שבו הן בבחי' בלי מ\"ה כו', וגם יש בו מרושם הא\"ס כו' וכמו שנת\"ל פכ\"ח, וז\"ש בבה\"ז דבהכרח הוא שיהי' צנורות קטנים שע\"י נמשך המים בהכלים כו', דמהצנור הגדול הגם שזהו צמצום לגבי הנהר, מ\"מ מפני שהמשכתו הוא מהנהר א\"א שיומשך ממנו בהכלים כו', והדוגמא מזה הוא בבחי' הקו שהוא הצנור הנמשך מאוא\"ס שלפה\"צ כמ\"ש בע\"ח, ה\"ה בבחי' פשיטות עדיין וא\"א להכלים דע\"ס לקבל האור מהקו עצמו כ\"א מהצנורות פרטים שהן מקורי האורות כו', וע\"כ הקו בכלל עושה בחי' התכללות הספי' כו', וז\"ע מלגאו איהו ש' מ\"ה דאיהו אורח האצי' דהיינו בחי' הקו בכלל כו'. והנה\nהפרד\"ס שע\"ד פ\"ו מבאר דמש\"כ מלגאו איהו כו', הוא האור העצמו' המתפשט בתוך הספי' וזהו מלגאו דוקא כו', ובפלח הרמון סוף שע\"ד כ' נקוט האי כללא בידך דבכ\"מ שנזכיר עצמו' וכלים יהי' העצמו' הוא הנשמה הפרטי' דהיינו אור הפנימי כו', לא שנרצה בו עצמו' אלק' ח\"ו כו', אמת כי העצם הנעלם מחי' את הכל והוא נשמת הנשמו' עכ\"ל (ומ\"ש העצם הנעלם נר' שהכוונה על עצם השם דהוא ושמו אחד ושמו בגימט' רצון כו' ועמ\"ש שם ספ\"ג, וא\"כ גם זה אינו עצמו' אלק' כו', וי\"ל שזהו בחי' הא\"ס הבל\"ג כו'), וא\"כ מלגאו איהו ש' מ\"ה לפי' הפרד\"ס הוא בחי' או\"פ המחי' את הכלי, אכן דוחק לפרש כן דא\"כ מהו\"ע דאיהו אורח האצי' הלא בכל כלי ודאי יש או\"פ המחי' את הכלי ומה נק' זה בשם אורח אצי' סתם כו', וגם הרי האו\"פ הן אורות פרטי' ול' אורח מורה על אורח ודרך אחד כו', ויש חילוק בין דרך א' או דרכים הרבה כו' (וכמ\"ש באד\"ר בתחלתו וההוא אורחא אתפרש לתרי\"ג ארחין כו', הרי יש הפרש גדול בין חד ארחא לכמו שמתפליג לתרי\"ג ארחין כו', ועמ\"ש באגה\"ק סי' ז'), וגם מדוע מתייחס זה\nלש' מ\"ה דוקא שהרי בפרטי השמות שהן פרטי האורות ש' ע\"ב בחכ' ושם ס\"ג בבינה כו', וא\"כ מהו אומרו ש' מ\"ה דוקא כו', דנר'"],[3601330651,"מזה דכללו' האור הוא ש' מ\"ה והיינו שהוא הממשיך להיות התכללו' הע\"ס (והיינו דלאחר שחשיב כל פרטי הספי' חסד דרועא ימינא שנכלל בזה גם האור כו', אומר מלגאו איהו ש' מ\"ה הכולל כולם כו'), וע\"י התכללות זו נמשך עליהם אור עליון יותר לאין קץ מהאו\"פ כו', וא\"כ אם נא' דהמשכה זו היא רק האו\"פ המחי' את הכלי הרי בחי' נשמה זו יש בכל כלי שלא מצד התכללותו עם שאר הע\"ס (וי\"ל דכללות האור נק' ש' מ\"ה ע\"ש בחי' הביטול והיינו שנמשך באופן כזה שיוכל לקבל ספי' ההפכי' כו' וכמשי\"ת, ועמ\"ש בלקו\"ת בהבי' דוהניף בענין מה שמו ומה שם בנו כו'). א\"ו משמע שהוא המשכת דבר מחודש כו', והיינו שממשיך מבחי' נשמה לנשמה, שאף גם העצמות שבתוך הכלי שהיא בחי' נשמה להכלי, הנה היא בערך בחי' כלי לגבי אותו האור ולכן נק' נשמה לנשמה כו', ועז\"א מלגאו איהו ש' מ\"ה דאיהו אורח אצי' שהאורח ודרך זה הוא לחבר העצמו' והכלים דאצי' עם בחי' הא\"ס שלמע' מהאצי' שהיא נשמתא לנשמתא כו', והיינו כמשנת\"ל בשם הפלח הרמון דנשמה לנשמה זהו בחי' העצם הנעלם והוא בחי' אוא\"ס הבל\"ג\nכו', ואורח האצי' הוא בחי' הקו שבו רושם הא\"ס כו', וע\"י הקו נמשך מבחי' האוא\"ס הבל\"ג גם בהאורות דאצי' (וע' משנת\"ל פכ\"ח) והו\"ע ש' מ\"ה כו'. ובד\"כ בחי' נשמה לנשמה הוא בחי' עתיק וכמ\"ש בזח\"ג דקנ\"ב, והוא בחי' עצמו' הקו שלמע' מכל בחי' התלבשות כו', והוא מ\"ש בע\"ח שיש כדוגמת עתיק לעילא מגולגלתא דא\"ק דנת' במ\"א שזהו בחי' ראשית הקו כו', והו\"ע ש' מ\"ה העושה התכללות הספי' כו', וזהו כללות ש' מ\"ה דענינו הוא לעשות התכללות כו' (ועמשי\"ת לקמן בעזה\"י בענין עצם ש' מ\"ה וההתגלות שלו שהוא בחי' הארת מ\"ה כו', והיינו מה שהקו בעצם הוא בחי' ש' מ\"ה והוא בחי' ש' מ\"ה דא\"ק ובחי' כדוגמת עתיק כו', ובחי' המשכת ש' מ\"ה בהאורות דאצי' להיות בהם ההתכללות כו'), וכ\"ה ראשית התגלות ש' מ\"ה היוצא ממצחא דא\"ק שהוא לעשות התכללות הספי' כו', שזהו עיקר ענין התיקון להיות התכללות ההפכים ע\"י ש' מ\"ה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויקדים ענין ש' מ\"ה שהוא לעשות התכללות ההפכים, וזהו מלגאו איהו ש' מ\"ה בחי' הקו, דאיהו אורח האצי' בחי' צנור הגדול הנמשך מאוא\"ס (וצנורות הפרטים הן מקורי האורות פרטים), דהנקודות שהן הספי' שבו הן בלי מ\"ה, ובו רושם הא\"ס, וע\"כ עושה ההתכללות באצי', ובפרדס שזהו האור שבכלים, ודוחק שה\"ה אורות פרטים ואורח משמע אחד כמו חד ארחא, גם הן עסמ\"ב וש' מ\"ה הוא בחי' נשמה לנשמה בחי' עתיק, והו\"ע כדוגמת דלעילא מא\"ק ראשית הקו, וזהו כל ענין ש' מ\"ה דתיקון שהו\"ע ההתכללות.</span>\n<b>רל)</b> והענין הוא דהנה ידוע דתהו ותיקון הן בחי' מ\"ה וב\"ן, דע\"ס דתהו הן ע\"ס דב\"ן ולכן נק' מלכין דתהו כמ\"ש ואלה המלכים אשר מלכו כו', דמלוכה הוא ש' ב\"ן כנודע והוא בחי' הישות והמציאות כו', דכל ענין המלוכה הוא בחי' היש ודבר בעצמו דוקא כו', והישות שלהם זה הי' סבת השבירה מפני שלא הי' להם קישור וחיבור זע\"ז כו', וז\"ע המא' דספ\"ד דעד דלא הווה מתקלא לא הוו משגיחין אפין באפין, והיינו שהיו זה תחת זה מפני שלא הי' להם קישור וחיבור אלא כאו\"א בבחי' יש ודבר בפ\"ע עד שלא היו סובלים זא\"ז כו', וממילא לא הי' אפ\"ל"],[3601330652,"ספי' האחרת כ\"א כאשר נתבטלה הספי' הקודמת כו', וכמו כאשר נמשך ספי' החסד לא נתנה מקום כלל למדת הגבו' ועוד שלא הי' יכולה לסבול כלל את מדת הגבו' כו', ולכן בהכרח שנשברה ונסתלקה מדת החסד בכדי שיהי' מדת הגבו' כו', וכן במדת הגבו' לגבי הת\"ת כו', וע\"כ נא' בהם וימת מלך פלוני ואח\"כ וימלוך פלוני משום דבשעה שמלך זה לא הי' באפשר שימלוך השני כו', וע\"כ אין מלכות נוגעת בחבירתה אפילו כמלא נימא, דמשום ענין הישות שז\"ע המלוכה א\"א שיהי' שניהם כו'. וכנראה בטבע בנ\"א החשובים שכל א' יש ודבר בפ\"ע בגדולה וחשיבות ביותר לא יוכל לבא לידי חבור ואחדות עם זולתו הגדול וחשוב כו', וכמו ב' מלכים או ב' שרים גדולים כל שהמה גדולים בעצם ביותר יותר לא יוכלו להתחבר ולהתאחד, לפי שכל א' תופס מקום בעצמו והוא יש גדול בעצמו דכולא כלא ממש חשיבי קמי' ואינו נותן מקום כלל לזולתו ולא יוכל לסבול כלל את זולתו כו', אבל בנ\"א הקטנים בערך כל שהמה קטנים בעצמם יותר יותר יוכלו להתחבר ולהתאחד יחד, לפי שכל א' אינו תופס מקום ויש כלל בעצמו ה\"ה נותן מקום\nלזולתו ובקל הוא נכנע ובטל להתכלל עם זולתו עם שהוא היפוכו (וכמו ב' עניים שפלים בטבעם ונמוכי רוח אע\"פ שהן ב' הפכים בטבעם יתחברו ויאהבו זא\"ז לבטל עצמו כל א' מפני חבירו, וכן ב' נרדפים שאוהבים זא\"ז והיינו מפני הביטול וההכנעה שבהם כו'). והדוגמא מזה בספי' דתהו דמצד תוקף הישות והתנשאו' והרוממו' יתירה שהי' בכל ספי' עד שהספי' זולתה לא הי' תופס מקום כלל להיות נותן לה מקום ג\"כ כו', וכמו ספי' החסד הי' בבחי' הרוממות ביותר (שז\"ע שהיתה בבחי' מלוכה כו') דרק אנא אמלוך, ולא הי' ספי' הגבו' תופס מקום ליתן לה ג\"כ מקום למלוך כו', ועוד זאת שלא הי' יכולה לסבול ספי' הגבו' לפי שהיא היפך מהותה לגמרי כו', וכ\"ז הוא מצד הישות כו', ומדות דתיקון הוא בבחי' הביטול לא בבחי' התנשאות והיינו שגם המדה ההפכי' תופס מקום ליתן לה ג\"כ מקום כו', וגם יש בהם הביטול וההכנעה להתאחד ולהתחבר עם המדה ההפכיות כו'. וביאור הענין הוא דהנה לכאו' הענינים סותרים זל\"ז דמאחר שבמדות דתהו הי' בהם ההתנשאו' שהמדה ההפכי' לא הי' תופס מקום כלל, א\"כ מהו\"ע\nשלא היו סובלים זא\"ז, דהרי דבר שאינו תופס מקום ה\"ה כאלו אינו, ואיך יתכן לו' בזה שאין יכול לסובלו שזהו מורה שהזולת תופס מקום דמשו\"ז לא יוכל לסובלו כו', ומאחר שלא הי' נותן מקום כלל לספי' האחרת (שז\"ע אנא אמלוך לבד כו') מפני מה לא היו סובלי' זא\"ז כו', ובאמת הי' כן בבחי' הפירוד דתהו שלא הי' סובלים זא\"ז לא רק מה שלא נתנו מקום זל\"ז דזה הי' עיקר סבת השבירה כו', וגם צ\"ל דמצינו היפך מהנ\"ל והוא דבחי' הרוממו' דוקא נותן מקום לכל דבר, שהרי אין לך דבר שאין לו מקום דהיינו שאין לו ערך ותפיסא בעצמו ותפיסא אצל הזולת כו' כמשנת\"ל פקס\"ח, וזה ביותר בבחי' הרוממו' דוקא, דמי שאינו ברוממו' ישנם דברים שהוא מחשב ותופסים אצלו מקום גדול ולהיפך יש דברים שאינם חשובים בעיניו כלל ואינם תופסים מקום אצלו (והיינו מפני שהחשיבות הוא בבחי' קירוב ושייכות אל הדבר וע\"כ במה שיש לו שייכות הוא חשוב בעיניו, ושאין לו שייכות לזה אינו חשוב בעיניו לדבר מה כו'), משא\"כ בהמרומם דשום דבר אינו חשוב בעיניו (בבחי' קירוב ושייכות אליו כו') והוא\nמובדל מהכל, אדרבה נותן מקום לכל דבר, דכל דבר יש לו ערך ותפיסא קצת כו'. וגם אנו מוצאים דטבע המרומם להיות נמשך אל השפל דוקא כו', דהרוממו' אינו מתגלה בדבר שהוא בבחי' מציאות ויש"],[3601330653,"כ\"א אל השפלים דוקא כו', וכמו בענין הרחמים הרי ידוע שזהו משום ב' סבות, הא' מצד הדעת וההרגשה שמרגיש את הזולת והחסרון שלו נוגע אליו ומשו\"ז הוא מרחם עליו, והוא הרחמים שבא מצד הקירוב דוקא שיש לו קירוב אל הזולת ויודע אותו ואת עניניו וכ\"ז נוגע אליו ומעורר הרחמים בלבו שמרחם עליו כו', והב' הוא מצד הרוממו' דוקא דמשו\"ז ה\"ה רואה שפלות הזולת כו', וכידוע דרחמים שייך על השפל דוקא דמי שהוא באיזה דרגא הרי אינו נופל עליו רחמים כ\"א על השפל, וזהו שהוא מרומם להיותו מובדל בערך ה\"ה רואה שפלות הזולת וע\"כ הוא מרחם עליו לפי שטבע המרומם להיות נמשך אל השפל דוקא כו'. וזה הטעם שגבי המלך ימצא ענין הרחמים יותר מבשרים הגדולים שזהו דוקא מצד הרוממות שבו, דהשרים להיות שאינם ברוממות כ\"כ בבחי' הבדלת הערך והיינו שיש להם קירוב ושייכות אל העם כו', אינם רואים כ\"כ שפלות הזולת וה\"ה עומד באיזה דרגא ולכן אין לו הרחמים עליו כו', אבל המלך להיותו מרומם בבחי' הבדלת הערך ה\"ה רואה השפלות של הזולת שאין לו שום דרגא כלל (והכל שפלים נגדו\nכו'), וע\"כ הוא מרחם עליו, שזהו מפני שהרוממות נמשך אל השפל דמה שאינו שפל כ\"א עומד באיזה דרגא אין בו התגלות הרוממו' כ\"א בהשפל דוקא הוא התגלות הרוממות כו' (דכמו\"כ הוא למע' דמרום וקדוש אשכון את דכא ושפל רוח דוקא כו' דמה שהוא בבחי' יש הרי אין אני והוא יכולים לדור כו', ובד\"כ כ\"ד שבבחי' מציאות א\"ז כלי לאוא\"ס כ\"א בחי' הביטול דוקא הוא כלי לגילוי אוא\"ס ב\"ה). הרי שהרוממות דוקא נותן מקום לכ\"ד וגם מתחבר עם כל דבר (דזהו מה שמרומם נמשך אל השפל כו'), וה\"ז להיפך ממשנת\"ל בספי' דתהו שלא נתנו מקום זל\"ז ולא היו סובלי' זא\"ז שכ\"ז הוא מצד הרוממו' כו' (ובענין הנ\"ל ג\"כ צ\"ל מאחר שהמרומם נותן מקום לכ\"ד וא\"כ איך הוא נמשך אל השפל שזהו שאינו עומד באיזה דרגא, ומאחר שנותן לו מקום וערך ה\"ה עומד באיזה דרגא כו'). אך כללו' ההפרש בהעדר תפיסת מקום שמצד הרוממו' הוא שאם רואה אותו בבחי' העדר המציאות באמת אז ה\"ה נמשך אליו כטבע המרומם להיות נמשך אל השפל כו', אבל כאשר רואה אותו בבחי' מציאות דבר והוא עוד במציאות הפכי כו' אינו יכול\nלסובלו כו', וזהו דבספי' דתהו שמצד הרוממו' שהי' בבחי' החסד עד\"מ לא הי' תופס מקום מדת הגבו', מ\"מ ה\"ז נראה גבי מדת החסד בבחי' מציאות דבר כו', ומצד הרוממות א\"א לסבול איזה מציאות (ובאמת הרי היש והמציאות אינו כלי אל הרוממות כו' כנ\"ל), וכ\"ש שהוא מציאות הפכי כו', אבל במדרי' התקון הוא שאינו רואה אותו למציאות דבר ומשו\"ז הוא דוקא נמשך אליו כו', וז\"ע מרום וקדוש אשכון את דכא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> דהנה תהו ותיקון הן מ\"ה וב\"ן, תהו מלוכה ב\"ן ישות ורוממות שלא היו נותנים מקום זל\"ז, ולא היו סובלים זא\"ז, ומשו\"ז הי' השבירה, ולכאורה מה שאינו נותן מקום הו\"ע העדר תפיסת מקום, ושאינו סובלו הוא שתופס מקום, וגם הרוממות נותן מקום וערך לכל דבר, וטבע המרומם להיות נמשך אל השפל, וכמו הרחמים שמצד הרוממות, וכמו רחמי המלך על הכל שכולם שפלים נגדו, מרום וקדוש אשכון את דכה, וכללות הענין דברוממות כאשר רואה השפל בהעדר המציאות ה\"ה נמשך איליו, וכשרואהו במציאות אינו יכול לסובלו, וזהו ההפרש בין תהו לתיקון.</span>"],[3601330654,"<h3>בס\"ד. ליל א' דחה\"ש, תרד\"ע</h3>\n<b>וידבר</b> אלקים את כל הדברים האלה כו', וצ\"ל מפני מה נא' במ\"ת ש' אלקים והלא ידוע דש' אלקים הוא מדת הצמצום וההעלם כו', ובמ\"ת הי' גילוי אוא\"ס וכמ\"ש וירד ה' על הר סיני שהי' גילוי אוא\"ס ממש למטה, וכתיב וכל העם רואים את הקולות רואין את הנשמע כו', ובנתינת התו' פתח באנכי ה' כו', שכ\"ז הוא גילוי אוא\"ס ממש כו', וא\"כ למה נא' כאן ש' אלקים דוקא כו'. ולהבין זה ילה\"ק משנת\"ל דספי' דתהו היו בבחי' פירוד שלא נתנו מקום זל\"ז ולא היו סובלים זא\"ז כו', ולכאו' הענינים סותרים זל\"ז דמאחר שהספי' האחרת לא הי' לה תפיסת מקום כלל איך לא היו יכולים לסבול כו', וגם מצינו להיפך שהמרומם דוקא נותן מקום לכל דבר וטבע המרומם להיות נמשך אל השפל כו'. ונת' דכאשר המרומם רואה את הזולת בבחי' העדר המציאות ה\"ה נמשך אליו, אבל כאשר רואה אותו בבחי' מציאות אז לא יוכל לסובלו כו'.\n<b>רלא)</b> והנה סבת הדבר מה שהזולת נראה למציאות לכאו' זהו מפני שהוא בבחי' מציאות בעצם כו', וכמו בספי' דתהו הרי גם מדת הגבו' הי' בבחי' מציאות מורגש כמו החסד כו', וע\"כ לא הי' יכולה החסד לסבול מציאות מדת הגבו' כו', אך באמת לא זהו עיקר הסבה שהרי גם במדות דתקון כל מדה וספי' היא בבחי' מציאו' דבר כו', וע\"ה שאינו בבחי' מציאות מורגש כמו בספי' דתהו מ\"מ ה\"ז בבחי' מציאות כו', דבכל המדרי' יש בחי' המציאות גם במדרי' שלפני אצי' כו'. וכידוע דמן הצמצום הראשון הי' התחלת ענין המציאות כו', וז\"ע עד שלא נבה\"ע כו' דהיינו קודם שהי' הצמצום כו', דבאוא\"ס שלפה\"צ לא יש ענין המציאות כלל, דהגם דגליף גליפו בטה\"ע והו\"ע שיער בעצמו בכח כו' א\"ז בבחי' מציאות כלל כו' וכמ\"ש במ\"א. אבל לאחה\"צ הי' התחלת ענין המציאות כו', וכ\"ש באצי' שהוא בחי' המציאות שגם האור הוא בחי' מציאות האור כו', וכ\"ש שהכלים הם בבחי' מציאות כו', וידוע דכל ענין המדות הן בחי' הרגש עצמו כו' וכמשנת\"ל פל\"ג ובכ\"ד, וע\"ה שהמדות למע' אינם כמו למטה וכמ\"ש במ\"א\nשהמדות למע' הן עצמי' לא מה שמתפעל בהדבר כו', הנה זהו בעצם המדות כמו שהן למע' מבחי' פעולה עדיין כו', אבל פעולת המדות דהיינו חיצוני' הכלים וחיצוני' האור ה\"ז בבחי' התפעלות כו', שהרי בהכלים נוגע מעשה התחתונים כו', וכידוע בענין עיני ה' המה משוטטים שהן המלאכים הממונים כו' שע\"י החטא נעשה כתם בהמלאך ומגיע הפגם בהכלים (בבחי' החיצוני' שלהם כו'), ומ\"ש גלוי וידוע כו' הוא בהאור, אבל בהכלים הוא בבחי' יודע וע\"י הכלים מגיע בהאור בבחי' ידוע כו' וכמ\"ש בתו\"א ד\"ה ארדה נא דרוה\"ב, ומאחר שמגיע שם פגם הרי מובן דהפעולה היא בבחי' התפעלות כו', וגם שהמדות לגבי למע' והוא מה שהחסד הוא בחי' האה' וגבו' בחי' היראה כו', והו\"ע רצו\"ש דמבו' במ\"א ששייך גם בע\"ס דאצי' (בבחי' הכלים עכ\"פ כו' ועמ\"ש בד\"ה דבר אל בנ\"י וישובו כו'), י\"ל שזהו ג\"כ בבחי' מורגש כו'. הרי שיש ענין המציאות והמורגש גם במדרי' התיקון כו', ובאמת הרי אין לך דבר שאין לו מקום כו' כנ\"ל, והגם דספי' דתיקון אינן בבחי' רוממות והתנשאות כו', הרי יש מדרי' שהן בבחי' רוממו' וכמו בחי' הכתר שהוא בבחי' רוממות דוקא, ומ\"מ"],[3601330655,"מרום וקדוש אשכון את דכא דוקא שאינו נראה לבחי' מציאות כו', וגם בחי' המל' שהיא בבחי' רוממו' והתנשאות דענין המלוכה הוא בבחי' רוממות דוקא כו', ומ\"מ ה\"ה בחי' מקור לבי\"ע ונמשך בבחי' חיות לכל העולמות ונבראים וכמ\"ש ואתה מחי' את כולם כו', ע\"ה שבי\"ע הן בבחי' מציאות ממש כו', הרי שאין הסבה מצד מציאות הזולת כו'. אך עיקר הסבה לזה הוא הרוממות, היינו מה שהמרומם הוא בבחי' מציאות מורגש בעצמו כו', דלהיותו בבחי' מציאות בעצמו ה\"ה רואה את הזולת ג\"כ בבחי' מציאות כו', וההעדר תפיסת מקום מה שכולא קמי' כלא כו' הוא רק מה שמבטל הכל, לא שהכל אינו בבחי' מציאות נגדו להיות בטל במציאות לגבי' ושהוא רואה אותו בבחי' העדר המציאות כו', כ\"א אדרבה כל דבר הוא בבחי' מציאות דבר נגדו והוא רואה אותו בבחי' מציאות שיש לו ערך ותפיסא כו' מאחר שהוא בעצמו בבחי' מציאות כו', אבל כאשר הרוממות הוא בבחי' בלי מציאות בעצמו אז באמת כל דבר כלא וכאין קמי' וכן נראה כל דבר בבחי' העדר המציאות כו'. ועיקר ההפרש בזה הוא בסבת הרוממות אם שהוא בבחי' רוממות\nוהתנשאות לבד, או שהוא מצד העצם שהו\"ע רוממות עצמי שבעצם הוא מרומם לא שמרומם עצמו כ\"א בעצם מהותו הוא מרומם ונעלה מאד וממילא בא הרוממות לגבי זולתו כו', והיינו שהרוממות אינו בבחי' מציאות ובבחי' מורגש כי אדרבה אינו בבחי' מציאות ובבחי' מורגש כלל, שז\"ע שהוא מרומם בעצם היינו שאינו בבחי' מציאות בעצמו, דכל שהוא בבחי' מציאות בעצמו אינו מרומם בעצם מהותו כו', ובד\"כ ענין המציאות הוא שמשו\"ז הוא מתרומם על הזולת (וגם בזה יש חילוקים בענין המציאות וכמשי\"ת), אבל רוממות עצמו אינו בבחי' מציאות דבר כו', וגם הלא ענין רוממות עצמו היינו שהוא למע' מגדר הזולת (ולמע' היינו שזהו למע' מהעולמו' כו') הרי אינו בבחי' מציאות כו', ובבחי' רוממות זו אין הזולת נראה בבחי' מציאות כלל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה מה שהזולת נראה למציאות אין זה מפני המציאות שלו, שהרי כ\"ה גם בתיקון, דמהצמצום הו\"ע המציאות גם לפני האצי' וכ\"ש בחי' או\"כ דאצי', וחיצוניות המדות הן בבחי' התפעלות, יודע וידוע, רק לפני הצמצום גם בחי' השערה בכח אינו בבחי' מציאות, ויש בחי' רוממות בתיקון בחי' הכתר, גם מל' בחי' רוממות ומחי' בחי' המציאות דבי\"ע, רק הסבה היא מה שהמרומם הוא מציאות בעצמו, להיות הרוממות הוא שמרומם עצמו, ע\"כ כל דבר תופס מקום ומציאות רק שמבטל אותו, ובבחי' רוממות עצמי שזהו לא בבחי' מציאות בעצמו כלל, אין הזולת נראה למציאות כלל וכלא ממש.</span>\n<b>רלב)</b> והענין למע' הוא דהנה הביטול דתיקון בכלל הוא הביטול בעצם המציאות, שז\"ע רך כקנה וקשה כארז, דמדות דתהו בכללות הן בבחי' המציאות ומדות דתיקון הן בכללות בבחי' ביטול המציאות כו', וע\"ה שיש בזה מדרי' שהן בבחי' המציאות (וכמשנת\"ל פרל\"א דגם מדות דתיקון הם בבחי' מציאות דבר כו'), מ\"מ בכללות הוא בבחי' ביטול בעצם כו', וכמו מי שהוא בטבע הרך שהוא בבחי' ביטול ושפלות בעצם המציאות שלו, דע\"ה שהוא מ\"מ בבחי' מציאות ושייך בו עבודה בבחי' ביטול היש כו' מ\"מ הוא בטל בעצם כו', כמו\"כ הוא במדרי' דתיקון דבעצם יש בזה הביטול בעצם המציאות כו'. אך לפי המבו' כאן בענין הרוממות יובן"],[3601330656,"זה בבחי' העצמות שהוא בבחי' רוממות עצמי להיותו עצמי כו', והרי אין בזה ענין המציאות כלל ח\"ו כו', אמנם בגילוים זהו בהאור שהוא בבחי' גילוי העצם וכלול בעצמו כו' שהרוממות בזה הוא בבחי' רוממות עצמי כו', וכמו המלך המרומם לבדו וכמו אשר מלך בטרם כל יצור נברא כו' שהו\"ע רוממות עצמי כו' (וי\"ל דבזה שייך ענין רוממות המעלה כו', דהרי הרוממות שלהיותו עצמי הרי אינו שייך בזה מע' לו' שהוא גבוה במעלתו מאחר שהוא עצמי ה\"ז למע' מגדר ענין העילוי כו', והרוממות שמצד היותו גילוי העצם וכלול בהעצם כו' בזה שייך ענין העילוי שמרומם במעלתו כו', וכמ\"ש בסש\"ב במשל זיו השמש כמו שהוא בגוף כדור השמש שהוא שם ביתר שאת וביתר עז דהיינו שהאור שם בריבוי ביותר ובאופן נעלה הרבה יותר כו' וכמ\"ש במ\"א, אבל ג\"ז הוא רוממות עצמי היינו שהוא מרומם בעצם מהותו ואינו בבחי' מציאות בעצמו כמו העצם כו', וכמש\"ש בסש\"ב שאינו עולה שם בשם אור וזיו כלל כו'). וכמו\"כ הוא גם בבחי' הרוממו' שהוא בבחי' התפשטות מן העצם דלהיותו מרומם בעצם ה\"ה בבחי' התפשטות הרוממו'\nעל הזולת כו', וכמ\"ש במ\"א בענין כתר מל' ולבוש מל', דכתר מל' הוא בבחי' רוממו' עצמי שמנושא ומרומם בעצם וכמו המלך הקדוש כו', ולבוש מל' הוא בחי' הרוממו' על העולמו' וכמ\"ש ה' מלך גאות לבש בבחי' רוממות והתנשאו' על עם כו', והוא בחי' מל' דא\"ס כמו שהוא לפה\"צ שעלה ברצונו אנא אמלוך כו', שזהו סבה על הרצה\"פ שעלה ברצונו להאציל ולברוא כו', משום שאין מלך בלא עם כו', דרצון זה דאנא אמלוך גם כמו שהוא לפה\"צ ה\"ז רק הארה ובחי' התפשטו' לבד כו', וכידוע דבעצמותו הוא בחי' אור השייך אל העולמות כו' וכמ\"ש במ\"א, אך זהו התפשטות הארה מבחי' הרוממות עצמי דעצמות א\"ס שאינו בגדר שייכות אל העולמות שזהו בבחי' רוממו' עצמי כנ\"ל, וכמו אשר מלך בטרם כו', שגם ע\"ז אמרו אין מלך בלא עם דפי' אין הן שיש מלך בלא עם כו', ומבחי' רוממות העצמות נמשך התפשטות הארה בחי' הרצון דאנא אמלוך כו', וכמו שאו' המלך המרומם לבדו והמתנשא כו' דמפני שהוא מרומם לבד בבחי' רוממות עצמי ע\"כ הוא מרומם ומתנשא מימות עולם כו', וע\"כ גם הרצון דאנא אמלוך הוא בבחי' רוממות\nעצמי להיותו התפשטות הארה מבחי' הרוממות בעצם כו', ועיקר ענין התנשאות על עם שייך לאחה\"צ, אבל בחי' מל' דא\"ס כמו שהוא לפה\"צ ה\"ז בחי' רוממו' עצמי עדיין שבא מבחי' הרוממו' בעצם כו' וכמ\"ש במ\"א (עמ\"ש בדרוש שמח תשמח רנ\"ז), ועוד זאת דבחי' הרצון דאנא אמלוך הוא שבא ע\"י התגלות דבחי' הרוממות בעצם דבחינת עצמות האור כו'. והענין הוא דהנה ידוע דבפרטי' יש בזה ג' מדרי' (בבחי' המלוכה הכלולה באוא\"ס לפה\"צ כו') הא' בחי' המלוכה כמו שהיא כלולה בעצמותו שאינו בבחי' המשכה וגילוי כו' (וזהו בחי' עצמות האור שנת\"ל), והב' מה שעלה ברצונו אנא אמלוך כו' (והוא בחי' התפשטות הארה מבחי' עצם האור כו'), והג' איך שמשו\"ז עלה ברצונו להאציל כו'. וכידוע שכל כח מתחלת הווייתו עד שמוכן להתגלות קודם שמתגלה עדיין יש בו ג' מדרי', וכמו מדת החסד יש בזה ג' מדרי', כמו שהיא נטוע ומושרש בנפש שאינו בבחי' המשכה כלל ולא בבחי' מקור אל הגילוי כו', וכמו שבא בבחי' התעוררות כללי כו', ואח\"כ ההשערה באיזה אופן תהי' ההטבה כו', ולמע' הו\"ע כי חפץ חסד הוא בחי'\nחפץ חסד ההיולי העצמי כו', וכמו שעלה ברצונו להטיב שזהו בחי' התעוררות הטבה כבי' רק שהיא בד\"כ עדיין כו', ואח\"ז ההשערה באיזה אופן"],[3601330657,"תהי' ההטבה שז\"ע שיער בעצמו בכח כו'. וכמו\"כ במדת המלוכה למע' הוא בחי' המלוכה כמו שהיא כלולה בעצמותו שאינו בבחי' המשכה כלל וכמו המלך הקדוש כו', ומה שעלה ברצונו כבי' אנא אמלוך שזהו בבחי' התעוררות כללי כו', ואח\"ז ההשערה בפרט שעלה ברצונו להאציל כו'. אמנם בכדי שמבחי' המלוכה כמו שהיא בעצמותו תהי' ההתעוררות דהרצון דאנא אמלוך זהו ע\"י ממוצע שיש ביניהם, והו\"ע התורה דכתי' בה בי מלכים ימלוכו כו', והיינו שע\"י התו' בא בהתגלות בחי' המלוכה הכלולה בעצמותו, וע\"ה שא\"ז שנעשה בבחי' מקור רק שמתגלה כמו שהוא בעצם כו', ועי\"ז נמצא מזה בחי' התפשטות הרוממות דאנא אמלוך כו', ולהיות שזהו ע\"י התגלות הרוממות בעצם ע\"כ גם זאת הוא בבחי' רוממות עצמי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והענין הוא דהנה תיקון בכלל הוא בחי' רך כקנה הנחת עצמותו, אמנם ענין הרוממות הוא בבחי' העצמות, רוממות עצמי, אך כמו\"כ בהאור הכלול בעצמותו עצם האור הוא בבחי' רוממות עצמי (וי\"ל בזה ג\"כ רוממות המעלה להיותו בחי' אור עכ\"פ), המלך המרומם לבדו, בחי' מלך בלא עם, וכן בחי' התפשטות האור בעצמותו בחי' הרצון דאנא אמלוך סבת הרצון להאציל, להיות שזהו התפשטות רוממות העצמי, ה\"ז ג\"כ בבחי' רוממות עצמי, כתר מל' ולבוש מל', ועוד שזהו ע\"י התגלות עצם האור, דהנה יש ג' מדרי' בחי' מל' הכלולה בעצמותו שאינו בבחי' המשכה, והיינו עצם האור, ועליית הרצון למלוכה, והשערה בכח, ומדרי' ד' היא התורה ממוצע שיהי' התגלות עצם המלוכה בכדי שיהי' עליית הרצון למלוכה, ע\"כ הוא בחי' רוממות עצמי.</span>\n<b>רלג)</b> אבל יש רוממות שאינו מצד רוממות עצמי כלל כ\"א מה שמרומם ומגביה א\"ע או שמגביהים אותו להיות בבחי' ממשלה ברוממות והתנשאות ואין בו רוממות עצמי מצד העצם כו', שזהו ההפרש בין רוממות המלך לרוממות השר, דרוממות המלך הוא מפני שיש בו ענין הרוממות בעצם שגם קודם שנעשה למלך ה\"ה מלך בעצם שיש בו ענין הרוממות בעצם כו', וה\"ה מרומם ומנושא בעצם מהותו שמובדל בערך מן העם כו', וכמו משכמו ולמעלה גבוה מכל העם כו' וכמ\"ש במ\"א, וכאשר נעשה מלך ה\"ז בחי' התפשטות והתגלות הרוממות להיות משתרר ומושל על עם ומדינה בהתפשטות והתנשאות גדולה כו', אבל כ\"ז הוא התפשטות מרוממות עצמותו כו', דכאשר נעשה מלך מתגלה בו בחי' הרוממו' שבעצמו ומזה בא התפשטות הרוממות כו' (ולכן לפ\"ע רוממות עצמו כ\"ה הרוממו' על עם כו' דזה שהוא מרומם בעצם ביותר (דהיינו שיש בו מבחי' המלוכה במדרי' גבוה יותר והוא מרומם ומנושא ביותר בעצם מהותו כו'), גם התפשטות הרוממות שלו הוא ביותר שמולך ומושל על מדינה גדולה וריבוי עם כו', שלא כ\"א יכול למלוך על מדינה\nגדולה כו' כ\"א כאשר יש בו מבחי' הרוממות ביותר כו', וכן התפשטות הרוממות עושה בחי' הרוממו' בעצם דכאשר מולך על מדינה גדולה וריבוי עם נעשה מרומם בעצם ביותר כו', דבאמת א\"ז בו בדרך התחדשות כ\"א שיש בו בחי' הרוממות בעצם רק שבא לידי גילוי לעצמו ע\"י התפשטות הרוממות כו' וכמ\"ש במ\"א). משא\"כ רוממות השר הוא שאין בו בחי' הרוממות בעצם ואינו מרומם ומנושא בעצם מהותו כו', רק שעשו אותו לשר היינו שהגביהו ורוממו אותו להיות שר ומושל"],[3601330658,"כו', וכמו גדל המלך את המן כו' שזהו רק מה שגדלוהו ורוממוהו אעפ\"י שלא הי' גדול בעצם אדרבה הי' הפחות שבהז' שרים כו', ובזה יכול להיות הרוממות בהתנשאות יתירה מאחר שאינו לפי העצם כלל רק שמגדלים ומנשאים ואח\"כ מנשא א\"ע כו', ע\"כ יכול להיות בזה הגדלה יתירה כו' (רק שסופו ליפול דמאחר שאין בזה ענין עצמי כלל ע\"כ סופו ליפול וכשהוא נופל ה\"ה נופל לגמרי, וכמו סר צלם מעליהם כו' דזהו לפי שאין בהם או\"פ רק מה שהמקיף מחזיק ומקיים אותם, ולכן בעת היותם הם בבחי' תוקף ביותר מחמת המקיף וכאשר סר צלם מעליהם ה\"ה מתבטלים לגמרי כו' וכמ\"ש במ\"א, וכמו המן הרשע שנפל אח\"כ בנפילה יתירה ונפל תפול שלא נשאר ממנו מאומה מפני שאין בו עצמי כלל כו', וזהו ההפרש בכלל בין נש\"י כו' דעם היות דכשהן נגבהין נגבהין עד לשמים וכשהן נופלין ר\"ל כו', מ\"מ נשאר בהם וכמו ואף גם זאת לא מאסתים כו' וכמו ואותך לא אעשה כלה כו', והיינו מפני שההגבהה והרוממות הוא מצד העצם כו' והיינו שיש בהם ענין עצמי שזה אינו מתבטל ח\"ו כו'), אבל רוממות זאת היא בבחי' ישות\nובבחי' מציאות מאד כו', שע\"י הרוממות נעשה בבחי' ישות גדולה ביותר עד שהכל קמי' כלא חשיבי ואינו נותן מקום לשום דבר והיינו שמבטל את הכל מצד הגיאות וההתנשאות שלו כו', וזה ג\"כ נוגע אל הרוממות שלו, דלהיות שאינו מרומם בעצם לכן אם לא יבטל את זולתו א\"א לו להיות בבחי' רוממות כ\"כ דבמה יתרומם על הזולת כו', וע\"כ לאחר שמתרומם ה\"ה מבטל הכל כו', שכ\"ז הוא רק מצד תוקף הישות והמציאות הן בתחלתו היינו תחלת ההתנשאות שהיא רק בבחי' ישות לבד, והן אח\"כ לבטל כל דבר כו', ומשו\"ז אינו נותן מקום וערך אל הזולת שבאם יתן לו ערך אינו יכול להתנשאות כו' (והיינו שהערך והמציאות של הזולת מגרע ומפחית ערכו ומציאותו כו'), וע\"כ כשמתנשא אינו נותן מקום לשום דבר כו', אך כ\"ז הוא רק בהתפשטות החיצונה, אבל באמת הוא להיפך שכל דבר תופס מקום אצלו היינו שרואה אותו למציאות דבר (ולכן ה\"ז מונע להתנשאות שלו אם יתן לו מקום כו' כנ\"ל), משום שבאמת הוא בבחי' מציאות לגבי' להיותו ג\"כ בבחי' מציאות כו', והמציאות של הזולת מנגד אליו כו', וכ\"ז הוא מפני\nשהרוממות שלו הוא בבחי' מציאות וישות כו'. משא\"כ ברוממות המלך שהרוממות מצד העצמות אין מציאות הזולת מנגד כלל. דהיינו מה שהזולת הוא אינו מגרע ומפחית מאומה, מפני שהרוממות שלו אינו משום ענין המציאות והישות כ\"א מפני שהוא מרומם בעצם, ע\"כ אין מציאות הזולת נוגע כלל ואינו מגרע ומפחית מאומה גם בהתפשטות הרוממות כו', והגם דהתפשטות הרוממות הוא בבחי' ישות וכנודע דכל מלוכה הוא בחי' יש כו' וכמ\"ש במ\"א, מ\"מ סיבת הישות אינו מצד המציאות בעצם כ\"א מצד הרוממות עצמי דרוממות עצמי הוא אדרבא בחי' העדר המציאות והישות לגמרי וכמשנת\"ל פרל\"א, וזו היא סיבת הישות דהתפשטות הרוממות כו', הרי גם הישות הזאת אינו בבחי' ישות כ\"א שבזה בא בחי' רוממות העצמי כו', ובאמת י\"ל דישות דמלוכה אין זה ענין הישות והמציאות כ\"א הוא תוקף הכח והעוז שזה בא מהתוקף דרוממות עצמי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה גם התנשאות על עם הוא התפשטות רוממות עצמי, ולכן לפ\"ע שמרומם בעצם הוא ההתפשטות על עם ומדינה, אבל יש שמרומם עצמו</span>"],[3601330659,"<b>ואין</b> בזה ענין עצמי כלל, והוא בתוקף רוממות יתירה (וכשנופל נופל לגמרי) ומבטל הכל, ובאמת הכל תופס מקום וערך אצלו, ובכוונה מבטלו בתוקף שלו מפני שמגרע מציאותו, משא\"כ ברוממות מצד העצם אין הזולת מגרע מציאותו, מאחר שאין הרוממות מצד המציאות כ\"א מצד העצם, והרי מלוכה היא בבחי' ישות זהו ג\"כ מצד רוממות העצמי ובאמת זהו תוקף הכח שבא מתוקף רוממות העצמות.\n<b>רלד)</b> והענין י\"ל עפמ\"ש בש\"א בענין וסוס אשר רכב כו', דסוס בגימ' ב\"פ ס\"ג שם ס\"ג שעולה למע' ושם ס\"ג היורד כו', דאות סמ\"ך מורה על הסתימות וההעלם דא\"ס כמו שהוא סתום מצ\"ע כו' וכמשנת\"ל פ' ר\"ה ור\"ז, והוא בחי' פלא עליון דהיינו בחי' הפלאת האור למע' בעצמותו בלתי יבוא למטה כלל כו', וכמו שבחי' פלא זה הוא למע' בעצמות, כמו\"כ גם בבואו למטה הוא סתום ונעלם והוא מ\"ש אתה אל מסתתר, ובחי' הסתר זה הוא באותיות הטבע כו' והוא ההסתר שאינו בהדרגא כלל כו' (ועמשנת\"ל פרכ\"ד ורכ\"ה), וכאשר ההסתר הזה נהפך לאור ה\"ז בחי' גילוי העצמות ממש כו' וכמשנת\"ל שם, וזהו ג\"כ מה שהתהוות המציאות הוא מבחי' העצמות דוקא כו', דכשם שכל ההעלמות וההסתרים הן מבחי' העלם העצמי הסתום בעצם כו', כמו\"כ התהוות היש והמציאות הוא מבחי' העצמות דוקא כו', ולכן הביטול שבעולמות עצמן הוא בבחי' אין עוד שלמע' יותר מהביטול שבאור שהוא בבחי' כלא חשיב לבד, ובמציאות היש הביטול הוא בבחי' אין עוד כלל כו' וכמ\"ש במ\"א ונז' לעיל פקע\"ח. וכמו\"כ בבחי' המל' דבחי'\nהישות והתוקף דמלוכה זהו מבחי' רוממות העצמות שלמע' מבחי' גילוי כו', וכמו ויתן עוז למלכו כו' וכמ\"ש ה' בעזך ישמח מלך כו', שזהו מה שנותנים לו התוקף דבחי' הרוממות עצמי כו', דבחי' התפשטות המלוכה שבא בבחי' רוממות על עם בתוקף הישות והמציאות זהו מבחי' הכח והעוז דבחי' מל' שלמע' בבחי' עצם הרוממות כו'. אבל בעצם מהותו ה\"ז בבחי' ביטול המציאות לגמרי כו', דכשם דבחי' הרוממות עצמי ה\"ז בתוקף גדול, דכל עצמי הוא בתוקף כו', ואינו בבחי' מציאות דבר כלל שז\"ע העצם שאינו בבחי' מציאות כו', כמו\"כ תוקף ההתנשאות בפועל להיות שזהו תוקף העצמות ה\"ז בבחי' ביטול המציאות לגמרי כו'. וכמו דוד המע\"ה בתוקף המלוכה שלו הי' בבחי' ביטול ושפלות לגמרי ונקרא דוד עבדי כו', וכתיב כי עני ואביון אני ואם לא שויתי ודוממתי כו' בבחי' תכלית השפלות והביטול כו', ואינם סותרים זל\"ז כלל דעם היות שהי' בבחי' ביטול לגמרי היתה המלוכה בתוקף ההתנשאות בבחי' תוקף העצמי כו', והגם שהי' בתוקף ההתנשאות הי' בעצם מהותו בבחי' ביטול במציאות לגמרי כו', וגם זאת שכל\nדבר נראה בבחי' העדר המציאות כו', דהרי באמת הכל בטל במציאות לגמרי כו', וכמו דלגבי רוממות המלך הכל מתבטל במציאות לגמרי שאין בו שום תפיסת מקום לעצמו ומתבטל בעצם מהותו כו' כנודע, וזהו דברוממות המלוכה הכל שפלים נגדו והכל אין ואפס נגדו שאין זה מצד התנשאות יתירה שבו שמבטל הכל, כ\"א שהן בעצמן (וכן גבי המלך) אינם תופסים מקום וערך כלל לגבי הרוממות שלו (דגם ההתפשטות הוא מבחי' רוממות העצמות כו' כנ\"ל), והן באמת בבחי' ביטול כל מציאותם כאלו אינם בבחי' מציאות כלל כו', וברוממות המלוכה נראים כמו האמת שרואין אותם בבחי' בלי מציאות כו'."],[3601330660,"<span data-k=\"ks\"><b>קיצור.</b> וע\"ד ש' ס\"ג שיש בו ב' מדרי' עולה ויורד, וכמו סמ\"ך סתום בעצם, ולפ\"ע זה הוא ההסתר לגמרי, וכמו התהוות היש הוא מהעצמות דוקא, ולכן ביטול היש הוא בבחי' אין עוד, וכמו\"כ תוקף המלוכה הוא מתוקף העצמות, ובאמת אינו בבחי' מציאות כלל, כמו העצמי שהוא בעצם התוקף ובלי מציאות, וכמו\"כ הזולת הוא בלי מציאות בעצמו שמתבטל בעצמו מפני הרוממות וכן גבי המרומם הוא בלי מציאות וערך כלל, שכן הוא באמת וברוממות המלוכה נראה האמת.</span>\n<b>רלה)</b> אך לכאו' סותר לזה מה שאנו רואין שהמרומם דוקא בבחי' רוממות אמיתי אינו מבטל שום דבר ואדרבה נותן מקום וערך לכל דבר כו', ובאמת אין לך דבר שאין לו מקום ואיך נאמר שאינו במציאות כלל וכן הוא נראה בהרוממות בבחי' בלי מציאות, דלפי הנ\"ל לכאו' הוא להיפך דכל דבר שנמצא ונתהווה יש לו מקום והרוממות דוקא נותן מקום לכל דבר כו'. אך הענין הוא דזה שיש לו מקום ונותן לו מקום אין זה שהדבר מצ\"ע יש לו מקום וערך כ\"א מה שנותנים לו ערך, דעם היות שאין לו שום ערך ותפיסא כלל וכלל לגבי הרוממות, ובאמת ה\"ה בטל במציאות לגמרי לגבי הרוממות כנ\"ל, מ\"מ טבע הרוממות האמיתי כאשר בא בבחי' התפשטות והתגלות שנותן מקום לכל דבר, וגם לדבר הקטן ביותר נותן לו ערך ומקום כמו לדבר הגדול כו', וזהו מפני שהתפשטות הרוממות הוא מבחי' רוממות העצמות לא בבחי' מציאות וישות כו' כנ\"ל, ע\"כ הוא נותן מקום לכל דבר הגם שמצ\"ע אין לו שום מקום וערך כלל כו', ודוקא בבחי' בהתפשטות הרוממות דכאשר הוא ברוממות עצמי בעצם אינו בגדר נתינת מקום לשום דבר כי\nמובדל בערך לגמרי כו', אבל כאשר הוא בהתפשטות הרוממות ה\"ה נותן מקום לכל דבר כו', ועם היות שנותן להם מקום וערך אין להם שום מקום וערך מצד עצמן כלל כו', דזה שנותן לו מקום אין זה שהדבר תופס מקום אצלו, דבאמת אין הדבר מצ\"ע תופס מקום כלל רק מה שהוא נותן לו מקום וערך, ולכן הגם שנותן לו מקום אין להדבר מקום מצ\"ע כלל כו', דכן הוא בידיעת הרוממות דמצ\"ע אין להם שום מקום כלל רק שהוא נותן להם מקום וערך כו'. וזהו ההפרש בין המרומם לשאינו מרומם, דמי שאינו מרומם ה\"ה נותן מקום וערך לדבר שיש לו מקום מצ\"ע היינו לדבר שתופס מקום אצלו, ועם הנתינות מקום נעשה הדבר בבחי' מציאות יותר להיות שזהו בבחי' קירוב הערך, וא\"כ בזה שנותן מקום להדבר הרי הדבר הוא אצלו בבחי' תפיסת מקום יותר דהיינו בחי' המציאות והערך יותר כו', משא\"כ המרומם נותן מקום לדבר שאין לו מקום וערך מצ\"ע דהיינו שמצ\"ע אין זה תופס מקום כלל, וע\"כ עם הנתינות מקום אין מ\"מ להדבר מקום מצ\"ע להיות שזהו בבחי' הבדלת הערך ואינו נתפס בזה, לכן הדבר מצ\"ע אין לו מקום וערך כלל\nכו' (ובזה מתורץ איך טבע המרומם להיות נמשך אל השפל מאחר שהוא נותן מקום להדבר א\"כ אינו שפל כו', דלפי הנ\"ל מובן להיות שזהו רק מה שהוא נותן לו מקום וערך אבל הדבר מצ\"ע אין לו מקום וערך כלל, א\"כ הרי מצ\"ע הוא שפל שלא בבחי' מציאות כלל וע\"כ טבע המרומם כו'). וי\"ל הענין למע' ע\"פ הידוע בענין דעת עליון דהדיעה העליונה היא שלמע' יש היינו בחי' יש האמיתי כו' ולמטה אין שהכל בבחי' אין ואפס ממש כו', ומבואר הענין במ\"א להיות מעצמות האוא\"ס א\"א שיהי' איזה מציאות דבר"],[3601330661,"והתהוות המציאות הוא רק ע\"י הצמצום כו', וכאשר לגבי אוא\"ס אין שום דבר מצמצם ומעלים כלל ומאיר האוא\"ס בגלוי לאחה\"צ כמו קודם הצמצום, לכן באמת העולמות והנבראים בטלים במציאות לגמרי שאינם בבחי' מציאות כלל כו', ולכאורה אינו מובן והלא מ\"מ נתהוו העולמות וכתיב בראשית ברא אלקי' כו' ואיך אינם במציאות כלל כו'. ולפי הנ\"ל י\"ל דבאמת כל העולמות אינם במציאות כלל, ומה שהן במציאות זהו רק מה שהאוא\"ס נותן להם מקום ומציאות אבל לא שהן בבחי' מציאות מצ\"ע כו', ועם היות שנותן להם מקום מ\"מ אין להם מקום מצ\"ע כו', וכך הוא בידיעתו ית' שאינם בבחי' מציאות כלל וכלל רק שהוא ית' נותן להם מקום וערך כו' (דהעולמות בידיעתם הוא שיש להם מקום מצ\"ע וה\"ה בבחי' מציאות כו', וזהו בבחי' ד\"ת שהוא בההארה השייכה אל העולמות שהיש תופס מקום כו' וכמ\"ש במ\"א, משא\"כ בידיעתו ית' מה שנתהוו הוא רק שהוא ית' נותן להם מקום דבאמת אינם במציאות כלל כו'). ועפ\"ז יש להמתיק מה שמבואר במ\"א בענין ה' אחד מלמטלמ\"ע דהנבראים לאחר שנתהוו ה\"ה כלולים בעצמותו וממילא\nאינם במציאות כו', ומבו' שם דמ\"מ נתהוו הנבראים דהרי שם אלקי' הוא אמת רק שהשם אלקי' כלול בעצמותו כו', ולפי הנ\"ל י\"ל ענין ההתכללות דשם אלקי' בעצמותו הוא שזהו רק מה שהאוא\"ס ב\"ה נותן מקום וערך אל הנבראים כו', והרי שם אלקי' אמת בידיעתו ית' שיש מציאות לנבראים וזהו ע\"י שם אלקי' דוקא, וכנ\"ל דבבחי' רוממות עצמי ממש הרי אינו בגדר נתינת מקום כלל רק בהתפשטות הרוממות כו', וז\"ע שם אלקי' שהוא כענין בחי' התפשטות הרוממות כו' (ועמ\"ש במ\"א בענין המלך הקדוש והמלך המשפט כו') ה\"ה נותן מקום וערך לנבראים כו', אך הוא כלול בעצמותו שזהו רק מה שהוא ית' נותן להם מקום לא שיש להם מציאות מצ\"ע דמצ\"ע אינם בבחי' מציאות כלל כו' (וביחוד דמלמעלמ\"ט הוא שהוי' הוא אלקי' והיינו שמציאות הנבראים הוא שהן אלקות כו' וביחוד דמלמטלמ\"ע הוא שאוא\"ס נותן מקום שזהו באמת בלי מקום ובלי מציאות כו').\n<b>ועפ\"ז</b> יובן מ\"ש וידבר אלקי' את כה\"ד כו' דהנה גילוי בחי' ד\"ע הוא שנתחדש במ\"ת דהרי עד מ\"ת הי' העבודה בבחי' ד\"ת וכמ\"ש וארא כו' באל שדי ושמי הוי' לא נודעתי להם, ופירש\"י לא ניכרתי להם במדת אמיתית שלי והו\"ע ואמת הוי' לעולם בחי' ד\"ע שהיא הדיעה האמיתית כו' ועל מ\"ת נא' לכן אמר לבנ\"י אני הוי' גילוי בחי' ד\"ע כו', והנה בד\"ע הגם שזהו גילוי שם הוי' הרי יש בזה ג\"כ שם אלקי' רק שזהו מה שאוא\"ס נותן מקום כו', וזהו אמיתית היחוד דהוי' אחד שהעולמות נבראו ומ\"מ ה\"ה בבחי' אחד לפי שהם כלולים בעצמותו ובטלים ומיוחדים כו', וזהו שנא' במ\"ת וידבר אלקי' ומ\"מ הי' גילוי אוא\"ס ממש למטה ואמר אנכי הוי' כו' גילוי שם הוי' ממש כו' דשם אלקי' אינו מסתיר ומאיר הגילוי דאוא\"ס כו', והשם אלקי' הוא כלול בעצמותו דהיינו שזהו רק מה שאוא\"ס נותן להם מקום וערך ובאמת מצ\"ע אין להם שום מקום כלל כו' והוא אמיתית היחוד דהוי' אחד כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולכאו' הרי המרומם נותן מקום לכל דבר, ונמשך אל השפל, הנה זהו שהמרומם בעצם נותן מקום וערך לדבר שאין לו מקום וערך מעצמו</span>"],[3601330662,"<b>ונמשך</b> איליו (ולכן לא נעשה בזה בבחי' מציאות, משא\"כ האינו מרומם בעצם נותן מקום לדבר שיש לו אצלו מקום, ובזה נראה אצלו במציאות יותר), ושייך זה רק בהתפשטות הרוממות, כי עצם הרוממות מובדל לגמרי, וז\"ע ד\"ע דכל\"ח והלא נבראו העולמות, זהו רק שהוא ית' נותן להם מקום ומצ\"ע אין להם מקום, וזהו ש' אלקים הכלול בעצמותו בחי' התפשטות הרוממות. וזהו וידבר אלקים גילוי בחי' ד\"ע שנתחדש במ\"ת."],[3601330663,"<h3>בס\"ד. ליל ב' דחה\"ש, תרד\"ע</h3>\n<b>אנכי</b> ה' אלקיך אשר הוצאתיך מאמ\"צ כו', וצ\"ל מ\"ש אשר הוצאתיך מאמ\"צ ולא נא' אשר בראתי שו\"א, והלא ברה\"ע הוא לכאו' פלא יותר מיצי\"מ דהאותות ומופתים דמצרים היו יש מיש וברה\"ע הוא יש מאין, וא\"כ הול\"ל אשר בראתי שו\"א כו'. גם צ\"ל מ\"ש אנכי ה' אלקיך הלא ידוע דהוי' ואלקים הן אורות וכלים דהוי' מקור האורות ואלקים מקור הכלים כו' וזה שייך בס' השתל' כו', אבל אנכי הוא בחי' עצמות אוא\"ס שלמע' מס' השתל' כו', ומאומרו אנכי ה' אלקיך משמע דבחי' אנכי הוא הוי' אלקיך כו'. ולהבין זה ילה\"ק משנת\"ל דברוממות יש ב' ענינים בחי' הרוממות שאינו בבחי' רוממות עצמי שאינו נותן מקום לשום דבר וזהו רק שמבטל כל דבר, דבאמת כל דבר יש לו מקום ומציאות בעצם שאינו בטל וגם בהמרומם הוא תופס מקום שמגרע ומפחית ערכו ומציאותו כו' רק שמצד הישות והתנשאות יתירה ה\"ה מבטל כל דבר כו', ויש בחי' הרוממות שהיא התפשטות והתגלות בחי' רוממות עצמי כו', דרוממות זו נותן מקום לכל דבר ועם היות שנותן מקום אין להדבר מקום מצ\"ע כי הוא בטל במציאות וכן הוא נראה בהרוממות כמו שהוא באמת שהדבר אין לו מקום מצ\"ע רק שהוא נותן לו מקום וערך כו'.\n<b>רלו)</b> וע\"פ הנ\"ל יובן בספי' דתהו דסיבת הדבר שהיו בבחי' מנגדים זל\"ז ולא היו סובלים זא\"ז זהו מצד שהרוממות הי' בבחי' ישות ובבחי' מציאות מורגש בעצמו, וא\"כ העדר תפיסת מקום דהספי' האחרת אין זה שאינה בבחי' מציאות רק שמבטל כל מה שזולתו מצד תוקף הישות וההתנשאות, אבל באמת ה\"ה בבחי' מציאות ונראה למציאות כו', וממילא ה\"ז מגרע ומפחית את המציאות שלו, וע\"כ הוא בבחי' מנגד אליו ואינו יכול לסובלו מצד עצם המציאות שלו, וכ\"ש כשהוא היפוכו כו'. והא בהא תליא דכאשר הרוממות היא בבחי' רוממות עצמי לא בבחי' מציאות בעצמו, ה\"ה נותן מקום לכל דבר והדבר בעצמו הוא בבחי' בלי מקום ומציאות כו' (דהיינו שבעצם הוא בבחי' בלתי המציאות דבטל במציאות לגמרי וכן הוא נראה בבחי' בלי מציאות כו'), וע\"כ הוא נמשך ומתחבר אליו כטבע המרומם להיות נמשך אל השפל כו', משא\"כ כאשר הרוממות היא בבחי' מורגש בעצמו בבחי' מציאות דבר אינו נותן מקום לשום דבר, אבל הדבר הוא בבחי'"],[3601330664,"מציאות ונראה למציאות כו', וע\"כ אינו יכול לסובלו כו'. אמנם עדיין צ\"ל הרי ספי' דתהו היו כאו\"א בבחי' מלוכה, וכמ\"ש ואלה המלכים אשר מלכו כו' ונקרא ז' מלכין דתהו כו', והרי נת\"ל פרל\"ג דבמלוכה הרי רוממות המלך הוא בבחי' רוממות עצמי ונותן מקום לכל דבר ונמשך אליו כו', והרי בספי' דתהו הי' ההיפך מזה לגמרי, ונת' שזה מפני שהי' בבחי' מלוכה שהו\"ע ההתנשאות והישות כו', ומאחר שהן בבחי' מלוכה הרי אדרבא הי' צ\"ל נותן מקום לכל דבר כו'. אך הענין יובן ע\"פ משנת\"ל פקכ\"ב שיש ב' מדרי' בבחי' כתר מל', דבד\"כ ענין הכתר הו\"ע ההתנשאות והרוממות כו', ויש בזה ב' מדרי' הא' הכתר מל' שמקבל מהעם והשרים כו' והוא ע\"י ההכתרה שמכתירים אותו בכתר מל', דענין ההכתרה הוא שמקבלים אותו למלך עליהם ומראים לו הביטול שמתבטלים לפניו בכריעה והשתחוואה המורה על בטול כל מהותם כו', ועי\"ז נעשה מלך עליהם בבחי' התנשאות והשתררות עליהם כו', והיינו שמתגלה בו כח ההתנשאות שיש בנפשו בהעלם כו', שהרי כאו\"א יש בו כח ההתנשאות כמו שיש בו כל הכחות והמדות כו', ויש\nחלוקים בנפשות דיכול להיות שאיזה מדה היא בו בתוקף יותר כו', והיינו שהיא בבחי' המשכה קצת מהנפש כו', ואין זה בבחי' המשכה נעלמת שזהו שנעשה מקור לגילוי כו' וכמ\"ש במ\"א, כ\"א זהו בהכחות עצמיים שאינם בבחי' מקור עדיין כו', רק שמ\"מ יכול להיות שכח א' יהי' בבחי' המשכה יותר ועלול יותר להתגלות כו', וי\"ל שזהו מה שיש בו העלולית להתגלות הכח הזה, וכמו מי שהוא איש הגבורה יש בו העלולית להיות התגלות כח ההתנשאות שבו כו', וגם יכול להיות שיש בו בחי' כח ההתנשאות יותר מצד שרשו שיש לו איזה שרש בבחי' מדת המלוכה יותר מזולתו כו'. אבל כ\"ז הוא ההתנשאות הנעשה ע\"י העם כו' ואין זה רוממות עצמי כו', דרוממות עצמי אינו מכח ההתנשאות לבד כ\"א מעצם הנשמה שהיא בבחי' הרוממות בעצם כו', וכמו המלך דעצם נשמתו הוא במדרי' גבוה ונעלה והוא נשמה כללית כו' וכמ\"ש במ\"א, אבל הרוממות שמכח ההתנשאות שבנפש זהו ההתנשאות הבאה מן העם כו', והב' הוא כתר מל' הבא לו בירושה מאבותיו שהכתר שהי' על ראש אביו מלביש גם הוא כו' והו\"ע כתר הולמתו כו', והיינו בחי'\nהתנשאות ורוממות עצמי שהוא מלך בעצם מצד עצם נשמתו וא\"צ להכתרה כלל, וכידוע דמלך בן מלך א\"צ להכתרה כו' (ובשלמה הי' מצד המחלוקת כו'), והיינו שא\"צ להביא (ארויסבריינגען) ההתנשאות שבו רק באה מאליו וממילא, דלהיותו מרומם בעצם היינו בעצם נשמתו ה\"ז בא מעצמו כשמגיע הזמן לזה כו', וגם אין העם צריכים להראות לו ביטולם אליו כי הכל בטלים אליו ממילא, והבטול הוא שאינם בבחי' מציאות כלל והוא בטול אמיתי בעצם מהותם ממש כו', והרוממות אינו בבחי' השתררות כ\"א שזהו התפשטות והתגלות מבחי' רוממות העצמי כו', והיינו שגם בההתפשטות נראה ונגלה בחי' רוממות העצמי שהוא מרומם בעצם, והכל יכירו שראוי למלוכה מצד עצמו כו', וכמו גבי שלמה דכתיב בו ויתן עליו הוד מלכות ופי' במצ\"ד שהכל ראו שראוי והגון הוא למלוכה מצ\"ע כו', ונת' שם שז\"ע הוד מל' והדר מל' דהוד מל' הוא מצד העצם והדר מל' הוא מצד העם וכמו ברוב עם הדרת מלך כו', ובד\"כ הן ב' מדרי' שבכתר דהוד מל' הוא מבחי' עתיק בחי' פנימי' הכתר כו', והדר מל' מבחי' א\"א השייך לנאצלים כו' ועז\"נ הוד\nוהדר לבשת כו' יעו\"ש. ונמצא דבמלוכה גופא יש ב' ענינים, ולפי\"ז י\"ל דספי' דתהו שהיו בבחי' מלוכה אין זה בבחי' רוממות עצמי"],[3601330665,"בעצם כו'. והענין הוא דהנה ידוע דספי' דתהו היו בבחי' הכתר בכלל עשר כתרים כו' וכמ\"ש בע\"ח, והוא שהע\"ס דעקודים שזהו בחי' העצמות של כל ספי' דהיינו בחי' הכתרים שבהם כו' הוא שיצא ונתגלה שז\"ע עשר נקודות דתהו כו', דבעקודים העשר אורות הם עקודים וכלולים בנקודה דכתר שבכתר כו' ובנקודים יצאו ונתגלו כו' וכמ\"ש במ\"א, ועשר כתרים אלו כמו שהן בבחי' עקודים ה\"ה לא בבחי' מציאות ניכרת וע\"כ ישכנו כולם יחד בבחי' התאחדות ממש כו', וכאשר יצאו ונתגלו שכל ספי' נעשה בבחי' ספי' נכרת והוא בבחי' תוקף האור דהיינו תוקף המציאות כו' לא היו סובלים זא\"ז כו'. ולפי הנ\"ל י\"ל דעם היות דספי' דתהו זהו שנתגלו הע\"ס דעקודים כמו שהן כו' (לא בבחי' העלם וגלוי כו'), מ\"מ זהו רק בחי' החיצוניות שלהם כו', וכמו ב' מדרי' שבכתר בחי' עתיק ואריך (שזהו בחי' הוד מל' והדר מל' כו'), וכמו\"כ בעקודים הע\"ס הן כמו בחי' פנימי' הכתר כו' וה\"ה בבחי' העדר המציאות כו', ועם היותם בחי' הכתר שהוא בחי' הרוממות כו' זהו כמו בחי' רוממות עצמי שאינו בבחי' מציאות כלל כו'\nוע\"כ הן בבחי' התאחדות כו', והע\"ס כמו שבאו בנקודות דתהו ה\"ז כמו בחי' חיצוניות הכתר שהוא בחי' התנשאות על הנאצלים וכמו והמתנשא מימות עולם כו', רק שבמדרי' דתקון גם בחי' התפשטוח הרוממות הוא מבחי' רוממות עצמי שזהו בבחי' בטול ונותן מקום כו' כנ\"ל פרל\"ג, אבל במדרי' דתהו (גם לגבי עקודים כו') בחי' ההתפשטות וההתגלות הוא כדבר בפ\"ע כו', דכשם דספי' דתהו הן בבחי' ענפין מתפרדין זמ\"ז כמו\"כ הן בבחי' פירוד לגבי שרשן ומקורן כו', והיינו שההתגלות הוא בחי' חיצונית הכתר לבד כו' ואין זה התפשטות דבחי' רוממות עצמי כו', והוא בבחי' מציאות דבר דכל ספי' היא בבחי' אנא אמלוך בבחי' רוממות והתנשאות שאינו נותן מקום להספי' האחרת וגם אינם סובלים זא\"ז כו', וזהו דספי' דתהו עם היותם בבחי' מלוכה לא נתנו מקום זל\"ז להיות שהרוממות אין בחי' התפשטות רוממות עצמי רק התגלות כח ההתנשאות לבד כו', ובתקון ע\"י שם מ\"ה נעשה ההתכללות בהספי' שנותנים מקום זל\"ז, ועוד זאת להיות מקבלים זמ\"ז שזהו תכלית השלימות והוא ע\"י ההמשכה מבחי' הוד מלכות כו' וכמשי\"ת.\n<span data-k=\"ks\"><b>קיצור.</b> ועפ\"ז יובן דספי' דתהו שהיו בבחי' מציאות, הנה הספי' האחרת תופס מקום וערך ומנגד לה שמגרע מציאותה, רק שמבטל ואינו נותן מקום, ולכאו' הלא מלוכה היא התפשטות רוממות עצמי וספי' דתהו היו בבחי' מלוכה, הענין דהנה נת' ב' ענינים בכתר מל' הא' שבא מן העם שמכתירין אותו, שעי\"ז מתגלה כח ההתנשאות שיש בכאו\"א, ובו היא בעלולית להתגלות, או שיש בו כח ההתנשאות יותר מבזולתו, והב' שהוא מלך בעצם מצד עצם נשמתו, וממילא התפשטות הרוממות, ולא בבחי' השתררות כ\"א התפשטות רוממות שנראה ונגלה בו שהוא מלך בעצם, והכל בטלים איליו בביטול אמיתי, והו\"ע בחי' פנימיות וחיצוניות שבכתר, ולפ\"ז י\"ל דספי' דתהו שהן התגלות דעקודים, הנה בעקודים הוא בחי' הפנימיות בבחי' העדר המציאות, ובתהו נתגלה בחי' החיצוניות, וההתגלות נפרד מן העצם, ע\"כ זהו רק התגלות כח ההתנשאות.</span>\n<b>רלז)</b> והנה יש עוד סיבה להפירוד דספי' דתהו מה שלא נתנו מקום זל\"ז מצד השלימות שכל ספי' היתה בבחי' שלימות בעצמה ולא רצתה לקבל"],[3601330666,"מהספי' האחרת, כי זה שצריך לקבל מזולתו הוא מצד שנחסר לו בעצם שלא יוכל להשלימו בעצמו, כ\"א ע\"י זולתו שיש בו אותו הדבר מה שאין בו, וא\"כ כל ספי' אינה בבחי' השלימות בעצמה ומקבלת השלימות מהספי' האחרת כו', והספי' דתהו היו בבחי' שלימות כאו\"א בפ\"ע ולא רצו להשפיע אל הספי' האחרת ולא לקבל שפעה ממנה כו' (ושרש סבת הדבר הוא הישות, דהנה בספי' דתקון להיותם בבחי' ביטול בעצם ע\"כ נמצא בהם דעת והרגש זה שאין בכ\"א השלימות בעצמה כ\"א ע\"י הספי' האחרת, וכמו מדת החסד עם היותה בחי' חסד יש בה ההרגש דחסד לבד אינו שלימות וצ\"ל ג\"כ גבו' כו', וכן במדת הגבו' ההרגש שצ\"ל ג\"כ חסד כו', והיינו מצד עצם הביטול לבחי' שלימות העצמית דעצמות א\"ס שיהי' בכל ההפכים דוקא כו', וע\"כ מקבלים השלימות זמ\"ז כו', וספי' דתהו שלא הי' בהם בחי' הביטול ע\"כ כל ספי' הסתפקה במציאותה שזה לבד הוא השלימות כו'). וה\"ז כענין דאי' במשנה דאבות האומר שלי שלי ושלך שלך ה\"ז מדת סדום, וידוע דאנשי סדום שרשם הי' מבחי' התהו דע\"כ היו בבחי' הפירוד שלא ליהנות ולא לקבל זמ\"ז\nכו', והיינו שכל א' רוצה להיות בבחי' השלימות בלתי יצטרך לקבל שפעו מזולתו וכן לא ישפיע לזולתו כו', דבזה הי' ארצם מובדל מכל הארצות בלתי צריכים לקבל שום טובה בפרנסה מארץ נכרי' וכן ביניהם לא הי' צריכים זל\"ז כו', אבל ה' בחכ' יסד ארץ שכל הארץ היא בבחי' התקון דחכ' שהוא היפך זה ממש, והוא שכל אקלים יקבל שפע פרנסה מארץ זולתו שזהו עיקר ענין המסחר כו', ונמצא כל ארץ מקבל מזולתה ומשפיע לזולתה כו', וזהו ואגודתו על ארץ יסדה כאגודה זו שבין הכל כא' יחשב ואין לחלק א' שלימות בלי זולתו כו', אבל מדת סדום הי' שלא יקבלו זמ\"ז והו\"ע שלי שלי ושלך כו', וזהו ג\"כ ענין הפירוד דמדות דתהו שכ\"א היתה בבחי' השלימות וע\"כ לא רצו לא להשפיע ולא לקבל זמ\"ז כו'. אך לכאורה אינו מובן דהרי טעם זה מספיק רק על זה שלא רצו לקבל מהספי' האחרת מפני שעושה גרעון בשלימות שלה שהרי זה מורה החסרון כו' כנ\"ל, אבל מפני מה לא רצו גם להשפיע שזה לכאורה אינו מגרע את השלימות אדרבא זהו גדלות מה שהוא בבחי' משפיע כו'. אך הענין הוא דהנה ידוע ומבו' במ\"א דמ\"ש\nבס\"י נעוץ תחלתן בסופן וסוב\"ת, הטעם ע\"ז מה שיסד המאציל עליון בנאצלים להיות נעוץ תחלתן בסופן כו' הוא בכדי שיהי' בחי' משפיע ומקבל כו', דהרי כל מקבל באמת הוא באין ערוך לגבי עצמות המשפיע כו', ומה שמתדמין זל\"ז שהרי משפיע ומקבל הוא כענין עו\"ע כו', זהו רק שהמדרי' העליונה שבהמקבל והיינו עצם כח שכלו ותבונתו מתדמה להארת השכל של המשפיע הבא בדבור, וכידוע בענין כאשר דברת לאמר, שמהדבור של המשפיע נעשה בחי' מחשבת שכל של המקבל כו', דכללות ההשפעה מה שמשפיע אל הזולת ה\"ז באין ערוך כלל לגבי אור השכל כמו שהוא בהמשפיע לגבי עצמו כו' כידוע, ובפרט אור השפע כמו שבא בדבור ה\"ז אור מצומצם מאד שבאין ערוך לגמרי לגבי עצמות המשפיע ולגבי אור שפעו כמו שהוא לעצמו כו', והרי צריך לצמצם א\"ע בזה בכמה צמצומים גדולים כו', וכידוע דבתחלה צריך להעלים אור שכלו לגמרי בכדי שימצא בו האור שכל השייך אל המקבל כו' דזהו כמו שבא ממהות למהות אחר, עם היות שאינו מהות אחר לגמרי שהרי זה מאותו שכל שהשכיל לעצמו כו', מ\"מ ה\"ז כמהות אחר מפני שבא באופן אחר לגמרי (באופן שא\"א לבוא מזה על הענין כמו שהוא אצל המשפיע כו', וכאשר קאים אדעתא דרבי'"],[3601330667,"דהיינו עומק חכמתו כמו שהוא לעצמו כו', שזהו ע\"י שבההשפעה בפרטי הדבורים יש בזה בהעלם גם עומק ופנימי' חכמתו כו' ה\"ז כמו שבא על דבר חדש לגמרי כו', ואין זה כמו בהחיצוניות גופא כשעולה במעלות להשיג הענין בעומק יותר שאין זה בבחי' התחדשות אצלו מפני שכבר נמצא כלול ונרגש אצלו בהעלם גם בהשגה הקודמת כו', והו\"ע עד ועד בכלל דגם בהיותו בהשגה הקודמת ה\"ה בקירוב ובערך אל ההשגה העליונה וממילא כאשר בא אל ההשגה העליונה אין זה בבחי' התחדשות כו', והוא ענין עו\"ע שהן בערך זה לזה כו', אבל כאשר בא לעומק כוונת הרב ועצם דעתו ה\"ז אצלו בבחי' התחדשות לגמרי שלא הי' גם בהשערה שלו מקודם כו'), שזה צמצום עצום כו', ואח\"כ צריך להיות כמה צמצומים דכאשר נמצא האור שכל השייך אל המקבל ה\"ה נמצא בבחי' נקודה לבד וצריך לפרט הפרטים שבה ויש בהם עדיין ריבוי אור לפי\"ע המשפיע, וצ\"ל אח\"כ עוד המשכה והתפשטות שזהו שטח הבא בדבור כו' כנודע ומבו' במ\"א, וא\"כ למה לו להמשפיע כל הטורח והירידה הזאת לצמצם א\"ע כ\"כ כו', וביותר כידוע אשר כל עלול טבעו לעלות\nאל עילתו והיינו דוקא להיות בבחי' עלי' למע' ולא לירד למטה כו', והעלי' היא בג\"ר שלו, ומה שיורד להשפיע זהו בחי' ז\"ת שבו כו', והרי הירידה בכלל היא היפך טבעו כו' וכמ\"ש במ\"א, וא\"כ מפני מה יהי' בהמשפיע היפך הטבע להיות בבחי' ירידה ובבחי' צמצומים רבים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> עוד סבה להפירוד שבתהו, שכל ספי' היתה בבחי' שלימות בעצמה, מצד הישות שמספיק מציאות עצמה, וא\"צ לקבל מזולתה והו\"ע מדת סדום שלי שלי ושלך שלך, ולכאו' מפני מה לא רצו גם להשפיע, יקדים דענין נתב\"ס בכדי שיהי' משפיע ומקבל, להיות שההשפעה היא באין ערוך לגבי עצמות המשפיע שצריך להעלים עצם שכלו ובא כמו מהות אחר (וכשהמקבל בא על הפנימיות ה\"ז כמו התחדשות, לא כמו בחיצוניות השכל גופא), ויש עוד כמה צמצומים, וטבע המוחין להיות בעלי' והבדלה.</span>\n<b>רלח)</b> אך בהיות אשר נמצא בהמקבל דבר חדש מה שאין בהמשפיע, וע\"י ההשפעה מתוסף לו תוס' אור רב כו' וכמא' ומתלמידי יותר מכולם כו', דבד\"כ ע\"י ההשפעה מתוספים בו ענינים שכליים מה שלא ידע מקודם כו', וכמו שנראה בחוש באור השכל שבא בדבור אל הזולת מתרבה ומתגדל בתוס' רב גם בהתחדשות בכמה ענינים כו', וזה בב' אופנים או שבא בבחי' גילוי מההעלם והיינו הענינים שכבר נמצאים בכח שכלו במקור השכל רק שלא באו אצלו לידי גילוי עדיין גם לעצמו כו', וכמו עד\"מ כשעוסק באיזה ענין שכלי בהשגת הענין שיודע ומשיג אותו אך נרגש אצלו שנמצא בזה עוד עומק ועדיין לא בא עליו מה הוא כו', ובהעלם יותר הוא שאינו מרגיש גם זה שיש בזה עומק כ\"א מה שאינו נוח לו עדיין, דעם היות שמשיג את הענין היטב בפרטי הענינים שבו ומ\"מ אינו נוח לו עדיין, והיינו שאינו מוצא עדיין תענוג ונח\"ר בההשגה כמו בכל השגה שיש בה תענוג כו' כנודע, וזהו הוראה שלא הגיע עדיין בהשגת הענין כפי כח השגתו במקור שכלו כו', והיינו שבמקור השכל נמצא עוד עומק בזה מה שלא בא עליו עדיין בגילוי כו', ויכול להיות שאצל בעל שכל אחר הענין טוב וניחא ולו לא ניחא לו עדיין מפני"],[3601330668,"שאצלו נמצא במקור שכלו עוד עומק שלא בא עליו עדיין כו', וע\"י הדבור שמדבר בהענין מתגלה אצלו העומק הזה כו'. והאופן הב' הוא שבא בבחי' התחדשות לגמרי והיינו שבדבור מתחדשים אצלו ענינים שלא הי' משער כלל מקודם כו' וכמ\"ש במ\"א, הרי עם היות שהדבור הוא כח אחרון ובא בבחי' צמצום גדול כנ\"ל, ובד\"כ הדבור הוא בבחי' מקבל לבד מהשכל כו', ומ\"מ עי\"ז דוקא בא תוס' אור בשכל כו', אך היא הנותנת דלהיות שהדבור הוא בבחי' מקבל וכן כל ענין הדבור הוא להשפיע אל הזולת כו', יש בזה כח נעלם מה שלא יש בהתגלות השכל שהוא בחי' המשפיע כו', והוא להיות דשרש הדבור (שהוא בחי' מקבל כו') הוא למע' מהשכל כו', וכידוע דשרש הדבור הוא מקדמות השכל כו' וכמ\"ש באגה\"ק סי' ה' ד\"ה ויעש דוד שם, ולכן בכדי להביא אור שכל בדבור צ\"ל מכח עליון דוקא, וכידוע דגם מי שיודע ומבין השכל לעצמו יכול להיות שאינו יכול להשפיע אל הזולת כו' שזה בא דוקא מעומק מקור השכל יותר כו' וכמשנת\"ל פק\"ע, והיינו מפני ששרש הדבור הוא למע' מהשכל כו' וע\"כ מצד הכח נעלם שיש בדבור מתוסף תוס'\nאור רב בשכל ע\"י ההשפעה בדבור כו', ובפרט בתלמיד המחכים את רבו ע\"י הקושיות וסתירות שעי\"ז מתוסף ריבוי אור מכח השכל ההיולי העצמי כו' וכמ\"ש במ\"א, וכ\"ז גורם ירידת המשפיע להשפיע דמאחר שע\"י ההשפעה מתוסף אצלו ריבוי אור ע\"כ הוא יורד ומצמצם א\"ע להשפיע כו'. וכמו\"כ הוא הדוגמא למע' מה שהוסד בס' השתל' להיות נעוץ תחלתן בסופן וסוב\"ת היינו שבהמדרי' התחתונה נמצא כח נעלם עליון מהמדרי' העליונה כו', בכדי שהמדרי' העליונה תרד ותצמצם עצמה להשפיע להמדרי' התחתונה ועי\"ז מתוסף בה תוס' אור כו', ונמצא מובן דסיבת ההשפעה אל התחתון הוא מפני שעי\"ז מקבל מן התחתון כו', ולפי\"ז מובן בספי' דתהו מה שלא רצו להשפיע אל הספי' האחרת שזהו ג\"כ מצד השלימות בפ\"ע שנחשב בעצמו שא\"צ לקבל מהספי' האחרת, וע\"כ לא רצתה לירד ולצמצם עצמה להשפיע כו', והגם דבספי' דתהו זהו בבחי' חו\"ג דלכאו' אין זה עליון ותחתון דשניהם שוין במדריגתן בבחי' המדות כו', מ\"מ הרי ידוע שיש מעלה בבחי' החסד על הגבו' מה שהחסד הוא בחי' גילוי אור והגבו' הוא בחי' צמצום והעלם כו'\n(דבספי' דתקון בחי' החסד הוא גילוי אור הבלתי מוגבל וגבו' הוא בחי' אור מוגבל כו' וכמ\"ש במ\"א, ובספי' דתהו י\"ל שהחסד הוא בחי' גילוי (והגילוי הוא בלי גבול) והגבו' הוא בחי' העלם לגמרי כו'), דמשו\"ז בחי' הגבו' הוא בבחי' מטה לגבי החסד כו' (גם במדרי' התקון וכ\"ש בתהו כו'), אמנם יש ג\"כ מעלה במדת הגבו' שההעלם שרשו למע' יותר שזהו מבחי' העלם העצמי ויש בזה תגבורת העצמות כו' (ועמשנת\"ל פרכ\"ד), וכאשר הגבו' נהפכה לחסד ה\"ז בבחי' תגבורת האור והגילוי ביותר כו', וזהו ע\"י ההמשכה וההשפעה מבחי' החסד בגבו' (וכענין הקבלה באהבה המבואר שם וכמו התוקף והחוזק בקיום התומ\"צ בזמן הגלות כו'), שעי\"ז נעשה הגבו' בבחי' חסד שזהו בבחי' ריבוי ההשפעה יותר הרבה מבחי' החסד כו', וכמו אלקים ברב חסדך כו' וכמו יברכנו אלקי' כו', שהברכה שמבחי' אלקי' הוא למע' הרבה יותר כו'. ונמצא כאשר החסד משפיע בבחי' הגבו' נמשך תוס' אור בבחי' החסד כו', וע\"כ בספי' דתהו שלא רצו לקבל זמ\"ז משו\"ז ג\"כ לא רצו להשפיע כו', משא\"כ בתקון כל הספי' משפיעים ומקבלים זמ\"ז\nכו', ונמצא דהעדר ההשפעה שהי' בספי' דתהו מכל ספי' אל הספי' האחרת זהו ג\"כ מצד הישות כו', דכל ספי' הי' בבחי' שלימות"],[3601330669,"בעצמה והיינו שאינו מוצא חסרון בעצמו שצריך אל הזולת, וגם אינו מוצא שום יתרון בהזולת עליו דמשו\"ז ישפיע לו בכדי לקבל ממנו היתרון שבו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אך מפני שע\"י המקבל מתוסף בהמשפיע, וכמו שע\"י הדבור מתוסף שכליים, אם בבחי' גילוי ההעלם, שמרגיש שיש בזה עומק, או שאינו נוח לו עדיין הענין, מפני שבמקור שכלו יש עוד עומק בזה, ומתגלה ע\"י הדבור, או שכליים חדשים ממש, והוא מפני שדבור שרשו למעלה מהשכל, וכמו\"כ מצד ההשפעה להזולת, ובפרט בתלמיד המחכים את רבו, ומחמת תוס' האור בהמשפיע ה\"ה רוצה לירד ולהשפיע, וע\"כ ספי' דתהו שהיו בבחי' שלימות בעצמן לא רצו להשפיע, ויבאר דחו\"ג הן ג\"כ עליון ותחתון, דחסד בחי' גילוי ובל\"ג, וגבו' העלם, וגם יש יתרון בההעלם בשרשו.</span>\n<b>רלט)</b> ובאמת זהו העדר הביטול וההנחה (דער אוועקלייג) לגבי למע' ממנו היינו לגבי עצמות אוא\"ס כו', דהנה במשפיע ומקבל הרי הביטול של המשפיע בזה שמניח א\"ע לירד ולהשפיע כו', הרי אין זה הביטול אל המקבל כ\"א הביטול והנחת עצמותו אל אמיתת הכוונה להיות משפיע ומקבל, היינו שירד מעצמותו ויניח א\"ע להשפיע אל הזולת כו'. ויובן זה יותר בענין אורות וכלים דמבו' במ\"א בענין וירד מצרימה אנוס ע\"פ הדבור דהאור בטבעו לעלות למע' ולהיות בבחי' דביקות במקורו כו' ובדביקותו במקורו ה\"ה מקבל האור לעצמו (כמו שהוא בעצמותו שאינו בגדר התלבשות בכלים כו', ואין הכוונה על עצם האור ממש, כ\"א האור שלמעלה מבחי' התלבשות בכלים כו' ועמשנת\"ל פכ\"ט) והירידה שלו שיורד מעצמותו ומצמצם עצמו להתלבש בכלים כו' זהו בהכרח בהאור מצד הכוונה העליונה, דאמיתית הכוונה הוא להיות התלבשות האור בכלי כו' דלא לתהו בראה אלא לשבת יצרה כו', וזהו אנוס ע\"פ הדבור כו', רק שכל השפעה צריך להיות ברצון דוקא הנה זהו ע\"י שבהאור (שהוא בחי' גילוי כו') נרגש בו היתרון\nשיש בהכלים מצד שרשן הקדום שע\"י ההתלבשות מתוסף בו תוס' אור כו' וכמ\"ש במ\"א בדרוש לרוקע הארץ כו', הרי דעצם ענין ההשפעה הוא מצד הבטול בעצם כו' שבטל אל אמיתת הכוונה העליונה כו', וע\"י שנשלם הכוונה העליונה עי\"ז בא התוס' אור ע\"י המקבל שבו דוקא יש נעיצת התחלה דהיינו אמיתית הכוונה כו', והתוס' אור הוא שמאיר בו בחי' אוא\"ס הבל\"ג כו', דהאור מצ\"ע גם כמו שהוא בדביקות במקורו ה\"ז בחי' אור המוגבל היינו בחי' או\"פ כו', והכלים ידוע דשרשם מאוא\"ס הסובב (דלכן הכלי היא עגולה כו' וכמ\"ש במ\"א) ואמיתית שרשה היא מעצמות א\"ס כו', וע\"כ ע\"י ירידת האור בהכלי מתוסף בו תוס' אור כו' (ודוקא כאשר ההשפעה היא בבחי' ביטול אז דוקא מתוסף בהמשפיע בחי' תוס' אור ע\"י ההשפעה כו'), ובספי' דתהו לא הי' בהם בחי' הביטול והנחת עצמותו אדרבא כל ספי' היא בבחי' תוקף הישות להיות במציאותו כמו שהוא בעצמותו דוקא וע\"כ לא הי' בהם בחי' ההשפעה זה לזה כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש אנכי ה' אלקיך, דהנה עיקר התחלת התקון הוא מן מ\"ת דהרי מקודם היו שני אלפים תהו ואח\"כ שני אלפים תורה שזהו בחי' התקון"],[3601330670,"כו', וז\"ש במ\"ת אנכי הוי' אלקיך דהוי' אלקים הו\"ע אורות וכלים והיינו להיות התיישבות האורות בהכלים דלא לתהו בראה אלא לשבת יצרה כו', וע\"י התלבשות האור בהכלי להאיר את הכלי נמשך תוס' אור מבחי' אוא\"ס הבל\"ג כו', וזהו אנכי ה' אלקיך גילוי בחי' אנכי כו' כו', וכמו שש מאות אלף רגלי העם אשר אנכי בקרבו דמשה הי' בבחי' משפיע ועי\"ז אנכי בקרבו כו' כנודע ומבו' במ\"א. וזהו ג\"כ מש\"א אשר הוצאתיך מאמ\"צ היינו היציאה מהמצרים וגבולים, וכנ\"ל דהאור מצ\"ע גם כמו שהוא בבחי' דביקות במקורו ה\"ז אור מוגבל וע\"י ההשפעה בהכלי מאיר בו בחי' אור הבל\"ג כו', וזהו אשר הוצאתיך מאמ\"צ כו' ולא נא' אשר בראתי שו\"א, דבריאת שו\"א הוא בבחי' הארה שבאה בבחי' מדה וגבול לפי\"ע העולמות כו', וגם בתחלת ברה\"ע היו שני אלפים תהו כו' ומ\"ת הוא להיות בחי' התקון כו', וע\"כ אומר אשר הוצאתיך מאמ\"צ גילוי בחי' אוא\"ס הבל\"ג כו', וזהו אנכי הוי' אלקיך שע\"י יחוד אורות וכלים בבחי' התיישבות וגילוי בבחי' או\"פ עי\"ז אנכי ה' אלקיך מאיר גילוי בחי' אנכי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ואמיתית הסבה הוא העדר הביטול דתהו לעצמות אוא\"ס, דירידת העליון להשפיע הוא מצד הביטול לאמיתת הכוונה וכמו בהאור שטבעו לעלות למעלה, ואזי מקבל אור עליון יותר, ויורד בהכלי מחמת הביטול לאמיתת הכוונה, והוא ברצון מצד הרגש היתרון שבכלים, שמאיר בו בחי' אוא\"ס הבל\"ג שרש הכלים. וזהו אנכי הוי' אלקיך שע\"י דש' הוי' בחי' האור נמשך באלקים בחי' הכלים הוא גילוי בחי' אנכי.</span>"],[3601330671,"<h3>בס\"ד. יום ב' דחה\"ש, תרד\"ע</h3>\n<b>וראיתי</b> אני שיש יתרון לחכ' מן הסכלות כיתרון האור מן החשך, וצ\"ל מה מודיע בזה שיש יתרון לחכ' מן הסכלות שזה ידוע ומובן לכל ומה מודיע זאת שלמה בחכמתו שיש יתרון כו'. ולהבין זה ילה\"ק משנת\"ל סיבת הפירוד דספי' דתהו שלא רצו לקבל זמ\"ז וגם לא להשפיע זל\"ז מצד השלימות שהי' בכאו\"א כו' והוא להיות דסיבת ההשפעה מה שהמשפיע יורד ומצמצם א\"ע להשפיע הוא מפני שעי\"ז מקבל יתרון אור כו', וספי' דתהו מצד הישות שלהם היו בבחי' שלימות בעצמן שלא מצא חסרון בעצמו וגם לא מצא יתרון בהמקבל שעי\"ז יהי' בו תוס' אור כו' וע\"כ היו בבחי' פירוד שלא להשפיע זל\"ז כו'.\n<b>רמ)</b> אמנם עדיין צ\"ל דהרי אנו מוצאים דבהשפעה יש ב' אופנים, הא' שההשפעה היא מצד הביטול והב' שסיבת ההשפעה היא מצד הגדלות דוקא, דב' מיני השפעה אלו ישנם בקדושה ג\"כ, דהנה ידוע דמקובלים הראשונים קראו מדת החסד בשם גדולה והאריז\"ל קורא תמיד מדת החסד בשם חסד ובחי' הגדולה אינו"],[3601330672,"בכלל המדות כלל לדעתו (ומ\"ש לך ה' הגדולה וכן מש\"א הגדול הגבור מפרש שזהו בחי' החסד, אבל עצם ענין הגדולה ה\"ז למע' מהמדות כו'). והענין הוא דהנה אי' בזהר אית חסד ואית חסד אית חסד בחי' חסד זוטא חסד דז\"א ונקרא חסד דאברהם, ואית חסד בחי' רב חסד שהוא בחי' חסד דא\"א כו', ונודע דחסד דז\"א הוא חסד שמצד הביטול ועש\"ז נק' חסד זוטא כו', דלבד זאת שבא בבחי' הגבלה לגבי בחי' רב חסד דאריך כו', דמשו\"ז כללות המדות דאצי' נק' בשם זעיר אנפין לגבי בחי' אריך כו', וכידוע דז\"א הוא סוף עולם הא\"ס והיינו שכל האורות דאוא\"ס ב\"ה באים בז\"א בבחי' קטנות וצמצום ועי\"ז יכול להיות התהוות העולמות בע\"ג כו' וכמ\"ש במ\"א, דמ\"מ לא משו\"ז לבד נקרא חסד זוטא שהרי מ\"מ גם בחי' חסד דז\"א הוא ההשפעה בבחי' בלי גבול כו', וכמ\"ש בסש\"ב ח\"ב פ\"ד בפי' הגדול הגבור ופי' הגדול הוא מדת חסד והתפשטות החיות בכל העולמות וברואים לאין קץ ותכלית כו', ועם היות שזהו בחי' בל\"ג דאצי' דכללות אור האצי' הוא שבא בבחי' מדה וגבול כו', ועיקר הבל\"ג בזה הוא לגבי עולמות בי\"ע לבד\nכו', מ\"מ ה\"ז ההשפעה שבבחי' בל\"ג כו' (וי\"ל דבמדרי' שהוא בבחי' בל\"ג אפי' רק לגבי העולמות יש בזה מבחי' בל\"ג באמת כו', וכמו בענין בכל מאדך שמבואר בכ\"מ הפי' מאד שלך היינו מה שאצלו הוא בחי' בל\"ג דבמדרי' שלמע' ממנו ה\"ז בבחי' גבול כו', ומ\"מ אמרו ע\"ז במדה שאדם מודד בה מודדין לו שממשיך עי\"ז בחי' מאד העליון שהוא בל\"ג באמת כו', והיינו שמשום דאצלו הוא בחי' בל\"ג ה\"ז גבוה במדרי' מבחי' הגבול דהמדרי' העליונה כו', וכמו\"כ יובן בבחי' החסד להיותו בבחי' בל\"ג דהרי במדות דאצי' זהו ההפרש בין בחי' החסד והגבו' דחסד הוא בל\"ג וגבו' הוא בחי' הגבלה כו' וכמ\"ש במ\"א, ע\"כ עם היות שכ\"ז הוא לגבי בי\"ע דבעצם מהותם ה\"ה בבחי' מדות שהן בבחי' מדידה והגבלה כו' יש מ\"מ בבחי' החסד מבחי' בל\"ג האמיתי כו'). וא\"כ מה שנקרא חסד זוטא אין זה מצד ההגבלה כ\"א זהו מפני שהוא בחי' חסד שמצד הביטול כו', וכמו חסד דאאע\"ה שהי' משפיע טוב וחסד לכל אדם שהי' זה מצד הביטול והשפלות שלו שלא הי' נחשב כלל בעיני עצמו, וכמ\"ש ואנכי עפר ואפר שהי' בעצמו כעפר ואפר\nממש, וע\"כ כל מה שהי' לו נתן לזולתו שנחשב בעיניו יותר ממנו כו' והוא הסתפק בהשיריים ומותרות, מפני שהי' נחשב בעצמו כשיריים כו', וכן הוא בד\"כ בכל איש הטוב והחסד שיש בו ע\"פ הרוב מדת הענוה והשפלות וא\"צ דבר לעצמו, ומסיבה זאת יהי' כמו טבע בנפשו להרבות חסד וטוב לכל הבריות וליתן להם מכל אשר לו כו', דמי שהוא בהגבהה והתנשאות צריך הכל לעצמו וכמה שיש לו אינו מספיק לו (עס איז ניטא קיין גינוג) ולהיפך מי שהוא בענוה ושפלות יתן הכל אל הזולת כו', וכמארז\"ל במשנה פ\"ה דאבות תלמידיו של אברהם אבינו עין טובה ורוח נמוכה ונפש שפלה כו'. והדוגמא מזה למע' באדם העליון בחי' החסד הוא ג\"כ מצד הביטול כו', דלהיות שהע\"ס דאצי' הן בבחי' ביטול לגבי אוא\"ס דלאו מכל אלין מדות איהו כלל כו', וכמ\"ש בס\"י ולפני כסאו הם משתחוים כו', ומצד זה הוא בחי' החסד וההשפעה להשפיע טוב וחסד בעולם כו' (ולמע' הרי אינו שייך לומר דמפני שא\"צ לעצמו משו\"ז הוא משפיע כו', רק דצ\"ל דמצד הביטול כל דבר תופס מקום ונראה לדבר חשוב וראוי הוא להשפיע לו כו' (ומדת\nהגבו' הוא ג\"כ מצד הביטול והוא דמצד עוצם הביטול הנה כל ביטול הנבראים לא זכו בעיניו כו', ומ\"מ בחי' השפלות והנחת עצמותו הוא יותר בבחי'"],[3601330673,"החסד כו'), ועמ\"ש במ\"א ההפרש בין טוב לחסד דאיש הטוב הוא שרואה גרעון הזולת ושאינו ראוי ומ\"מ מיטיב עמו כו', דבמדת הטוב בעצם אין גרעון הזולת מונע כלל כו', ואיש החסד הוא שאינו רואה כלל את הגרעון ונראה לו שהוא ראוי אל ההשפעה כו', והיינו מצד הביטול והשפלות שלו שאינו נחשב בעיניו למציאות כלל ושפל מאד בעיניו כו', ה\"ה רואה רק את הטוב בכל דבר וחשוב הוא בעיניו ושהוא ראוי לההשפעה כו'), וזהו דחסד דז\"א נקרא חסד דמ\"ה וכמו אברהם אבר מ\"ה דהיינו החסד שמצד הביטול כו', אך כ\"ז הוא בבחי' חסד דאצי' כו'. אבל בחי' ורב חסד שלמע' מאצי' הוא בחי' החסד שמצד הרוממות והגדולה כו', וכמו שאנו רואין למטה שיש ג\"כ בחי' רב חסד שבא ממדה הפכית לגמרי ממדת השפלות והשיריים כנ\"ל כ\"א אדרבה ממדת הגדולה וההתנשאות כו', והוא כאשר האדם מתעלה בגדולה והתנשאות דעושר בבלי מדה מוגבלת כו', אזי יהי' כמו טבע בנפשו להשפיע ג\"כ רב טוב וחסד לכל הבריות כקטן כגדול במדה בלתי מוגבלת כלל כו', וכמו מלך גדול שמשפיע לכל כיד המלך בריבוי השפעה ביותר, וזהו מפני\nשמצד עוצם גדולתו אין ההשפעה תופס מקום וגם ריבוי ההשפעה כדבר קטן נחשב אצלו כו' (והנה הטבע הזאת להשפיע כו' אין זה מצד טבע המרומם להיות נמשך אל השפל כו' שנת\"ל פרל\"ה, דכאן הוא להשפיע גם למי שאינו שפל ושייך גם במי שעומד בדרגא כמו בהשפל לגמרי כו', רק זהו מצד גדולת המשפיע, שמפני ריבוי השפע וריבוי האור בעצמו ה\"ה בבחי' טבע הטוב להיטיב לכל והיינו שמטובו ייטיב לכל אדם כו', דמי שטוב לו על לבו (עס איז גוט אויפין הארצין) רוצה שיהי' לכל טוב כו' וזהו סיבת ההשפעה אל הזולת כו', ומצד הגדולה והרוממות שלו ההשפעה היא בריבוי מאד ונמשך לכל בשוה להיות כי טבע הטוב להטיב כו'). והדוגמא מזה למע' באוא\"ס שלפני אצי' שהאור הוא בבחי' א\"ס ובבחי' בל\"ג ממש דלגדולתו אין חקר כו' וטבע הטוב כבי' להיטיב ולהשפיע טוב וחסד לעולמות ונבראים בריבוי השפעה ביותר שאין קץ ותכלית כלל לחסדו הטוב כו', ועז\"נ ארך אפים וגדל חסד וכמא' כמה ארך אפים לפניו כו' שמשפיע לכל בריבוי השפעה ביותר כו', וכ\"ז הוא מצד הגדולה והרוממות שזהו סיבת ההשפעה ומשו\"ז\nהוא בריבוי ביותר כו'. ולפי\"ז צ\"ל בספי' דתהו הי' צ\"ל עכ\"פ אופן ההשפעה כזאת שמצד הגדולה כו', דעם היות שלא הי' בהם ההשפעה שמצד נעיצת התחלה שבהמקבל שעי\"ז יהי' יתרון להמשפיע כו' שזהו כענין ההשפעה שמצד הביטול כו' (ובאמת זהו ע\"י הביטול אל אמיתת הכוונה כו' כנ\"ל פרל\"ז ורל\"ט), ובספי' דתהו מצד הישות שלהם א\"צ לקבל שום יתרון שהיו בבחי' שלימות בעצמן כו' כנ\"ל, מ\"מ הרי מצד הגדולה וההתנשאות שהי' בהם משו\"ז הי' צ\"ל בהם ההשפעה כו', ונודע דספי' דתהו הי' בבחי' ריבוי האור ביותר, וא\"כ הי' צ\"ל בהם טבע הטוב להיטיב ולהשפיע ג\"כ בבחי' ריבוי אור כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וצ\"ל הלא בהשפעה יש שמצד הביטול, דחסד דז\"א שנק' חסד זוטא, אין זה רק מצד הצמצום, שהרי חסד במדות דאצי' הוא השפעה בבחי' בל\"ג, וי\"ל שיש בזה בחי' בל\"ג ממש להיותו בחי' בל\"ג דאצי', כ\"א זהו מצד הביטול, וכמו חסד דאברהם שהי' כשריים בעיניו, וכמו\"כ למעלה מצד הביטול לאוא\"ס כל דבר תופס מקום וראוי להשפעה, אמנם רב חסד הוא השפעה מצד הגדולה, לא מצד תפיסת מקום דהמקבל, רק משום טבע הטוב להיטיב ובריבוי בל\"ג, וכמו הגדול</span>"],[3601330674,"<b>בעושר</b> רוצה להיטיב ולהשפיע לכל, ולכאורה הרי אופן השפעה זו הי' צ\"ל בספי' דתהו מצד הגדולה.\n<b>רמא)</b> אך הענין דהנה במשנה דפ\"ה דאבות אי' שלי שלי ושלך שלך זו מדה בינונית וי\"א זו מדת סדום, דלהת\"ק עיקר מדת סדום הוא כשמונע ממנו מה שזה נהנה וזה לא חסר כלל, אבל כשזה חסר קצת אין זו מדת סדום, ולהי\"א גם כשחסר קצת ה\"ז מדת סדום כו'. והענין למע' הוא ע\"פ הידוע ההפרש בין אור ושפע (עמשנת\"ל פנ\"ג ואילך באורך), דאור הוא שאינו פועל שום שינוי בהמאור והוא להיותו בחי' הארה לבד שאינו נמשך בזה ממהות ועצמות הדבר רק הארה לבד כו', ואופן ההמשכה היא שלא בבחי' התלבשות וחפיסא דהיינו שאין המאור מוטרד ומוגדר בההשפעה כו', והוא דלהיותו בחי' הארה לבד ה\"ז בא בדרך ממילא כו', וכמו באור השמש שאינו עושה שום שינוי בהמאור דבגילוי האור אין שום חסרון בהמאור וכשאינו מאיר אין בו תוספות כו', או להיפך דבהשפעת האור אינו מתוסף דבר בהמאור וכשאין האור מאיר אין בו שום גרעון מזה כו', רק שהשמש מוכרח בהאור. ולמע' יובן דעם היות שזה גילוי רצוני מ\"מ ה\"ז בדרך ממילא כו' וכמו באור וחיות כללי מהנפש כו' וכמשנת\"ל שם באורך, והנה בהמשכת\nהעצמות ודאי כן הוא שאין בו שום שינוי ח\"ו, דכאשר העצמות נמשך אין זה עושה שום חסרון ח\"ו, דכשם שבהמקבל הרי כשאתה תופס במקצת מן העצם אתה תופס בכולו, כמו\"כ בהעצמות אין בזה שום חסרון ח\"ו בזה שנמשך כו' (ולא כמו בשפע כמו מים הנמשכים ממקום למקום כו'), וגם אינו שייך שום טרדא והגדרה כו'. הנה ודאי כן הוא בבחי' העצמות, אבל מה שמדברים הוא בהאור והגילוי אם הוא בבחי' אור או בבחי' שפע והכוונה הוא בהאור עצמו (וגם במקור האור ר\"ל מה שהוא בבחי' מקור כו') אם יש בזה שינוי כו', והוא דבההמשכה שבבחי' אור אין בזה שינוי לא בהמקור ולא בהאור דלהיות שהוא הארה לבד אינו פועל שינוי בהמקור כו', ומפני שאינו בא בהתלבשות ותפיסא (שזהו להיותו אין כמו העצם כו') אין שינוי גם בהאור כו', והעיקר הוא למע' בבחי' האור מקיף שבא בבחי' גילוי העצם ובבחי' אין כו', שההמשכה היא בבחי' אור לא בבחי' שפע והיינו שאין בזה שום שינוי כלל כו' וכמשנת\"ל בפרקים הנ\"ל. אבל כאשר ההמשכה היא בבחי' מהות דבר מה כו' והיינו בהאור שהוא בבחי' מציאות דבר כו', הרי\nההמשכה בזה הגם שהוא רק הארה לבד ה\"ז המשכת מהות דבר מה כו', וכמו בהשפעת השכל מהמשפיע אל המקבל שהשכל הוא בבחי' מציאות דבר (וכמשנת\"ל פמ\"ט דכח השכל ה\"ז כח שלחוץ העצמות של הנפש כו'), ע\"כ השפעת השכל הגם שזהו רק הארה לבד ה\"ז המשכת מהות דבר מה כו', וה\"ז בבחי' שפע שבא בבחי' התלבשות ותפיסא שהמשפיע נתפס בזה וגם ההשפעה היא באה בבחי' התלבשות ותפיסא בהמקבל כו', ולכן השפע משתנה אצל המקבל דכאשר תופס את ההשכלה ה\"ה משתנית לפי אופן הכלים והחושים שלו כו', וכן גם המשפיע משתנה בזה שאינו דומה קודם ההשפעה ובעת ההשפעה ואחר ההשפעה והיינו מפני שנתפס ומתלבש בזה כו', וכן הוא בכל עו\"ע שהארת העילה היא בבחי' התלבשות בהעלול כו' והעילה נתפסת בזה וכמא' החוקרים כל מניע מתנענע בעצמו כו'. ולמע' זהו בבחי' או\"פ בכלל שבא בבחי' צמצום ובבחי' מדה וגבול לפ\"ע העולמות להאיר העולמות כו' והוא בבחי' מציאות"],[3601330675,"אור כו', וכמשנת\"ל באורך איך שגם בשרש ומקור האורות יש ע\"ס רק שהן בבחי' אחדות ופשיטות לגמרי כו' (וכללות האור הזה הוא להאיר את העולמות כו'), ולאחר הצמצום הן בבחי' ספי' פרטיות ונקרא ע\"ס בלי מה כו', וכמו שמתלבשים בכלים ה\"ה בבחי' מציאות אור כו', ובד\"פ הוא בבחי' הכלים דע\"ס דאצי' שבהם שייך ענין ההשתל', וכמ\"ש באגה\"ק סי' כ' ד\"ה איהו וחיוהי חד בהשתל' הספי' בספי' עצמן כו', וגם למ\"ד כלים דזו\"נ נעשים נר\"נ לבי\"ע כו' (ובזה ג\"כ בחי' האור כמו שנמשך ע\"י הכלים שנעשה כמהות הכלים שבא ג\"כ בבחי' התלבשות כו', ומ\"מ על האור נאמר אין קדוש כה' כו' וכמ\"ש במ\"א).\n<span data-k=\"ks\"><b>קיצור.</b> יקדים דלדעת ת\"ק במשנה דאבות מדת סדום הוא כשמונע השפעה שלא חסר כלל, ולדעת הי\"א גם כשחסר קצת ה\"ז מדת סדום, והענין הוא דהנה אור להיותו הארה לבד אינו עושה שינוי בהעצם, וגם בהאור אין שינוי מפני שאינו בבחי' תפיסא, והעיקר הוא בהאו\"מ, ושפע הוא שעושה שינוי בהמשפיע כמו בהשפעת השכל, וגם השפע משתנה אצל המקבל, ולמעלה הוא בבחי' האו\"פ שבא במדה וגבול, ובהתלבשות בכלים ה\"ה בבחי' מציאות, והעיקר הוא בבחי' הכלים.</span>\n<b>רמב)</b> והנה בב' מדרי' אלו הוא ההפרש אם המשפיע חסר או לא חסר כו', דהנה בבחי' אור שזהו בד\"כ בבחי' האו\"מ כנ\"ל זהו זה נהנה וזה לא חסר כלל, והיינו דהמקבל נהנה מן האור שהרי האור מקיף פועל ג\"כ בעולמות, וכמשנת\"ל באורך (מפנ\"ז ואילך) בענין פעולת המקיף הן המקיפים כללים והן המקיפים פרטים כו', וכידוע דעיקר ההתהוות ועיקר החיות הוא מהאו\"מ כו', וזה לא חסר שלא יש שום שינוי בהמאור וגם לא בהאור כו' להיותו בחי' גילוי העצם לבד כו', וגם כמו שהוא בבחי' שייכות אל העולמות ונעשה בבחי' מקיף להם ה\"ה בבחי' אין ממש כו', ובכל מה שנמשך להיות בבחי' מקיף פרטי לכל עולם ועולם בפרט כו' ה\"ה באותו המהות ממש כמו שהוא בכללות ואין בו בחי' מעלה ומטה כו' וכמשנת\"ל פרק פ' ובפרקים שאח\"ז, ופעולת המקיף שפועל בהעולמות אין זה בבחי' התלבשות ותפיסא בהם ואין עושה שום שינוי כו', וזהו ולא חסר שאין שום חסרון וגרעון בההשפעה כו', וכ\"ז הוא בבחי' אור מקיף. אבל בחי' או\"פ שבא בבחי' שפע ובפרט בבחי' הכלים שפעולת העליון בהתחתון הוא בבחי'\nהתלבשות ותפיסא כו', הרי בזה חסר קצת המשפיע בהשפעתו היינו שיש שינוי בהמשפיע כו', וכמו בהשפעת השכל מהמשפיע אל המקבל שהמשפיע נתפס בזה כו', דכמו\"כ הוא בדוגמא כזאת בבחי' ההשתל' בע\"ס דאצי' דשייך בזה שינוי כו', ויש שהוא בבחי' חסר ממש וכמו ע' שנין דדוד שנתן לו אדה\"ר שנחסרו בשני אדה\"ר (וידוע שזהו המשכת האור מח\"ע לח\"ת כו', וכן בשני האבות שנתנו לו כו', וצ\"ל שזהו להורות שאינו כמדליק נר מנר כו', דהנה למטה הרי נחסרו ממש שנים האלו משנות אדה\"ר והאבות אבל למע' אינו שייך לומר חסרון ממש, רק י\"ל דלהיות שענין האצי' הוא כמדליק נר מנר שאין נר הראשון חסר כלל כנודע וההמשכה בבחי' המל' להיות שזהו מקור בי\"ע שבאצי' ההמשכה אינו בבחי' כמדליק נר מנר כו', ועמשנת\"ל פקמ\"ה ובפרקים שאח\"ז איך שבעו\"ע יש הפרש בין שהוא לצורך האצי' או לצורך בי\"ע כו'), וגם בהמשכה שאינה עד\"ז מ\"מ מאחר שהוא בבחי' התלבשות ה\"ז"],[3601330676,"עושה חסרון ושינוי כו'. ועמ\"ש בדרוש אוא\"ס בכוחך הגדול איך שכל נברא יש בו ג' מיני חיות והן בחי' אור וחיות וכח והיינו מבחי' האו\"מ והאו\"פ והכלים כו', דהאור מקיף אינו בבחי' התלבשות כלל כו', והאו\"פ הוא בבחי' התלבשות ומ\"מ הוא קדוש ומובדל ועז\"נ אין קדוש כהוי' כו', ובחי' כח הוא מבחי' הכלים שבבחי' התלבשות ממש ובזה שייך שינוי כו' (והעיקר הוא בכלים דבי\"ע כו'), וזהו זה נהנה וזה חסר, דזה נהנה בבחי' הנאה פנימי' בבחי' אור וחיות פנימי במורגש שמאיר בו בבחי' גילוי ממש בכל עולם ועולם לפי ערכו ומדריגתו כו', וזה חסר שנעשה שינוי ע\"י ההתלבשות והתפיסא כו', אך נגד זה יש בזה יתרון מה שנתוסף תוס' אור בהמשפיע ע\"י המקבל כו', וכמשנת\"ל פרל\"ח דירידת המשפיע מה שיורד ומצמצם עצמו להשפיע זהו מצד נעיצת התחלה שבהמקבל שעי\"ז נתוסף אור רב בהמשפיע כו', דכ\"ז הוא דוקא באופן ההשפעה הזאת שבבחי' או\"פ כו' וכמשי\"ת. ויובן כמו\"כ בנה\"א ונה\"ב שהנה\"א הוא בבחי' התלבשות בהנה\"ב, דעם היות דהנה\"א הוא במדרי' הקדושה והנה\"ב הוא מק\"נ שאינם בערך זל\"ז\nכלל וכלל ומ\"מ הרי הנה\"א הוא בבחי' התלבשות ממש בהנה\"ב, וכל ירידתו למטה הוא לפעול תקון וזכוך הנה\"ב שזהו דוקא ע\"י שהנה\"א מצמצם א\"ע ומתעסק בזה, דהיינו שההשגה וההתבוננות יהי' בענינים השייכים לנה\"ב היינו ענינים כאלו שהמה בקירוב אליו כו', ושתהי' ההתבוננות באופן כזה שיובן אל הנה\"ב ג\"כ וירגיש ג\"כ את הטוב והעילוי דאלקות כו', דכ\"ז הוא בבחי' שינוי בהנה\"א הן בכללות ההתלבשות והן בההתעסקות בתקון וזכוך הנה\"ב כו', אבל עי\"ז דוקא מתוסף אור רב בנה\"א מהשרש הקדום דנה\"ב דשרשו מתהו שקדם לתקון שניתוסף עי\"ז אור בנה\"א כו'.\n<b>ועפי\"ז</b> יובן מ\"ש וראיתי אני שיש יתרון לחכמה מן הסכלות כו', דסכלות קאי על הנה\"ב, והרי הנה\"א מתלבש בהנה\"ב ונתפס בזה אך עי\"ז מתוסף אור בנה\"א כו', ועז\"א וראיתי שיש יתרון כו' דעם היות שזה ירידה גדולה הנה עי\"ז דוקא יש יתרון לחכ' דנה\"א מהסכלות דנה\"ב כיתרון האור שהוא מתוך החשך דוקא כו', ובמדרש אי' דכשם שיש יתרון לאור מן החשך כן יש יתרון לד\"ת על דברי הבלים, והיינו שהרי התורה היא ג\"כ בבחי' התלבשות והתעסקות בדברים הגשמיים וכמו ר\"י כולהו תנויי בניזקין הוה שעי\"ז הוא הבירור כו' וכמשנת\"ל פקע\"ט, ונעשה יתרון עי\"ז בבחי' תוס' אור כו'. וזהו וראיתי אני שיש יתרון כו' דההשפעה שבבחי' שפע שעושה שינוי בהמשפיע ובההשפעה דכמו\"כ בנה\"א שמשתנה בההשפעה בבחי' התלבשות בנה\"ב, אך עי\"ז נעשה בו יתרון גדול בבחי' תוס' אור כיתרון האור כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה בהאו\"מ זה נהנה שהמקיף פועל בו, והוא עיקר החיות, וזה לא חסר שגם פרטי המקיפים הוא אותו המהות, ובהאו\"פ ובפרט בכלים הרי יש שינוי, ויש שחסר וכמו ע' שנין דדוד שחסרו מאדה\"ר, וי\"ל שלהיות ההמשכה במל' אינו כמדליק נר מנר, וזה נהנה באו\"פ וזה חסר שיש שינוי, אך יש בזה יתרון תוס' האור שע\"י המקבל, וכמו\"כ בנה\"א שמתלבש בנה\"ב לתקנו מתוסף עי\"ז אור בנה\"א. ובזה יובן מ\"ש וראיתי שיש יתרון לחכ' דנה\"א ע\"י בירור הסכלות דנה\"ב.</span>"],[3601330677,"<h3>בס\"ד. ש\"פ נשא, תרד\"ע</h3>\n<b>נשא</b> את ראש בני גרשון גם הם כו', וצ\"ל מהו ענין נשיאות ראש, וכן בכללות שבטי ישראל כתי' בפ' במדבר שאו את ראש כל עדת בנ\"י, וצ\"ל מה צריכים לנשאות את הראש והלא הראש הוא מדרי' גבוה ונעלה ומהו\"ע נשיאת הראש. ובמד\"ר נשא פ\"ו אי' הה\"ד לא יגרע מצדיק עיניו אין הקב\"ה מונע דוגמא דידהו (ופי' מת\"כ מה שחפצים בו וקובעין דוגמתו ומגמתו נגד עינם ולבם), יעקב חמד את הבכורה לשם שמים כו' והקב\"ה הסכים וקראו בני בכורי כו', ואם לחשך אדם והלא גרשון בכור הי' למה הקדים הכתוב לקהת לנשיאת ראש, אף אתה אמר לו מפני שקהת הי' מטועני הארון כו', שמא תאמר בני גרשון היו פחותים מהם לכך נאמר גם הם שהיו שוים ובשביל כבוד התור' הקדים בני קהת, אבל במקומות אחרים הקדים לגרשון כו'. וצ\"ל מה שייכות תורה לנשיאת הראש דמשו\"ז הקדים לבני קהת כו', ואעפ\"י שהקדים לבני קהת מ\"מ שניהם שוים כו', ולמה דוקא גבי נשיאת ראש הקדים בני קהת משום כבוד התו' כו'. ולהבין כ\"ז ילה\"ק משאמרז\"ל במשנה האומר שלי שלי ושלך שלך זה מדה בינונית וי\"א זו מדת סדום,\nדלדעת הת\"ק מדת סדום הוא כשמונע השפעה שזה נהנה וזה לא חסר כלל ולדעת הי\"א גם כשחסר קצת ה\"ז מדת סדום, ונת\"ל שזהו בב' המדרי' דאור ושפע דענין בחי' אור הוא שזה הארה לבד ובבחי' אין שאינו בא בבחי' התלבשות וע\"כ אין בזה חסרון ושינוי כלל לא בהמאור ולא בהאור כו', משא\"כ בחי' שפע הוא בהאור שהוא בבחי' מציאות דבר וההשפעה באה בבחי' התלבשות כו', וע\"כ הגם שההמשכה היא הארה לבד ה\"ז עושה שינוי בהמשפיע ובההשפעה כו'. ונת' דאור זהו בחי' או\"מ שאינו בבחי' התלבשות ושפע הוא בחי' או\"פ שבא בהתלבשות ותפיסא כו', וכמו רצון ושכל שהרצון בכ\"מ שהוא ה\"ה בבחי' תוקף הרצון שאין בו שינוי כלל כו' והשכל הוא במציאות כח שבא בבחי' שינוי כו', ונת' דמ\"מ יש יתרון מעלה באו\"פ דזה שע\"י ההשפעה מתוסף אור בהמשפיע ע\"י כוונת נעיצת התחלה שבהמקבל כמשנת\"ל (ד\"ה אנכי ה') זהו בהאו\"פ דוקא כו'.\n<b>רמג)</b> וביאור הענין יש להבין ענין האו\"מ והאו\"פ בתחילת המשכתן מן העצמות כו', דהנה ידוע דהאו\"מ הרי כללות ענינו אינו להאיר את העולמות כ\"א הוא בבחי' גילוי מן העצם כו', דכך עלה ברצונו ית' לגלות אור מן העצמות לפי אופן העצם כו' לא לפעול דבר כ\"א רק לגלות אור מן העצמות כו', ובודאי יש בזה כוונה (עמשנת\"ל פקכ\"ח) להיות שזהו גילוי רצוני כו', אבל ענין הגילוי הזה אינו לפעול איזה דבר רק לגלות אור לבד כו', ואור זה אינו כלל בבחי' ירידה מן העצמות כו'. דהרי ידוע דהאור שלפה\"צ כללות האור הוא בחי' אור הכלול בעצמותו כו' דעם היות שבהאור כמו שהוא לפה\"צ יש בו ג\"כ בחי' עצם והתפשטות, דהתפשטות האור הוא בחי' אור השייך אל העולמות כו' דבעצמותו גופא הוא בחי' אור המאיר אל הזולת כו', וכמ\"ש במ\"א בענין קדש וקדוש כמו שהוא באוא\"ס שלפה\"צ דשניהן הן בהאור רק דקדש הוא בבחי' עצם האור דהיינו בחי' אור המאיר לעצמו וקדוש הוא בחי' התפשטות האור דבעצמותו הוא בחי' אור המאיר אל הזולת כו', מ\"מ כללות האור אינו בבחי' יציאה מן העצמות כו'. וכנודע ההפרש בין שם אור לשם אצי'"],[3601330678,"דלכאו' מה נתחדש בענין האצי', שהרי אצי' הוא בבחי' האור דוקא להיות דכל ענין האצי' הוא בבחי' דביקות במקורו דאצי' הוא ל' אצלו וסמוך כו', וזה שייך בהאורות דוקא שהן בבחי' דביקות במקורן, משא\"כ הכלים אינם בבחי' דביקות כו', דמשו\"ז הכלים הן בחי' בריאה שבאצי' כו', דעם היות שהם בחי' אצי' להיותן אלקות ממש כו', מ\"מ לשיטת הרקנטי הרי הכלים הם בחי' ברי' שבאצי' כמ\"ש במ\"א ואצי' הן האורות שהן בבחי' דביקות כו', וא\"כ מה נתחדש בענין האצי' על ענין האור כו'. אך הענין הוא דאצי' הוא בחי' הפרשת הארה מן המאציל דהיינו בבחי' ירידה ויציאה מן העצמות כבי' שזהו ע\"י הצמצום דוקא כו', ועי\"ז נעשה האור בבחי' מציאות דבר דבזה שנאצל מהמאציל עליון נעשה בבחי' מציאות אור כו', אבל כללות האור שלפה\"צ נק' בשם אור דהיינו שכלול בעצמותו עדיין ואינו בבחי' מציאות אור כו' (ובחי' אצי' דכללות הוא האוא\"ס שלפה\"צ כמ\"ש במ\"א זהו מפני שבעצמותו הוא בחי' אור השייך אל העולמות כו'). וכידוע בענין אתה הוא הוי' לבדך דגם בחי' הוי' שהוא בחי' גילוי והתפשטות\nהאור הכל הוא לבדך כמו שהוא לבדו כו', וכשם דהאוא\"ס שלפה\"צ ה\"ה כלול בעצמותו כו', כמו\"כ כללות האו\"מ אינו בבחי' ירידה מן העצמות שהרי האו\"מ הוא אור שאינו בבחי' צמצום כו', וידוע דשרש כל המקיפים הן מהעיגול הגדול שלפני הקו והיינו שהן מהאוא\"ס שלפה\"צ שנמשך שלא ע\"י הצמצום כו' ר\"ל שאין הצמצום פועל באור זה כו' וכמ\"ש במ\"א (והגם שנת\"ל פכ\"ז בענין ב' ענינים שבצמצום, דבאור הבל\"ג הוא בבחי' סילוק האור, שזהו צמצום גדול יותר מענין מיעוט האור שבשרשי האורות כו', הנה זהו לגבי העולמות והיינו שיהי' האור בהעלם בעולמות לא בגילוי כלל (רק ע\"י עבודה דנש\"י יהי' גילוי האור הזה כו'), אבל בעצם האור לא פעל הצמצום, וה\"ה נמשך לאחר הצמצום כמו שהוא לפני הצמצום, רק שהוא בהעלם כו' ועמשית\"ל פ'). ולכן גם כשנמשך האור לאחה\"צ הוא בבחי' אין ובחי' אור הבלתי מוגבל ושלא לפי\"ע העולמות כ\"א בבחי' מקיף לבד כו', וכן בכל מדרי' שנמשך היינו בכל עולם שהאור מקיפו ה\"ז למע' מהצמצום שלפ\"ע העולם ההוא כו', וא\"כ הרי אינו בבחי' ירידה מעצמותו כ\"א הכל כלול\nבעצמותו עדיין כו', ומה שהוא מ\"מ בבחי' המשכה ה\"ז רק בבחי' גילוי מן העצם כו', והיינו שאין זה מה שהאור יורד ומאיר, כ\"א מה שהעצמות מגלה אור שלפי אופן העצם כו' (הבנת הענין הוא כמו עד\"מ הרצון והשכל, הרי השכל הוא אור הנמשך ומתגלה מן הנפש לא התגלות הנפש, הגם שהנפש היא המשכלת, היינו שמשכלת ע\"י כח השכל כו', והרצון הוא התגלות עצמות הנפש וכמשנת\"ל פמ\"ט, והרי זה מ\"מ רצון היינו רק אור הנפש, הנה זהו שהעצמות מגלה אור לא שהאור הוא מציאות דבר בפ\"ע. ולכן גילוי השכל נק' ע\"ש השכל, וגילוי הרצון נק' ע\"ש הנפש וכמו בכל לבבך ובכל נפשך, נפשי איויתך כו', אליך ה' נפשי אשא כו'. וכמו\"כ למעלה הוא שאינו אור היורד ונמשך מן העצמות בבחי' מציאות דבר בפ\"ע, כ\"א הוא בחי' התפשטות והתגלות העצמות, ובבחי' המשכת האור לאחר הצמצום הוא שהעצמות מגלה אור כו', ובאמת כן הוא גם קודם הצמצום וכמשנת\"ל פקכ\"ח), וגם בהמקבלים הרי אינו מאיר בפנימיותם להיות בהם בבחי' אור וחיות פנימי שזהו בחי' גילוי אור אל המקבל להאיר בחי' הכלים שלו כו', דמה שהמקיף\nפועל בהפנימי שנותן כח בפנימי כו' ה\"ז בהעלם כו', והיינו שהגילוי הוא האור פנימי רק שהוא בבחי' תוס' אור"],[3601330679,"ובעומק ופנימית האור יותר בכח המקיף כו', אבל האו\"מ עצמו אינו מאיר בו בגילוי כו', דענין שהמקיף נותן כח בפנימי זהו כמו שיש מזל מחכים שמוסיף אור בכח השכל, דהרי כל ההשכלות וההתחכמות הוא מכח המשכיל כו', אך יש שמתחכם ביותר והו\"ע ההצלחה בלמוד שבכל ענין שעוסק בו ה\"ה משכיל ומתחכם בו בכמה ענינים שכליים מה שלא הי' בו כלל בהשערה מקודם כו', וכמו מזל מעשיר ה\"ה ההצלחה שבאה השפע שלא לפ\"ע הכלי דמה שהוא לפי\"ע הכלי אין זה הצלחה עדיין כ\"א מה שבא שלא בהדרגה כ\"כ כו', וכמו\"כ מזל מחכים הוא מה שבא שלא בהדרגה כ\"כ, וזהו מהמזל שהוא בחי' מקיף דחי' כו' וכמ\"ש במ\"א, והרי אין המקיף מאיר בזה בגילוי דהגילוי הוא האו\"פ רק שבא בבחי' תוס' אור ע\"י כח המקיף כו', ופעולת המקיף בבחי' גילוי הוא שבא במקבלים ג\"כ בבחי' מקיף כו', וכמו בנפש בעבודה הוא שמתגלים הכחות מקיפים שבנפש כמשנת\"ל באורך מפ' ס' ואילך, שאין זה גילוי בפנימיות רק בבחי' או\"מ, ושעי\"ז מתוסף אור וחיות בהפנימי' כו' (וכמו טוב טעם ודעת למדני כי במצותיך האמנתי, שע\"י האמונה\nפשוטה מתוסף טעם ודעת בתורה כו', דבהתגלות האמונה נעשה עי\"ז תוס' אור רב כו', הרי האמונה היא בבחי' מקיף והגילוי הוא האו\"פ כו').\n<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע הנה האו\"מ הוא רק גילוי העצמות, ואינו בבחי' יציאה וירידה מן העצמות, דכללות האור הוא שכלול בעצמותו, אצי' שהיא ג\"כ אור, ה\"ז בבחי' יציאה מן העצמות, ואור הוא הכלול בעצמותו, וכן המשכת האו\"מ אינו דרך הצמצום והמשכתו אינו ירידת האור להאיר, כ\"א שהעצמות מגלה אור, ובהמקבלים הוא רק שנותן כח בפנימי וכמו הצלחת ההשכלה ממזל מחכים, טוב טעם כו' ע\"י שבמצותיך האמנתי, וגילוי המקיף הוא רק בבחי' מקיף.</span>\n<b>רמד)</b> והנה יש גם גילוי בחי' או\"מ שמאיר בפנימיות וכמ\"ש בלקו\"ת בהבי' דאת שבתותי פ\"ד שבשבת נכנסים המקיפים דחול בבחי' פנימיים ונמשכים מקיפים עליונים יותר. והנה במ\"ח מס' שחרית דשבת פ\"א מ\"ב כ' ובשבת אין להניח תפילין מפני שהמוחין דלמ\"ד דצלם שהיתה מקיפה בחול על ראש ז\"א כו' עתה בשבת נכנסה בראשו ונעשו בו מוחין פנימיים עכ\"ל, וכן הוא בפע\"ח שער השבת פי\"ט ועיי\"ש פ\"ז, והנה בחי' ל' דצלם הן בחי' המוחין חב\"ד עצמן שהן בבחי' מקיף לז\"א, ובנשמה הוא בחי' מזל דנשמה כמ\"ש בלקו\"ת בהבי' דכי תצא, ושם דבחי' ל' דצלם יוכל להתלבש לפעמים להיכנס לתוך האו\"פ והכלים, וי\"ל להיות שזהו בחי' מוחין חב\"ד שהן בחי' או\"פ בעצם רק שהן בחי' מקיף לגבי מוחין דז\"א (ועמ\"ש בסי' ע\"פ השמים מספרים מענין עצמות המוחין ומוחין שבמדות) ע\"כ נכנסים לפעמים בתוך האו\"פ כו', ונראה שם בהבי' שזהו כענין מזל מחכים שנת\"ל דהיינו בחי' תוס' אור וגילוי מכח המשכיל שנקרא מזל (ועמ\"ש במ\"א דמזל ונוצר ונקה הוא בחי' ל' דצלם, והיינו לגבי בחי' מוחין דאצי', והוא\nכענין כח המשכיל עד\"מ, וכמו\"כ בחי' חב\"ד לגבי מוחין דז\"א כו'), וכמש\"ש שזה ענין חכמת אדם תאיר פניו מהשכלת שכל חדש שהשכל החדש נמשך מכח המשכיל כו', וצ\"ל דהיינו שנמשך בבחי' תוס' אור מכח המשכיל כו' וכמ\"ש במ\"א, דלכן בשבת יכול האדם להתפלל בכוונה יותר מבחול מפני שהמקיף דל' דצלם מאיר בפנימיות,"],[3601330680,"ושם מבאר הענין ע\"ד ההפרש בין כלים דברי' וכלים דאצי', דכלים דברי' לאו איהו וגרמוהי חד לכן אף שמאיר בהם האור אין האור נקנה בהם להיות לאחדים ממש, וכמו השומע שכל מפי רבו (והיינו דבשעת ששומע השכל מהרב הוא אצלו עדיין בבחי' מקיף ר\"ל לא בבחי' התלבשות ותפיסא ממש בכלי מוחו כו', וכמ\"ש בלקו\"ת פ' שלח ד\"ה טובה הארץ מאוד מאוד פ\"ב יעו\"ש), אבל כשנקנה השכל בו ממש זהו עד\"מ כלים דאצי' שהם מתייחדים ממש עם האור. ועד\"ז יובן ההפרש בין המוחין שבחול שמאירים בחי' מקיף וז\"ע התפילין, ובין המוחין שנכנסים בפנימיות ממש והיינו דהמוחין שלמע' מהמוחין שבמדות בחול הן בבחי' מקיף, ובשבת הן בבחי' פנימי, והו\"ע הכוונה יתירה שבשבת דהיינו העבודה בבחי' עצמיות המוחין חב\"ד, וזהו כניסת המקיף בפנימי כו'. והנה בענין תפילין דמארי עלמא ידוע שזהו בחי' המקיף הנמשך לז\"א מאו\"א, וז\"ע הקב\"ה מניח תפילין הקב\"ה ז\"א מניח תפילין בחי' המקיף כו', וכמ\"ש בזהר ואתחנן דרס\"ב ע\"ב ואלין ארבעה נטלין לון וא\"ו ואתעטר בהו ואלין אינון תפילין דאנח קוב\"ה כו',\nועמ\"ש ע\"ז בסי' שער התפילין, ומבו' במ\"א שזהו כענין מי ברא אלה, אלה הן ו\"ק דז\"א ומי בחי' בינה (דבד\"כ תפילין הן מצד בחי' אימא ועמ\"ש בפע\"ח שער הציצית פ\"ג, ובשער התפילין פ\"א שגם מוחין דאבא כלולים בה, ובמ\"ח מס' תיקון התפילין פ\"ג מ\"א דתפילין דרש\"י הן מצד אימא, וזהו שאו' בק\"ש שעל המטה אם פגמתי באות ה' בביטול תפילין), והנה מדכתי' ברא אלה משמע שאין גילוי בחי' מי ממש בבחי' ז\"א, והוא כמו הנברא לגבי הבורא היינו כמו הברי' לגבי אצי' שאין ערוך ביניהם, וכמו\"כ יש באצי' אבי\"ע דכתר הוא בחי' אצי' שבאצי' וחו\"ב ברי' שבאצי' כמ\"ש בלק\"ת ד\"ה את שבתותי בפי' בורא קדושים, והיינו ע\"ש הכלים דחו\"ב כו' (ועמשנת\"ל פ' קל\"ז דחכ' בחי' אצי' שבאצי' דהיינו בחי' עצמיות ופנימיות הקו כו', ועמ\"ש בדדוש ג' מיני אדם דחכ' הוא בחי' האור שלמע' מהכלים כו', ואפשר דפנימיות בינה שנכלל ביו\"ד דש' הוי' והו\"ע או\"א עילאין הר\"ז ג\"כ בכלל בחי' אצי' שבאצי' כו'), וא\"כ גם בז\"א הכתר שבו שנמשך מת\"ת דאימא זהו אצי' שבז\"א, והט\"ס שבו הן בי\"ע שבו, וזהו מי ת\"ת\nדאימא ברא אלה ו\"ק דז\"א שנחשבים לגבי כמו בי\"ע לגבי אצי', ולכן הכתר או\"מ שאינו מאיר בפנימיות כמו שאצי' נשגב מבי\"ע, וזה\"ע תפילין דמארי עלמא שהן בחי' עטרה וכתר לז\"א (ובהבי' דאלה מסעי דתקס\"ג מבו' דמי היא הפרסא שבין אצי' לבי\"ע שהיא מחיצוניות בינה וכמ\"ש בתו\"א ד\"ה לך לך, וי\"ל דבאצי' בחי' כתר דז\"א הוא בחי' הפרסא שבין חו\"ב לז\"א והו\"ע הרקיע שע\"ג חיוון עילאין דמבטן מי יצא כו', ועמשית\"ל פ' דכתר הוא בחי' פרסא כו'). והנה מי אלה ז\"ע ש' אלקים (ועמ\"ש בלק\"ת ד\"ה והי' מספר פ\"ב בענין פלג אלקים דבחי' אלה עלמא דאתגלייא אינה מסתתרת ומתעלמת ונכללת במקורה עדאתכ\"ס הנקרא מי כו', והיינו שהמדות אהוי\"ר לא יהיו בהעלם בבינה ויהי' רק בחי' האהבה מוסתרת דהיינו האהבה שבתבונת מוחו ותעלומות לבו שזהו כשהן בבחי' עיבור בתבונה וכמ\"ש בסש\"ב פט\"ז בהג\"ה, אלא יהי' התגלות האהוי\"ר שע\"פ הדעת והשגה בהתבוננות אלקי כו', וכמש\"ש בהבי' שזהו גילוי בחי' חו\"ג המגולים דהיינו האהוי\"ר שע\"פ טו\"ד כו', וזהו מבחי' המוחין המאירים בז\"א היינו בהמדות בבחי'\nפנימי, אבל עצמות המוחין להיות בחי' פנימיות הלב שזהו גילוי בחי' חו\"ג המכוסים והוא גילוי בחי' מי, הנה זהו רק בבחי' מקיף שאינו מאיר"],[3601330681,"בגילוי כו' וזה ענין התפילין כו'. ובד\"ה אלה מסעי הנ\"ל דמי ברא אלה שיהי' ההתבוננות וההרגש איך שהאין מהווה את היש ושיהי' ביטול היש לאין כו', ובמ\"א בה\"ע דהנה בש' אלקים תיבת אלה קודם לתיבת מי, וידוע דהראשון גובר ולכן נראה העולם ליש ודבר, והיינו שנראה הגילוי שנתהווה מציאות הנבראים, ואינו נראה כלל דבר המהווה את הדבר שהוא בחי' מי, אבל ענין מי ברא אלה בהיפך שתיבת מי קודם (וי\"ל שז\"ע פלג אלקים) להתבונן ולידע שבחי' מי בורא ומהווה כל ההתהוות שבגילוי שנק' אלה, והיינו גילוי בחי' ש' הוי' שבש' אלקים (דהיינו בחי' האמת דש' אלקים בחי' יחו\"ת כו' וכמ\"ש במ\"א) דש' הוי' הוא המהווה כו', ויהי' זה בבחי' ראי' שז\"ע וראו מי ברא כו', ועמ\"ש בתו\"א תשא ד\"ה שמאלו תחת לראשי ובלקו\"ת ד\"ה ואתחנן, וי\"ל דזה דבשם אלקים צירוף מי הוא בהיפך אתוון ים ויו\"ד היא בחי' חכ' שזה הגובר, והיינו להיות בבחי' ראי', וא\"ז בחי' ראיית המהות ממש רק כאילו רואה, דבהתבוננות והשגה זו יכול להיות כמו ראי' חושיות ועמשנת\"ל פ' רכ\"ו. והנה ענין התפילין הוא\nשיהי' בחי' מי בבחי' מקיף עכ\"פ (ובמ\"א דהיינו שנמשך החיצוניות דבחי' מי דהיינו בחי' האהוי\"ר שע\"פ טו\"ד כו'), וי\"ל שזהו בחול הביטול דשמו\"ע שזהו בחי' חו\"ג המכוסים וכמ\"ש במ\"א בדרוש אלה תולדות נח דחו\"ג מכוסים וחו\"ג מגולים, דהביטול הזה יש גם בחול (והוא ע\"י מצוות תפילין, וכמ\"ש בלקו\"ת בד\"ה והי' מספר שם דקודם התפלה ממשיכים עליו מצוות ה' בטלית ותפילין), ובחול זהו רק בשמו\"ע וג\"ז בבחי' מקיף לבד וכמ\"ש בד\"ה אלה תולדות הנ\"ל שצ\"ל הביטול בחיצוניות, והביטול פנימי בזה הוא רק בבחי' מקיף כו', ובשבת הוא שהעבודה היא בבחי' ביטול זה כו' וכמשי\"ת, גם י\"ל ע\"פ מ\"ש בתו\"א ד\"ה בכ\"ה בכסלו בענין שמן המנורה שהוא בחי' אור החכ' כו', ומבו' במ\"א שבהתגלות המדות שע\"פ טו\"ד צ\"ל בהעלם בחי' הביטול עצמי שמבחי' החכ' שבנפש כו').\n<span data-k=\"ks\"><b>קיצור.</b> והנה בשבת המקיף נכנס בפנימי, והיינו בחי' למ\"ד דצלם, עצמיות מוחין חב\"ד, שהן בבחי' מקיף לז\"א בחול, והו\"ע התפילין שבולטין, ובשבת נכנס בפנימי דבחי' אצי' מתיישב בכלים דברי', ולכן תפלה דשבת היא בכוונה יותר, גילוי בחי' חב\"ד, דהנה ענין התפילין הוא מוחין דאי' מקיף לז\"א, מי ברא אלה, אלה ו\"ק דז\"א, ומי ברא אלה, כערך ברי' לגבי אצי', כתר אצי' שבאצי', וכן ת\"ת דאי' בחי' מי כתר לז\"א בחי' אצי' שבז\"א, מקיף לז\"א, והנה מי אלה אותיות אלקים, וכתי' פלג אלקים דבחי' אלה עדאת\"ג שנראה העולם לא יסתיר, ויהי' נראה ונרגש האין המהווה, ויהי' כאלו רואה, וזהו צירוף ים, והו\"ע הוי' שבאלקים אמת דאלקים בחי' יחו\"ת, ובחי' מקיף דמי י\"ל ביטול דשמו\"ע, גם י\"ל בחי' ביטול דחכ' בבחי' מקיף על המדות.</span>\n<b>רמה)</b> אבל בשבת גילוי ש' הוי' ממש והיינו כשז\"א יורש מקום או\"א ממש (עמ\"ש בלק\"ת מהאריז\"ל פ' בראשית ד\"ה ועתה נבאר מעלת אד\"ה קודם שחטא, ובשמ\"ש שער מאמרי רשב\"י פ' קדושים), א\"כ הבחי' שהי' מקיף וכתר עליון נכנס בו בבחי' פנימיות ממש ונמשך לו הכתר מבחי' עליונה יותר (והיינו דבחי' אצי' שבז\"א מאיר בו בבחי' פנימי יותר, וכמו דבעליית העולמות"],[3601330682,"בשבת הרי בי\"ע עולה באצי' ומאיר אור האצי' בכלים דבי\"ע, וכמ\"ש במ\"א בפי' ביום השביעי נתעלה וישב על כסא כבודו דהיינו שהכלים דברי' עולים באצי' ומאיר בהם אור האצי' כו', וכנ\"ל שאור האצי' הוא בשבת בבחי' התיישבות והתאחדות בכלים דברי' כו', וכמו\"כ בחי' בי\"ע דז\"א עולה ומאיר בהם היינו בט\"ס דז\"א בחי' הכתר שזהו בחי' אצי' שבו כו' כנ\"ל. ולפמ\"ש בלק\"ת בהבי' דוהי' מספר י\"ל שזהו גילוי בחי' אהוי\"ר המכוסים דהיינו בחי' פנימיות הלב כו', ומבו' במ\"א וית' ג\"כ לקמן שזהו מבחי' פנימיות המוחין, דהיינו כאשר ההשגה היא בעצם הענין שלא בבחי' התלבשות בלבושי השגה, ואזי מאיר בלב ג\"כ בחי' עצמיות המוחין ומתפעל ממילא בלבו בבחי' התפעלות פנימי ובלתי מורגש וכמו המוחין כו', וי\"ל שז\"ע ישראל כי שרית עם אלקים, דהנה מי ברא אלה נת' לעיל שזהו לידע ולהרגיש האין האלקי ולהיות ביטול היש לאין שזהו בחי' ה' שבשם אלקים, והעבודה היא בבחי' אתכפיא כו', אבל בחי' פנימיות הלב הוא בחי' גילוי ש' הוי' היינו בחי' ביטול אמיתי, והוא מדריגת ישראל כי שרית עם\nאלקים כו', וידוע דעבודה דחול הוא בחי' יעקב עבדי, ועבודה דשבת הוא בחי' ישראל וכמ\"ש בלק\"ת ד\"ה לא הביט און ביעקב וע\"ש בהבי', ועמ\"ש בתו\"א בד\"ה מזוזה מימין ובהבי' בענין גדול הוי' מכל אלקים שמושל על בחי' אלקים כו', ועמ\"ש בהגהות לדרוש זה בס' תרט\"ו, והגם שכתב שם שזה ענין ביטול היש, הנה הכוונה שם הוא על ביטול היש בעצם המציאות והוא מבחי' החכ' והו\"ע והחכ' תעוז לחכם יותר מעשרה שליטין שבעיר, דעשרה שליטין הן העש\"מ והוא בחי' האין האלקי שמזה הוא ביטול היש כו', והחכ' תעוז לחכם להיות בבחי' ביטול בעצם המציאות כו' וכמ\"ש במ\"א, ושם דהציור הוא מבחי' חפץ הוי' ובהגהות לשם דהציור הוא מבחי' בינה וזהו מי מדד, מי בחי' בינה כו' יעו\"ש. גם י\"ל ענין המשכת בחי' מי עפמ\"ש במ\"א בענין שיש ב' בחי' שושנה, כשושנה בין החוחים בחי' מל', ויש שושנת העמקים בחי' בינה, והן ב' בחי' כלה שבשה\"ש דמבו' בלק\"ת ד\"ה שה\"ש שהן ב' מס\"נ דק\"ש למס\"נ באחד ובכל נפשך, והוא מ\"ש כלתה נפשי לחצרות ה' שהוא ל' תשוקה והיינו תשוקת הנפש לידבק ולהיכלל באורו ית',\nוז\"ע בכל נפשך שהוא בחי' הרצון להכלל כו', אמנם למס\"נ באחד הוא כמ\"ש כלה שארי ולבבי אשתצי גושמא, והו\"ע הכליון שמכלה ומבלה הכל (עמ\"ש בהגהות הנ\"ל פ\"ג) והוא בחי' ד\"ע שכולא קמי' כלא חשיב ממש כו', וז\"ע שושנת העמקים העמקים מל' עומק בחי' העומק דש' הוי' (י\"ל דהיינו בחי' עצם ש' הוי' שלמע' משם הוי' שבשם אלקים כו'), דשם הוא דיעה העליונה דיחו\"ע איך שכולא קמי' כל\"ח כו' וזהו בחי' בינה. והגם דנתבאר בזוהר דבחי' בינה א\"א לקרוא בשם כלה, כי חו\"ב הם תרדל\"מ ובחכ' מאיר אוא\"ס ב\"ה, כי חכ' היא בחי' כח מ\"ה דאוא\"ס שורה במקום הביטול דוקא, וע\"כ עיקר השראת אוא\"ס בחכ', ונק' אחד האמת כו' וכמ\"ש בסש\"ב פל\"ה בהג\"ה, וממילא מאיר גם בבינה כי הם תרדל\"מ כו' (וצ\"ל דהיינו בבחי' פנימיות בינה, דבחיצוניות בינה הרי מאיר רק השכלי דחכ' כו' וכמשנת\"ל פמ\"ב והיא בחי' ד\"ת כו', ופנימיות בינה היא ההשגה בעצם הענין האלקי שבזה נרגש גם עצם האור כו' ועמשנת\"ל פקל\"ט בענין יחוד פנימי כו'), והיינו שאינו שייך לקרות בינה בשם כלה ל' כלתה נפשי ל' תשוקה\nדענין התשוקה שייך על ההעדר כמו צמאה לך נפשי כו' בלי מים, אבל כשעומד אצל המים על שפת הנהר אינו שייך בחי' צמאון כו', ולכן מאחר שחו\"ב הן תרדל\"מ"],[3601330683,"לזאת אינו שייך לקרות הבינה בשם כלה ל' כלתה נפשי כו'. אבל כלה מל' כלה שארי ולבבי בחי' כליון ממש זה שייך בבחי' בינה להיות כי שם מושג איך דכולא קמי' כל\"ח כו', וז\"ע שושנת העמקים בחי' עומק הוי' היינו בחי' החכ' שנק' אחד האמת איך שהוא לבדו הוא ואין זולתו, ולהיות דחו\"ב הן תרדל\"מ ה\"ז מאיר גם בבינה שמושג שם איך שכולא קמי' כל\"ח כו', וזהו גילוי בחי' מי דהיינו שגם למטה יהי' מושג דיעה העליונה איך שכולא קמי' כל\"ח ויהי' בחי' הביטול דיחו\"ע, ועמ\"ש בד\"ה כי תצא הנ\"ל דל' דצלם הוא גילוי עצמות נקודת הלב בחי' אצי', ושם שזהו בחי' פרצוף הפנימי דמל' כו', ובהביאור הב' דשחורה אני ונאוה פ\"ב דמל' כמו שהיא באצי' היא בחי' שכינתא עילאה כמו בחי' הבינה כו', והו\"ע כאמה בתה כו', ועמ\"ש בד\"ה שה\"ש ספ\"א. וזהו העבודה דשבת דבחול העבודה היא בבחי' ד\"ת ובשבת בבחי' ד\"ע כו', ועמ\"ש בלק\"ת ד\"ה צאו\"ר דרוה\"ב פ\"ד בענין נכנס יין יצא סוד, סוד הוא דבר המוסתר ומוצנע, וכך הנה העולם נראה ליש ודבר, ובאמת הוא בטל במציאות לגבי אור הוי' המהווה אותו,\nרק שביטול זה מוסתר כו', וע\"י יין שהוא בחי' ההתבוננות יצא הסוד בגילוי כו', והיינו דיין הוא יינה ש\"ת פנימיות התורה שעי\"ז מתגלה הסוד סתום שבעולם כו', ושם דבעבודה הוא גילוי בחי' אה\"ר והו\"ע עשה רצונו כרצונך כו' וכמש\"ש לעיל מזה, והיינו כמ\"ש באגה\"ק בקונטרס אחרון ד\"ה להבין מ\"ש בפע\"ח דידיעת ההשתל' היא מצוה רמה כו' ומביאו ללב שלם כו' ובהבי' דלא תשבית ספ\"ד שזהו בחי' יר\"ע כו', ועמ\"ש בד\"ה לריח שמניך טובים הא' שז\"ע מי גילה לבני רז זה גילוי בחי' מי כו', וזהו שמתגלה בשבת וכמ\"ש בתו\"א פ' שמות ד\"ה כי טובים דודיך מיין (ולכן בשבת העיקר הוא הלימוד בפנימיות התורה כו' וכמ\"ש במ\"א), וזהו ג\"כ דבחול הוא בחי' יעקב עבדי ובשבת בחי' ישראל שזהו בחי' ש' הוי' שלמע' מש' אלקים כו', וגם ביטול היש הוא בעצם המציאות שז\"ע כלה שארי שמבלה הכל אשתצי גושמא כו', ובאמת זהו עוד יותר מבחי' ביטול היש הנ\"ל, ואפשר זהו מה שבשבת גם התענוג הגשמי הוא תענוג אלקי כו' וכמ\"ש במ\"א, וזהו ביטול ההגשמה שהכל הוא אלקות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובשבת בחי' מי כתר דז\"א בחי' אצי' שבו מאיר בז\"א בבחי' או\"פ, וי\"ל שזהו גילוי חו\"ג המכוסים פנימיות הלב, דההשגה שבפנימיות המוחין מאיר גם בלב, והוא גילוי ש' הוי', ישראל כי שרית, והביטול היש הוא בעצם המציאות מכח החכ' שבנפש. גם י\"ל שהו\"ע שושנת העמקים, מס\"נ דאחד, בחי' כלה עילאה כלה שארי, דבחי' ד\"ע שבחכ' מושג גם בפנימי' בינה, וזהו גילוי מי שיהי' מושג למטה, והו\"ע גילוי עצמות נקודת הלב, וזהו נכנס יין יינה ש\"ת פנימיות התורה, יצא סוד בחי' ד\"ע.</span>\n<b>רמו)</b> והנה ענין המקיף דשבת י\"ל שזהו ענין ואמת הוי' שמבו' במ\"א שזהו אמיתית דש' הוי' שלמע' מש' הוי', והוא בחי' אין האמיתי כמו שהוא קודם שמתצמצם ומתלבש בד' אותיות הוי', והוא בחי' ד\"ע שלמע' מאצי' ובשרשו הוא בחי' אוא\"ס שלפני הצמצום כו', וכמ\"ש בדרוש יו\"ט של ר\"ה, רס\"ו, וי\"ל שהו\"ע בחי' אהבה בתענוגים להתענג על הוי' עד כלותה כו', ולא בבחי' כליון ממש דהרי לשבת יצרה רק שזהו בבחי' התכללות ממש באוא\"ס ב\"ה, וע\"ה שזהו ג\"כ בבחי' הרגש פנימי, הרי עיקר ענינו הוא בבחי' כליון ובבחי' או\"ח אל עצמותו"],[3601330684,"ה\"ז בחי' מקיף כו', ועמ\"ש בד\"ה כי טובים דודיך הנ\"ל בענין ערבים עלי ד\"ס, והו\"ע ברכת המצוות אשר קדשנו, אשר בחי' תענוג כו', והוא עובר לעשייתן בחי' מקיף כו' (ועמ\"ש במ\"א בענין קדשנו במצותיך שאו' בשבת היינו שיהי' גילוי בחי' מצותי כו'), ועמ\"ש בד\"ה חכלילי עיניים מיין ובהבי' שם, והו\"ע אז תתענג על הוי' שלמע' מבחי' וקראת לשבת עונג כו' וכמ\"ש במ\"א. גם י\"ל שזהו בחי' יחיד שלמע' מאחד, וכמ\"ש בתו\"א ד\"ה וארא הא' דאחד הוא בסדר השתל' שכולל ו\"ק ויחיד הוא בחי' עצמות אוא\"ס שלמע' מהשתל' כו', ובד\"ה שמע ישראל בלק\"ת פ' ואתחנן שזהו הב' שמות הוי' שבפ\"ר דק\"ש, והיינו דהוי' אחד הוא שם הוי' דלתתא שבסדר השתל', דהנה ידוע דש' הוי' הוא שרש האורות והיינו בחי' האור כמו שהוא למעלה עדיין מהתלבשות בכלים (דבהתלבשות האור בכלים דע\"ס נק' אל הוי' במדת החסד והוי' אלקים במדת הגבו' ובת\"ת גם הכלי שם הוי' ובנו\"ה נק' הוי' צבאות כו' וכמ\"ש במ\"א), וכידוע דהקו מראשית המשכתו עד שמתלבש בע\"ס דאצי' יש בו ש' הוי' וכמ\"ש במ\"א, וידוע דהד' אותיות הוי'\nמורים על הצמצום יו\"ד בחי' נקודה ה' התפשטות שאחר צמצום הנקודה כו' וכמ\"ש במ\"א שהן ד' צמצומים בהאור כו', הרי שיש מדה והגבלה בהאור, ומ\"מ אינו בבחי' התחלקות להיות שהוא המדידה בהאור עצמו שלא יש דבר המגביל אותו כ\"א מה שהאור בא במדה והגבלה כו'. ויובן זה עד\"מ מדידת אור השכל השייך אל המקבל שהמשפיע מודד בעצמו שאין זה בבחי' פרטים ובבחי' התחלקות כו' וכמ\"ש במ\"א, גם יובן עד\"מ קול ודבור שהקול הוא פשוט בלי התחלקות, ואותיות הדבור הן בבחי' הגבלה והתחלקות בעצם, וכאשר הקול מתלבש באותיות הדבור גם הוא נחלק לחלקים, אבל קודם שמתלבש בהאותיות ה\"ה קול פשוט כו' וכמ\"ש באורך בסי' בד\"ה אד' שפתי תפתח, והרי הקול ג\"כ מורכב מאמ\"ר ומ\"מ הוא קול פשוט, והיינו מפני שההרכבה הוא בעצם הקול שאין כאן ד\"א המגביל אותו כ\"א שהקול הוא בעצם מורכב מאמ\"ר כו' ה\"ז הרכבה פשוטה בלי התחלקות כו'. וכמו\"כ יובן דהד' אותיות הוי' זהו המדידה בעצם האור שאין זה בבחי' התחלקות (ועמשי\"ת לקמן פ' שגם בהע\"ס הוא בבחי' אחדות וכמשל הקול ודיבור כו', והאמת כן הוא\nדאצי' הוא בחי' יחו\"ע (וכבר נת' דגילוי המקיף שמאיר בשבת בפנימי הוא בחי' גילוי האצי' כו'), וכ\"ש שכן הוא בהאור שלמע' מהתלבשות בכלים כו'), ועמשנת\"ל פל\"א דנקודות שבהקו שהן בחי' הספי' ה\"ה בבחי' פשיטות ובבחי' בלי מ\"ה כו', וז\"ע הוי' אחד, ומ\"מ ה\"ז התאחדות הפרטים ושייך בהאור שבא בהשתל' עכ\"פ. אמנם ש' הוי' דלעילא הוא בחי' עצמות אוא\"ס שלמע' מהשתל' דאינו שייך שם שום מדה והגבלה כלל ה\"ז בחי' יחיד שמיוחד בעצם כו', והגם דגם שם יש ד' אותיות וכמ\"ש במ\"א שגם בהש' הוי' שברצון יש הד' צמצומים בכח כו', זה יובן ע\"פ משנת\"ל פ\"ל בג' מדרי' שבאור דהאור כמו שהוא במקורו הוא בבחי' חד ממש כו', ועיין משנת\"ל פי\"ט דע\"ס הגנוזות הן בבחי' פשיטות ממש כו', ובאמ\"ב שער הק\"ש פ\"ח שגם ע\"ס הגנוזות הן בחי' אחד, והיינו כמו שנת\"ל פט\"ז דע\"ס הגנוזות הן בבחי' עלות הרצון וש' הוי' דלעילא הוא בבחי' אוא\"ס שקודם עלות הרצון כו', ולפמ\"ש בשער היחוד בהג' מדרגות דיחיד אחד וקדמון באוא\"ס שלפה\"צ, בחי' יחיד הוא בחי' עצם האור שלמע' גם מקודם בחי' עלות\nהרצון, דבבחי' קודם עלות הרצון ג\"כ שייך ספי' רק שאין מספר לספי' וכמ\"ש בהבי' דקול דודי כת\"י הר\"פ ז\"ל, והו\"ע הוא ושמו"],[3601330685,"אחד בחי' אחד כו', ויחיד הוא בחי' עצם האור שאינו שייך שם ענין הספי' כלל כו', וכמ\"ש השל\"ה דהוא ר\"ת הוא ושמו אחד והיינו דהוא שמו ושמו הוא כולא חד ממש כו'. וי\"ל דזהו מ\"ש שער החצר הפנימית הפונה קדים (בחי' א\"ס קדמונו ש\"ע) סגור יהי' ששת ימי המעשה וביום השבת יפתח, ימי המעשה וביום השבת ר\"ת הוי' נאמר הש' הוי' ברמז בר\"ת ולא מפורש, והיינו דעצם האור הא\"ס הוא למע' מאותיות ממש דהוי' רק ברמז לבד כו', וזהו שנמשך בשבת בבחי' מקיף כו', ועמ\"ש בתו\"א ד\"ה וארא הב' בענין יחוד הוי' ואלקים שיהי' גילוי בחי' ש' הוי' דלתתא, וי\"ל שזהו בחי' מי אלה וכנ\"ל דאלקים הוא מי אלה שמאיר רק הארה דש' הוי', וגילוי בחי' מי הוא שמאיר גילוי ש' הוי' וזהו שמאיר בשבת בבחי' פנימי כו' ושמי הוי' הוא בחי' ש' הוי' דלעילא בחי' יחיד כו', ובנפש הוא גילוי בחי' יחידה שבנפש שמקבלת מיחיד כו' וכמ\"ש בלק\"ת ד\"ה שמע ישראל, והוא בחי' מ\"ם דצלם בחי' מקיף דיחידה כו'). והנה ענין ת\"ת דאימא שנעשה כתר לז\"א מבו' בסי' ובלק\"ת בהבי' דכי על כל כבוד שזהו בחי' המדות\nשבשכל ושנעשה כתר לז\"א זהו בחי' רצון התחתון כו', וכמש\"ש בענין אית רצון ואית רצון כו', וי\"ל שזהו כמ\"ש בד\"ה בהעלותך הא' שהרצון הוא פנימיות המדות כו', והיינו שהוא רצון הנולד מן השכל והוא למע' מהמדות ומנהיג את המדות כו', דרצון זה יש בו גם היפך טבע המדות וכמש\"ש שלא יתענג בדבר של תענוג, ויתענג בדבר של צער כמו בסיגופים וכה\"ג (ועמשנת\"ל פר\"ב), והוא ג\"כ מצד השכל שמחייב שצ\"ל כך ומשום זה הוא רוצה כך ומתענג בזה כו', ולגבי המדות הוא בחי' מקיף (ועמ\"ש בלק\"ת ד\"ה ויקח קרח ספ\"א בענין המח' שבמוח היא בבחי' פנימי, ובהג\"ה שם שז\"ע שבשבת המקיפים נכנסים בבחי' פנימי כו', י\"ל שזהו כענין בחי' רצון הנ\"ל שהוא בחי' מקיף על המדות ובשבת מאיר בבחי' פנימי כו'), וי\"ל שפועל בהמדות בדרך הכרח היפוך טבעם, כמו הרצון שפועל בדרך כח עליון בבחי' הכרח כו' וכמשנת\"ל פנ\"א. ובעבודה הוא שיהי' כל חפצו ורצונו לה' לבד ולא יהי' לו חפץ ורצון אחר זולתו כו', והוא ע\"י ההתבוננות בה' אחד כו' וכמ\"ש בלק\"ת שם, ועמ\"ש בתו\"א פ' תצוה ד\"ה זכור את אשר עשה\nלך עמלק בענין פנים ואחור דנפש האלקית, פנים הוא בחי' פנימיות הלב ששורה ומתגלה בו בחי' ה' אחד בגילוי ממש כו', ואזי האהבה היא שאין לו חפץ ורצון אחר רק לה' לבדו כו' וכמש\"ש לעיל מזה בד\"ה והנה ענין כו', וזהו העבודה דשבת בבחי' פנימיות והוא מדרי' ישראל כי שרית כו' וכנ\"ל. ומכל הנ\"ל יובן דבחי' המקיף שמאיר בשבת בפנימיות אין זה בחי' מקיף ממש רק מה שלמע' מבחי' פנימי כו', וגילוי המקיף ממש שיהי' בבחי' פנימי זה יהי' לעתיד, וכידוע דלעתיד יהי' חיבור המקיף עם הפנימי, כי הקו יהי' גם בקצהו התחתון נוגע ודבוק באוא\"ס כו' ואזי גם אמיתית המקיף יאיר בבחי' פנימי ממש כו' וכמ\"ש במ\"א. וע\"פ הנ\"ל יובן דבבחי' או\"מ אינו שייך ענין נעוץ תחלתן בסופן, להיות דכללות האור הוא רק בבחי' גילוי מן העצם ואינו בבחי' ירידה מן העצמות כו', ובהמקבלים ג\"כ אינו בא בבחי' פנימיות כו', ע\"כ לא יש בזה היתרון שמצד המקבל בבחי' נעיצת התחלה שבו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וענין המקיף דשבת י\"ל בחי' ואמת הוי' ד\"ע שלמעלה מאצי', וי\"ל שהו\"ע אהבה בתענוגים, וזהו אשר קדשנו בחי' התענוג אז תתענג על</span>"],[3601330686,"<b>הוי'</b>, וי\"ל שז\"ע יחיד, הוי' אחד ש' הוי' דלתתא, והד' אותיות הן בחי' מדידה, אך זהו בעצם האור, שזהו בבחי' אחדות, וכמו הקול שמורכב באמ\"ר ומ\"מ הוא קול פשוט, ויחיד ש' הוי' דלעילא אנת הוא חד, ע\"ס הגנוזות, או בחי' אוא\"ס שקודם עלות הרצון, ועיקר בחי' יחיד הוא עצם האור, והו\"ע הפונה קדים קדמונו ש\"ע דבשבת יפתח, וש' הוי' הוא ברמז לבד והוא גילוי בחי' יחידה מ' דצלם, וענין ת\"ת דאי' בחי' רצון התחתון שלמעלה מהמדות, והגילוי בפנימיות הוא להיות רצון א' לה' לבדו, וגילוי אמיתת המקיף בבחי' פנימי זה יהי' לעתיד, ומפני שהאו\"מ אינו מאיר בפנימי ע\"כ אינו שייך בזה ענין נתב\"ס.\n<b>רמז)</b> אמנם האו\"פ הרי כללות ענינו הוא להאיר את העולמות כו', ועם היות דאור זה הוא ג\"כ בבחי' גילוי מן העצם כו', הרי זהו מה שנמצא מן העצמות אור שלא לפי אופן העצמות ממש כו' וענינו הוא לפעול, היינו פעולת ההתהוות (שההתהוות בפועל הוא מן האור כו') והעיקר פעולת האור והגילוי כו', ואור זה בא בבחי' ירידה מן העצמות שהרי המשכתו הוא ע\"י הצמצום דוקא שזהו בבחי' ירידה ויציאה מעצמותו כו' (והיינו שזהו בבחי' ירידה גם לגבי האו\"פ כמו שהוא כלול בעצמותו כו', וכמ\"ש בלק\"ת ד\"ה תקעו הב' שהקו הוא בחי' יש מאין לגבי מקורו כו', וכמשנת\"ל מפי\"ט ואח\"ז שהע\"ס הגנוזות הן בבחי' פשיטות לגמרי והן בבחי' יחיד כו' ובקו באים בבחי' מדרי' פרטיות בבחי' מציאות כו'), ובכל מדרי' ומדרי' שהאור נמשך ה\"ה בא בבחי' צמצום להיות לפ\"ע המדריגה ההיא ולהתלבש בבחי' פנימי' דוקא דהיינו להאיר את בחי' הכלים להיות בבחי' אור וחיות פנימי בגילוי ממש כו', וכמו באור וחיות הנפש בגוף הרי האברים מרגישים את החיות מפני שבא בהם בבחי' התלבשות פנימי בגילוי\nכו', וכמו\"כ הוא שבא בגילוי ממש בבחי' התלבשות פנימי כו'. והנה זה גופא שיהי' האור בבחי' פנימי זהו ע\"י שהאור הוא בתחלה בהתלבשות בבחי' כלים שעי\"ז דוקא הוא בא בבחי' פנימי כו', דכל התלבשות בבחי' פנימיות הוא ע\"י לבוש המלביש את האור שז\"ע הכלים כו', והיינו מפני שע\"י הכלים נעשה האור בבחי' מציאות ובא בבחי' הגבלה להיות בערך התלבשות פנימי כו', כי האור בעצם גם האו\"פ הוא מובדל בערך מבחי' התלבשות ותפיסא באיזה דבר מה כו' (והראי' שגם כמו שנמשך ע\"י הכלים ה\"ה ג\"כ בבחי' הבדלה וכמ\"ש אין קדוש כהוי' כו' כנ\"ל), וע\"י הכלים נעשה האור באופן כזה שיהי' בערך ההתלבשות כו' (והיינו מצד שרש הקדום של הכלי שלמע' מן האור כו', והו\"ע נעיצת התחלה שבהכלי דהיינו אמיתת הכוונה העליונה להיות גילוי אור בבחי' או\"פ דוקא כו'), לפי שכללות ענין הכלים הוא בחי' המציאות ובחי' הירידה דוקא היפך האור שטבעו לעלות כו' כנ\"ל פרל\"ט וית' לקמן באורך, והו\"ע רוח האדם העולה הוא למע' דאדם בגימ' מ\"ה והוא בחי' האור בכלל דטבעו הוא לעלות למע' דוקא להכלל\nבמקורו כו', ורוח הבהמה היורדת למטה דבהמה בגימ' ב\"ן שהוא בבחי' ירידה והמשכה למטה דוקא כו', והו\"ע הכלים בכלל שהן בבחי' ירידה דוקא וכמ\"ש במ\"א. וע\"י הכלים בא האור בבחי' ירידה והמשכה כו' דע\"י שהכלים תופסים את האור והאור מתלבש ומתאחד עם הכלים נעשה האור כמהות הכלי גם בזה להיות בבחי' המשכה והתלבשות כו', דכשם שהאור נעשה כמהות הכלי לפעול דבר שאינו לפ\"ע האור בעצם, וכמו ענין ההתהוות דאיהו וגרמוהי חד לברוא בהן"],[3601330687,"וע\"י כו', דהאור בעצם אינו בערך להוות מציאות יש רק ע\"י הכלי כו', כמו\"כ נעשה האור כמהות הכלי להיות בבחי' ירידה והתלבשות כו'. ולכן הגם שבכלים יש מדרי' חלוקות שמובדלות זמ\"ז כמו בחי' הכלים שבכתר שמובדלין במעלתן ומדריגתן לגבי בחי' הכלים דאצי', וכידוע דכלים שבכתר הן עד\"מ אותיות החקיקה שהן בבחי' מיני' ובי' לא בבחי' דבר נוסף על העצם כו', וכלים דאצי' הן כמו אותיות הכתב שהן דבר נוסף כו', ומ\"מ ע\"י הכלים שבכתר נעשה האור בערך להתלבש בבחי' כלים דאצי' כו', והיינו מפני שגם כלים שבכתר הן בבחי' כלים עכ\"פ דהיינו שהן בבחי' טבע הירידה כו' וגם הן בבחי' מציאות כו', וכידוע דבאותיות החקיקה גופא יש ב' מדרי' הא' כמו אותיות החקוקים על האב\"ט דעם היות שאינם דבר נוסף ה\"ה משחירים עכ\"פ על האב\"ט דהיינו שהן בבחי' מציאות דבר המעלים כו', והב' כמו אותיות החקוקים מעבר לעבר שאינם בבחי' מציאות כלל כו', והוא ההפרש בין בחי' אותיות שלפה\"צ ואותיות שלאחר הצמצום כו', והיינו דכלים שבכתר הן בבחי' מציאות עכ\"פ כו' וע\"י התלבשות ותפיסת\nהאור בבחי' הכלים שבכתר נעשה האור בבחי' מציאות ובבחי' ירידה והמשכה להתלבש בבחי' הכלים דאצי' כו'. וי\"ל דבחי' א\"ק להיות שאין שם בחי' כלים (וכמ\"ש בע\"ח דהתחלת התגלות הכלים הוא בעקודים כו'), ולכן גם בבחי' יושר דא\"ק הגם שנמשך בכל המדרי' עד סוף העשי' כו', וכידוע דרגלי א\"ק מסתיימים בעשי' כו', הרי אין זה בבחי' התלבשות ממש להיות בבחי' גילוי ומורגש בנבראים כו', וכמשנת\"ל פ\"ס בענין ידיעה ובחירה שהידיעה העליונה אינה מכרחת את הבחירה להיות הידיעה בבחי' א\"ק שאין זה במורגש כלל בנבראים כו', וגם בנש\"י שמוכרח שיהי' בהם גילוי הארת בחי' א\"ק בכאו\"א כו' וכמ\"ש בלק\"ת ד\"ה למנצח על השמינית, אין זה בבחי' גילוי אור פנימי כ\"א הוא בבחי' התגלות אור מקיף שבנפש כו' וכמשנת\"ל פס\"א, ובכללות הרי אור הקו הוא בחי' אור פנימי והיינו ע\"י המשכתו מבחי' הרשימו שזהו כדוגמת כלי כו' וכמ\"ש בע\"ח בהתחלתו בהג\"ה, והן האותיות דגליף גליפו בטה\"ע שע\"י הצמצום נעשו בבחי' מציאות כו', דהגם שבהאותיות לא נגע בהם הצמצום כו', מ\"מ בהתגלות האור בהם לא הי'\nבבחי' מציאות כלל וע\"י שנתעלם האור נעשו בבחי' מציאות כו'. וזהו דבבחי' או\"פ דוקא הוא ענין נעוץ תחלתן בסופן, דהנה ע\"י שהאור העליון בא בבחי' התלבשות בהתחתון להיות בבחי' גילוי ממש אל התחתון עי\"ז דוקא נעשה בחי' תוס' אור בהעליון ע\"י ההשפעה כו', וכמו שאנו רואין בחוש בהשפעת השכל שדוקא ע\"י שמשפיע את השכל באופן כזה שמתקבל בהמקבל שתופס הענין ומבין ומשיג אותו עי\"ז דוקא מתוסף אור בהמשפיע כו', דכאשר המשפיע משכיל את השכל לעצמו הגם שזהו במדרי' גבוה ונעלה יותר אין בזה תוס' אור, כ\"א בהכנת ההשפעה אל המקבל שמשער חושי המקבל שבאופן כזה תהי' ההשפעה וכ\"ש בהשפעה בדבור אז דוקא מתוסף אור במשפיע כו' וכמו שנת\"ל פרל\"ח. וכן הוא ביחוד דו\"נ דכתי' ויברך אותם אלקי' כו' וכתיב בעטרה שעטרה לו אמו ביום חתונתו כו', שז\"ע א\"ח עטרת בעלה כו' כידוע ומבו' במ\"א, ה\"ז דוקא ע\"י השפעה פנימיות כו', וכמ\"ש והוא כחתן יוצא מחופתו שיוצא מבחי' המקיף להיות בבחי' גילוי בבחי' או\"פ כו', עי\"ז דוקא מאיר בו אור העליון שרש ומקור המקבל כו' וכמ\"ש במ\"א. היוצא מהנ\"ל דזה נהנה וזה לא חסר כלל הוא בהאור שלמע' מבחי' כלים (והוא ההשפעה שמבחי' רוממות"],[3601330688,"וגדולה כו') ואין שום שינוי ע\"י ההשפעה, וכמו\"כ אין בזה תוס' אור כו', ועיקר ההשפעה בבחי' או\"פ הוא בבחי' זה נהנה וזה חסר קצת, דהיינו שבבחי' התעסקות והתלבשות המשפיע שיורד ומצמצם עצמו להשפיע ולהאיר אל המקבל (והוא ההשפעה שמבחי' הביטול והנחת עצמותו של המשפיע כו'), שזה גורם שינוי בהמשפיע כו', והוא ההשפעה שמבחי' הכלים ובחי' האור המתלבש בכלים כו', אבל בזה דוקא יש בחי' תוס' אור בהמשפיע ע\"י ההשפעה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם האו\"פ ענינו להאיר, והוא בבחי' ירידה מן העצמות (גם לגבי שרשי האורות) ובא בהתלבשות פנימי בכלים, וזה גופא שהוא בבחי' או\"פ הוא ע\"י התלבשותו בבחי' לבוש וכלים, דטבע האור לעלות, וטבע הכלי לירד, וע\"י שהאור בהתלבשות ותפיסא בכלים, ה\"ה בבחי' ירידה, וע\"כ ע\"י כלים דכתר הגם שהן עד\"מ אותיות החקיקה, ומ\"מ אינם כמו מעבר לעבר שזהו האותיות שלפני הצמצום, הנה ע\"י נמשך האו\"פ באצי', וי\"ל דא\"ק משום שאין שם כלים, ע\"כ יושר דא\"ק הגם שמסתיים בעשי' אינו בבחי' התלבשות, וכללות הקו הוא בבחי' או\"פ ע\"י ההתלבשות באותיות דרשימו, שע\"י הצמצום נעשו בבחי' מציאות, וע\"כ בהאו\"פ הו\"ע נתב\"ס, וכמו שע\"י השפעה מתוסף בהמשפיע, והו\"ע בעטרה שעטרה לו אמו ביום חתונתו, ונמצא דבאו\"מ זה נהנה וזה לא חסר, ובאו\"פ זה נהנה וזה חסר קצת, ויש בזה יתרון דנתב\"ס.</span>\n<b>רמח)</b> ומעתה צ\"ל מזה בספי' דתהו דלדעת הת\"ק מש\"א כופין על מדת סדום הוא בזה נהנה וזה לא חסר כלל היינו בבחי' האורות דתהו שלא הי' מהם ההשפעה, דהגם דהאורות דתהו הי' בחי' אורות מקיפים וא\"כ ההשפעה מהם הוא בבחי' לא חסר כו', ומ\"מ לא הי' ההשפעה מספי' אחת אל הספי' האחרת כו', ולדעת הי\"א דגם זה נהנה וזה חסר קצת הוא מדת סדום ה\"ז בבחי' ההשפעה שמצד הכלים שבאה בבחי' התלבשות שזה לא הי' במדות דתהו כו', ולפי\"ז י\"ל דבספי' דתהו לא הי' ההשפעה שמצד הבטול אבל ההשפעה שמבחי' הרוממות והגדולה הי' בבחי' התהו ג\"כ כו', וגם לדעת הת\"ק דוחק לאמר שלא הי' השפעה מבחי' האורות דתהו שה\"ה בחי' אורות והיו מ\"מ בבחי' המשכה שהרי האירו בהכלים שלהם רק שלא היו בבחי' התלבשות בהכלים כ\"א בבחי' מקיף כו', והרי מצד היותם בבחי' או\"מ הרי הי' צ\"ל ההשפעה לכל המדרי' בשוה, וכמשנת\"ל בענין אופן ההשפעה דהאו\"מ כו', וג\"ז א\"א לומר שהי' מן האורות השפעה בכל המדרי', א\"כ מהו\"ע שהיו זה תחת זה בבחי' פירוד כו', ומהו סיבת השבירה מאחר שהי' השפעה מזה\nלזה כו' ועם היות שהי' ההשפעה רק בבחי' מקיף הרי מצינו גם בבחי' התקון שמקיפים זל\"ז וכמו עיגולי עתיק ועגולי אריך כו'. וצריכים לומר דזה שבספי' דתהו לא הי' השפעה (שז\"ע מדת סדום) זהו בבחי' הכלים דבזה לא הי' השפעה כלל כו', דלהיות דההשפעה שמבחי' הכלים הוא בבחי' ביטול כנ\"ל וזה לא הי' בספי' דתהו דאדרבא היו בבחי' ישות כו', ומצד השלימות שהיו בעצמן דמשו\"ז לא רצו לקבל כמו\"כ משו\"ז לא רצו להשפיע כו' כנ\"ל פרל\"ז, אבל מצד האורות שההשפעה היא בבחי' הרוממות זה הי' בספי' דתהו ג\"כ רק שלא הי' בבחי' זה נהנה כ\"א אדרבה דמשו\"ז לא נתנו מקום להספי' האחרת כו'. והענין הוא דהנה נת\"ל פרל\"ג דבהתפשטות"],[3601330689,"הרוממות והתנשאות יש בזה ב' מדרי', הא' שבא מבחי' רוממות עצמי כו', דרוממות זו נותנת מקום לכל דבר ועם היות שנותן מקום לכל דבר הדבר מצ\"ע אינו בבחי' מקום כו' כמשנת\"ל פרל\"ז, וע\"כ ההשפעה מזה הוא בבחי' זה נהנה וזה לא חסר כו', דזה נהנה היינו מה שנותנים לו מקום, וזה לא חסר שאינו נתפס בזה מאחר שמצ\"ע אינו בבחי' מקום כו' (והאופן הזה לא הי' בספי' דתהו וזהו שרש דעת הת\"ק שזהו מדת סדום כו'), והב' דהתפשטות הרוממות אינו מבחי' רוממות עצמי רק בבחי' הגבהה והתנשאות לבד כו', דמשו\"ז אינו נותן מקום לשום דבר כו', ואם יתן מקום ה\"ז מגרע ומפחית אותו כו' כמשנת\"ל פרל\"ו, וא\"כ בהשפעה זו אם יתן מקום הרי אין זה בבחי' לא חסר, אדרבא הוא חסר שמגרע ומפחית כו', וע\"כ השפעה זו הוא בבחי' זה לא נהנה דהיינו שמבטל הכל כו', ונת' שם דז\"ע הרוממות דספי' דתהו כו', וע\"כ בההשפעה מבחי' זו הוא העדר נתינת מקום לגמרי אל הספי' האחרת כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ומעתה צ\"ל בענין ספי' דתהו, דהנה הת\"ק מדבר בבחי' אורות דתהו, והי\"א בבחי' הכלים, דמבחי' האורות שההשפעה מצד הרוממות, הי' גם בתהו, והנה בהתפשטות רוממות עצמי שנותן מקום, ובעצם אינו בבחי' מקום, הרי זה זה נהנה בנתינת מקום, וזה לא חסר שאינו נתפס, ובתהו שהי' הרוממות רק בבחי' התנשאות הרי בהנתינת מקום זה חסר שמגרע מהותו, ע\"כ הי' ההשפעה בבחי' זה לא נהנה שמבטל הספי' האחרת, ומבחי' הכלים שההשפעה מצד הביטול, לא הי' בתהו השפעה כלל.</span>\n<b>רמט)</b> וביאור הענין הוא דהנה נת\"ל בקצרה בענין רוח האדם העולה כו' וית' לקמן באורך, דשם מ\"ה הוא בבחי' עלי' למע' ושם ב\"ן הוא בבחי' ירידה כו', והנה ידוע דמ\"ה וב\"ן הו\"ע תהו ותקון דספי' דתהו היו בבחי' שם ב\"ן שז\"ע שהיו בבחי' מלוכה דבחי' מל' הוא שם ב\"ן כנודע (והרי ידוע דתהו הוא בחי' שם ס\"ג, היינו בחי' ב\"ן דס\"ג שז\"ע אור העינים שהן ה' אחרונה בחי' ב\"ן דס\"ג וכמ\"ש בע\"ח ובשה\"ק עולם הנקודים ד\"ג), וספי' דתקון הן ספי' דמ\"ה כו', והלא בתהו ותקון הוא להיפך דספי' דתהו לא הי' בהם הירידה והמשכה וספי' דתקון הן בבחי' ירידה והמשכה כו', וגם הכלים כל ענינם הוא בחי' הירידה כו' ונת\"ל פרל\"ט דכוונה העליונה להיות בחי' המשכת וגילוי האור כו' נעוץ בבחי' הכלים דוקא, ששרשן מבחי' העצמות למע' מהאורות כו', ובודאי גם כלים דתהו שרשן מבחי' העצמות והי' בהם נעיצת הכוונה העליונה, ולמה לא הי' בהם בחי' הירידה להשפיע כו'. אך י\"ל דהנה טבע העלי' והירידה עיקר סיבת הדבר הוא בחי' האין והיש דכל שהוא בחי' אין טבעו לעלות וכל שבבחי'\nיש טבעו לירד כו', וכמו בהד' יסודות טבע האש לעלות מפני שהוא יסוד דק ורוחני כו', והמים שאינם בבחי' הדקות ה\"ה יורדים מגבוה לנמוך והעפר יורד למטה כו', וזהו מה שהאור טבעו לעלות למע' להיותו בחי' אין כו' (הגם דאמיתת האין הוא בחי' האו\"מ להיותו רק בבחי' גילוי מן העצם כו' כנ\"ל פרמ\"ג, מ\"מ הרי כללות בחי' האור גם האור פנימי הוא בבחי' אין כו', וכמ\"ש בלק\"ת ד\"ה כדכד הב' וכמבו' בכ\"ד וכמשנת\"ל פקכ\"ז שהאו\"פ הוא ג\"כ גילוי מן העצם ודבוק במקורו דמשו\"ז הוא בבחי' אור ובבחי' אין כו', רק שזהו"],[3601330690,"מה שמן העצמות נמצא אור לא כמו העצם כ\"א בבחי' מדה וגבול כו'), והכלי טבעה לירד להיותה בבחי' יש כו' (ובודאי ענין הירידה הוא מפני הכוונה העצמית אבל הפועל בהכלי מה שהיא בבחי' ירידה זהו מצד בחי' הישות שבה כו', ולכוונה זו נמצאה מן העצמות בבחי' יש בכדי שיהי' בה טבע הירידה כו'). ובב' המדרי' דאור וכלי בחי' ההשפעה שבהם הוא ע\"י הבטול כו', דהרי הכלי היא בבחי' ירידה והמשכה שהו\"ע ההשפעה וגם האור ה\"ה מ\"מ בבחי' המשכה כו', ה\"ז בשניהם מצד הבטול כו', דהרי בהאור הוא ודאי כן שהרי הירידה וההשפעה הוא היפך טבעו כו' ונת\"ל פרמ\"ז דזהו שהכלי פועל בהאור שנעשה כמהותה כו', מ\"מ להיות תחלת המשכת האור והתלבשותו בהכלי הוא מצד הבטול אל אמיתת הכוונה העליונה כו' (וגם מה שנמשך ע\"י הכלי הוא לפי שמאיר בו מהכוונה העליונה ע\"י הכלי כו' שעי\"ז נתפס בהכלי ונעשה כמהותה כו'), והיינו שנעשה בהאור בחי' בטול יותר מכמו שהוא בחי' אין בעצם שזהו מפני שנמשך מן העצמות בבחי' דבקות בהעצמות כו', והירידה וההשפעה שבו הוא מצד הבטול לבחי' פנימי' העצמות\nשלמע' מבחי' מקור הגילוי כו' דעי\"ז הוא הנחת עצמותו שלא להיות בבחי' עלי' כ\"א בבחי' ירידה והמשכה כו'. אמנם גם בבחי' הכלי ענין ההשפעה הוא ג\"כ מצד הביטול כו', דהגם שיש בה טבע הירידה כו' מ\"מ הרי מצד בחי' הישות יכול להיות שיקבל האור רק לעצמה ולא להשפיע כו' דגם הקבלה לעצמה הוא ירידה והמשכה כו', וע\"כ צ\"ל בזה ביטול היש לירד ולהשפיע כו'. ונמצא דענין הירידה וההשפעה בהאור והכלי הוא ע\"י הבטול אל הכוונה המושרשת בעצמות כו' (רק שבהאור הוא בבחי' ביטול אמיתי להיותו בבחי' אור בעצם דהיינו בבחי' אין ממילא הביטול שבו הוא גדול יותר כו', וע\"ד איהו וחיוהי חד ואיהו וגרמוהי חד שהביטול שבהאור הוא בבחי' יחוד ממש כו' וגם להיותו בחי' אור דהיינו בבחי' דביקות במקורו נרגש בו יותר הכוונה העליונה כו', וביטול הכלי הוא בבחי' ביטול היש להיותה רק בבחי' כלי שהוא בחי' יש כו', ודמשו\"ז אינו נרגש בה כ\"כ הכוונה העליונה בבחי' גילוי כו' דגם נעיצת התחלה שבהכלי ה\"ז בה בבחי' כח נעלם ומאיר בגילוי בהאור דוקא להיותו בבחי' גילוי כו' וכמ\"ש\nבמ\"א, ומ\"מ י\"ל דביטול האור הוא רק מהארת שם מ\"ה החדש וביטול הכלי הוא מעצמות שם מ\"ה כו' וכמשי\"ת, ולכן ביטול הכלי הוא באמת ביטול יותר בעצם המהות כו' וכמ\"ש במ\"א). וכ\"ז הוא בספי' דתקון דבכללות הן בחי' מ\"ה דהיינו בחי' הביטול כו', רק שהכלים הן בחי' ב\"ן דמ\"ה וע\"כ הן בבחי' טבע הירידה והביטול שלהם הוא בבחי' ביטול היש (שזהו הביטול דב\"ן כנודע) כו' כנ\"ל, והאור שהוא בחי' מ\"ה בחי' אין דמשו\"ז הוא בבחי' טבע העלי' והן בבחי' ביטול אמיתי (שזהו הביטול דמ\"ה) כו'. משא\"כ בחי' התהו דבכללות הוא בחי' שם ב\"ן דהיינו בחי' יש כו', וביותר שהן בחי' ב\"ן דס\"ג אותיות גס שזהו בחי' יש כו', וע\"כ עם היות שבהכלים דתהו הי' ג\"כ בהעלם הכוונה העליונה להיות בחי' הירידה וההמשכה כו', ולכן גם הכלים דתהו הרי ג\"כ המשיכו מ\"מ את האור דתהו להאיר את הכלים כו', הנה לא השלימו את הכוונה להיות בהם וע\"י ההשפעה והגילוי כ\"א לקבל לעצמן וזהו מה שהיו בבחי' יש שצריך רק לעצמו ולא להשפיע אל הזולת כו' (היפך בחי' חסד דמ\"ה שנת\"ל פר\"מ, וגם לקבל לעצמן לא הי'\nבהם בחי' הביטול להיות כלים אל האור לקבל את האור בבחי' פנימי' ממש כו'), וכמו\"כ היו בבחי' השלימות בעצמן שלא לקבל מהספי' האחרת ולא להשפיע כו' (דהעדר"],[3601330691,"ההשפעה מבחי' הכלים הוא מצד ב' ענינים הא' שצריך רק לעצמו, והב' מצד השלימות היינו שלא הי' בהם הביטול אל הכוונה העליונה כו'), וכמו\"כ האורות דתהו הי' ג\"כ בבחי' יש, והיינו דעם היות שהיו בבחי' המשכה (ע\"י בחי' הכלים דתהו שהמשיכו את האור וי\"ל שזהו ג\"כ להיותן בחי' ב\"ן בכלל שהו\"ע הירידה כו'), לא הי' בהם בחי' הבטול אל הכוונה העליונה להיות ההשפעה בבחי' ירידה וצמצום שיהיו בבחי' אור פנימי כו' כ\"א הי' ההשפעה בבחי' רוממות וגדולה (בבחי' התנשאות חיצוני כו'), והיינו שהכלים פעלו בהאור להיות בבחי' המשכה אבל ההמשכה לא היתה כפי הכוונה העליונה כ\"א הי' בבחי' תוקף האור ביותר, שגם בהכלי של האור לא הי' בבחי' התלבשות ובכללות לא הי' נותן מקום לספי' אחרת כלל כו', ולא כמו בבחי' התקון שגם בחי' האו\"מ הוא באופן שמתקבל בבחי' מקיף עכ\"פ וגם נותן כח בהפנימי כו', והיינו מפני שזהו התפשטות הרוממות הבאה מבחי' רוממות עצמי כו', ע\"כ אדרבא נותן מקום לכל דבר ומוסיף בו אור וחיות כו' שגם המקבל נעשה עי\"ז בבחי' הגבהה ורוממות כו', וכמו\nמרום וקדוש אשכון כו' להחיות רוח שפלים כו' להגביהו משפלותו כו', שזהו יתרון בהשפעה מבחי' הרוממות לגבי השפעה בבחי' או\"פ שרק מאיר את המקבל והאו\"מ מגביה אותו כו', וי\"ל הדוגמא לזה כמו הנותן צדקה והמפייסו שזהו מהכח נפשי דמדת החסד כו', דגדול שכר הפיוס מפני שעושה הרמת רוח בהמקבל כו' וכמ\"ש במ\"א, ובהאור דתהו שההשפעה היא בבחי' התנשאות הנה ההשפעה היא בבחי' תוקף ביותר שאינו מוסיף שום אור וחיות ועוד זאת שאינו נותן מקום לשום דבר כו', ונמצא דמבחי' הכלים דתהו לא הי' השפעה כלל להיות דההשפעה מבחי' הכלים הוא בבחי' זה חסר קצת בבחי' ביטול וזה לא הי' כלל בספי' דתהו כו', ובהאורות הי' בחי' השפעה אבל אדרבא בזה לא נתנו מקום להספי' האחרת כו'. ולפי\"ז יובן דב' הענינים שנת\"ל בבחי' התהו הא' שלא היו נותנים מקום זל\"ז והב' שלא היו מקבלים ומשפיעים זל\"ז, הנה מה שלא נתנו מקום זל\"ז הוא מצד האורות דתהו ומה שלא היו מקבלים זמ\"ז ולא משפיעים זל\"ז הוא מצד הכלים דתהו כו', ובתיקון נתתקנו ב' הענינים הנ\"ל והוא ג\"כ בבחי' האורות וכלים דתיקון שנתקנו ע\"י בחי' שם מ\"ה החדש כו' וכמשי\"ת.\n<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע דהנה מ\"ה וב\"ן בחי' עלי' וירידה, והלא הספי' דתהו בחי' ב\"ן למה לא הי' בהם ענין ההשפעה, ובודאי גם בכלים דתהו הי' נעיצת הכוונה בבחי' הירידה, הענין הוא דעם היות הירידה היא מצד הישות, הנה ההשפעה היא מצד הביטול, דבהאור ה\"ז היפך טבעו, וגם בהכלים עם היות בהן טבע הירידה, יכול להיות רק הקבלה לעצמה, וההשפעה היא מצד הביטול, ובהאור הוא ביטול אמיתי, ובכלים ביטול היש, ותהו בחי' ב\"ן דס\"ג, הנה בהכלים אם שהי' בהם טבע הירידה הוא רק לקבל לעצמה ולא להשפיע כלל, ובהאורות הי' השפעה אבל בבחי' יש שלא ליתן מקום (ובתקון האו\"מ נותן מקום שמוסיף אור וחיות ומגבי' את המקבל).</span>\n<b>רנ)</b> ועפ\"י הנ\"ל יובן מ\"ש נשא את ראש כו', דהנה אמרז\"ל אין עומדין להתפלל אלא מתוך כובד ראש, ופירש\"י הכנעה ושפלות, דהנה ידוע דענין התפלה הוא להיות התגלות הכחות דנה\"א, דקודם התפלה הנשמה היא בהעלם"],[3601330692,"וכמ\"ש חדלו לכם מן האדם אשר נשמה באפו דקודם התפלה הנשמה היא רק באפו דהיינו בתכלית הקטנות וההעלם, וע\"י התפלה נעשה התפשטות והגדלת הנשמה וכמ\"ש סולם מוצב ארצה וראשו מגיע השמימה שזהו סולם דתפלה שיש בו ד' שליבות עד פסוד\"ז ופסוד\"ז וברכת ק\"ש וק\"ש, שהן נגד ד' מדרי' שבנשמה, וכמא' נשמה שנתת בי טהורה היא אתה בראת כו', דעד פסוד\"ז הו\"ע ההודאה שזהו בחי' נפש כו', ופסוד\"ז הוא התגלות בחי' הרוח התפעלות המדות כו', וברכת ק\"ש וק\"ש התגלות הנשמה והיא ההשגה וההתבוננות באלקות כו', ובשמו\"ע מגיע לשרש ומקור הנשמה והוא להיות התחברות הנשמה המלובשת בגוף עם שרש ומקור הנשמה שזה עושה הגבהה ורוממות בהנשמה המלובשת בגוף, דהנה הנשמה המלובשת בגוף להיותה בבחי' התלבשות ותפיסא בהנה\"ב הגם שיש בזה מעלה שזהו בבחי' או\"פ שבא בבחי' גילוי ועושה תקון וזיכוך בנה\"ב כו', מ\"מ יכול להיות בזה התעלמות יתירה מצד הנה\"ב וכמו בהעדר עבודה הרי הנה\"ב מעלים ומסתיר מאד על הכחות דנה\"א כו', וכן בתחלת העבודה הרי הכחות דנה\"א מתעלמים בהנה\"ב ואינם בהתגלות כו'\n(וכמו בכ\"י קודם התפלה שנשמה באפו כו'), וכן גם מי שעובד עבודתו בתפלה בהתגלות הכחות דנה\"א ובהתגברות על הנה\"ב כו' הרי מ\"מ אחר התפלה כשהולך בעניני העולם יש התגברות מהנה\"ב כו', וזהו מפני שהנה\"א הוא בבחי' התלבשות ותפיסא שבא בבחי' ירידה וצמצום ובבחי' התלבשות ממש כו' ע\"כ יש התגברות מהמלביש כו', אך כשמאיר שרש ומקור הנשמה בנשמה המלובשת בגוף ה\"ז פועל הגבהה בהנשמה דאינה מתעלמת גם אחר התפלה ואדרבא היא מאירה בגלוי דגם כשהוא בעניני העולם ה\"ה באופן אחר לגמרי וכמו בכל דרכיך דעהו כו', וזהו שהתפלה הוא תשו\"ע דהיינו התגלות שרש ומקור הנשמה כו', אמנם בכדי להיות התגלות שרש הנשמה בתפלה ע\"ז צ\"ל מקודם בחי' תשו\"ת, וזהו אין עומדין להתפלל אלא מתוך כובד ראש, דהנה כתי' כי עונותי עברו ראשי כמשא כבד כו' פי' עונותי עברו ראשי הוא כמו כ\"א עונותיכם היו מבדילים ביניכם ובין אלקיכם שנעשה מסך מבדיל כו', אלקיכם הוא בחי' שרש ומקור הנשמה שזהו בחי' האלקות שבנשמה דהרי שכל ומדות יש בכולם ועיקר האלקות שבנש\"י הוא בחי' הרצון פשוט כו'\nוכמ\"ש במ\"א והעוון נעשה מסך מבדיל כו', נחלה עבר על נפשנו כו', ועי\"ז הנשמה המלובשת בגוף יורדת ומתעלמת ביותר כו', וזהו כמשא כבד כו', וכמ\"ש כבד לב פרעה וארז\"ל במד\"ר שנעשה לבו ככבד, דהרי חצר הכבד מפסיק בין אברי הנשימה לאברי המזון דאברי הנשימה המה בתכלית הדקות ואברי המזון בתכלית הגסות כו', ולמע' הו\"ע יהי רקיע ויהי מבדיל כו', דמים מצמיחים כל מיני תענוג ומ\"ע הם מצמיחים תענוגים רוחנים וכמו ונהר יוצא מעדן כו', ומ\"ת מצמיחים תענוגים גשמיים כו', ובנפש הוא ההבדלה בכלל בין הנה\"א והנה\"ב כו', ובנשמה גופא הוא ההבדלה בין בחי' נפש לרוח ונשמה, דנפש הוא מדרי' תחתונה ששייך בזה העלם ורוח ונשמה שהן מוח ולב ה\"ה בבחי' גילוי אור כו', אבל כבד לב הוא שהלב נעשה ככבד והו\"ע טמטום הלב וטמטום המוח שאינו נרגש בו אור אלקי גם במוח וכ\"ש בלב כו', וע\"ז צ\"ל כובד ראש דקדושה הכנעה ושפלות והו\"ע המרירות שיתמרמר בנפשו על ריבוי ההעלמות וההסתרים ועל עוצם ריחוקו כו' ויהי' לב נשבר כו' וגם יעורר ר\"ר על נפשו (שזהו ג\"כ בכלל המרירות כו'), ועי\"ז נעשה הגבהת הנפש וכמ\"ש ואשא אתכם על כנפי נשרים ואביא אתכם אלי שע\"י"],[3601330693,"כנפי נשרים בחי' הרחמים עי\"ז ואביא אתכם אלי לעצמותי כו', ברית כרותה ליגמדה\"ר שאינן חוזרות ריקם כו', וזהו ג\"כ ענין הצדקה קודם התפלה וכמ\"ש אני בצדק אחזה פניך כו', ועי\"ז נעשה ג\"כ הגבהת הנפש וכמ\"ש וצדקה תרומם גוי כו'. וזהו\"ע נשיאת ראש לחבר עם שרש הנשמה כו', דעם היות שהראש היא מדרי' גבוה מ\"מ להיות שזהו בבחי' התלבשות יכול להיות בזה התעלמות וע\"כ צריכים לנשאות הראש לחבר עם שרש ומקור הנשמה כו', וזהו שאו את ראש וכן נשא את ראש בני גרשון שזה\"ע נשיאת ראש כנ\"ל. והקדים הכתוב בני קהת לנשיאת ראש לפי שהם מטועני הארון, דהנה התורה היא כלי כללית לגילוי בחי' עצמות אוא\"ס דאורייתא מחכ' נפקת וידוע שהחכ' היא כלי לגילוי האו\"מ כו' וכמ\"ש במ\"א, וע\"כ ה\"ז קדום לנשיאת ראש כו', וידוע שהתורה נותנת ג\"כ כח בעבודה דתפלה שז\"ע למוד התורה שקודם התפלה כו' דהתורה היא עוז ותושי' עוז לנה\"א להוציא ממסגר אסיר להיות התגלות הכחות דנה\"א כו' וגם היא תושי' להתיש כחות הנה\"ב כו', וזהו שהתורה מסייעה בעבודה דתפלה כו' וכמארז\"ל מעיקרא כי עביד\nאינש כו', אך כ\"ז הוא במדרי' גבוה יותר מענין כובד ראש דהעבודה דתפלה שע\"י הקדמת התורה ה\"ז במדרי' גבוה יותר כו', וגם זה שייך במי שכבר עומד באיזה דרגא והיינו שאין הנה\"א בהתעלמות כ\"כ כו', ולכן בתחלת עבודה בהכרח שיהי' תחלה תשו\"ת בחי' לב נשבר ונדכה כו', וא\"א להתחיל תחלה העבודה ע\"י התורה (רק השקידה יתירה בתורה והעיקר מסירת נפשו די איבערגיגעבינקייט אין תורה שזה מועיל, וביותר בפנימי' התורה כו') וצ\"ל תשו\"ת, וכאשר הוא באיזה דרגא אז יכול להיות ע\"י הקדמת התורה כו'. וזהו שהקדים הכתוב את בני קהת לנשיאת ראש משום כבוד ומעלת התורה כו' ומ\"מ שניהם שוים דלגבי המקיף באמת כולם שוים כו', וזהו נשא את ראש וכן שאו את ראש שצריכים לנשאות את הראש והיינו ע\"י הכובד ראש דקדושה וע\"י התורה, שעי\"ז נעשה נשיאת ראש דהיינו התחברות שרש ומקור הנשמה עם הנשמה המלובשת בגוף כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וז\"ש נשא את ראש, דהנה הנשמה שבגוף יש בה מעלת או\"פ, אך יכול להיות התעלמות מהנה\"ב, והיציאה היא ע\"י תפלה, ומאיר או\"מ דנשמה שמגבי' את הנשמה שבגוף, וזהו תשו\"ע וצ\"ל תחלה תשו\"ת כובד ראש, כי עוונותיכם מבדילים ביניכם ובין אלקות שבנשמה, שלבו נעשה ככבד, וצ\"ל מרירות והתעוררות ר\"ר, ועי\"ז נעשה הגבהת הנפש. וזהו נשא את ראש, והקדים בני קהת היינו תורה שקודם התפלה, ולגבי המקיף שניהם שוין.</span>"],[3601330694,"<h3>בס\"ד. ש\"פ בהעלותך, תרד\"ע</h3>\n<b>בהעלותך</b> את הנרות אל מול פני המנורה כו', וזה מעשה המנורה כו' עד ירכה עד פרחה כו', וצ\"ל מה\"ע העלאת הנרות הלא הנרות הן בבחי' העלאה, וכמו הנשמה שקרוי' נר וכמ\"ש נר ה' נשמת אדם שזהו עד\"מ שהלהב עולה תמיד למעלה ונאחז ע\"י הפתילה ועי\"ז הוא ברצו\"ש תמיד כו', וכמו\"כ הנשמה היא בבחי' רצו\"ש שיש בה ההעלאה לעלות ולהכלל באוא\"ס וכמ\"ש רשפי' רשפי אש שלהבת י\"ה כו' ויורדת למטה להחיות לקיים רצון בוראה כו', ובפנימיות הענין הוא שהיא בבחי' ירידה לקיים תומ\"צ שזהו תכלית הכוונה וכמ\"ש לא לתהו בראה אלא לשבת יצרה כו', הרי שהנר הוא בבחי' העלאה וא\"כ מה צריכים להעלות את הנרות כו'. גם צ\"ל מ\"ש כאן וזה מעשה המנורה, הלא במעשה המנורה כבר נאמרה פ' שלימה בפ' תרומה ולמה נאמרה כאן, והמשמעות הוא שזה שייך אל ההעלאה ובשביל זה נשנית כאן, וצ\"ל מה שייך מעשה המנורה להעלאת הנרות כו'. והנה רש\"י כ' בשם מדרש אגדה למה נסמכה פ' הנרות לפ' הנשיאים לפי שכשראה אהרן חנוכת הנשיאים חלשה דעתו שלא הי' הוא ושבטו עמהם א\"ל הקב\"ה חייך שלך גדולה\nמשלהם שאתה מדליק ומיטיב את הנרות, דגם צ\"ל הלא הקרבנות הוא ענין גבוה ונעלה מאד מפני מה העלאת הנרות גדולה משלהם כו'. ולהבין כ\"ז ילה\"ק משנת\"ל במש\"א במשנה דאבות האומר שלי שלי ושלך שלך זו מדה בינונית וי\"א זו מדת סדום דלדעת הת\"ק מדת סדום הוא מניעת השפע מה שזה נהנה וזה לא חסר כלל אבל כשזה חסר קצת אין זה מדת סדום, ולדעת הי\"א גם כשחסר קצת ה\"ז מדת סדום, ונת' הענין למעלה דמה שזה חסר קצת ה\"ז בבחי' השפעה שמבחי' הכלים היינו בהאור המתלבש בכלים שזהו ע\"י ירידת וצמצום המשפיע להשפיע בבחי' התלבשות כו', והשפעה זו לא הי' כלל בתהו להיות דהשפעה היא בבחי' ביטול לירד ולצמצם כו' והיא מצד הכוונה העליונה דנעיצת התחלה שבהמקבל כו', וכלים דתהו שהיו בבחי' יש והיו בבחי' שלימות בעצמן לא רצו לירד ולצמצם כו' (כ\"א לקבל לעצמן כו') ולא מצאו גרעון בעצמן וגם לא יתרון בהמקבל כו', וע\"כ לא רצו להשפיע ולקבל כו', וההשפעה בבחי' לא חסר כלל היא מצד האור שלמע' מהכלי שההשפעה לא בבחי' התלבשות וע\"כ לא חסר כלל מפני שאינו יורד מעצמותו ואינו\nמצמצם עצמו כו', והשפעה זו הי' ג\"כ בתהו אך לא הי' בבחי' נהנה כ\"א אדרבא שלא נתן מקום להספי' האחרת כו' והיא ג\"כ בחי' הישות והמציאות דאנא אמלוך ולא אחר כו', ונמצא דמה שהספי' לא נתנו מקום זל\"ז הוא מצד האורות כו' ומה שלא הי' משפיעים ומקבלים זמ\"ז הוא מצד הכלים כו'.\n<b>רנא)</b> ומעתה צ\"ל ענין התיקון דלפי הנ\"ל מובן דהתיקון הי' צ\"ל בב' ענינים הא' שהספי' יהיו נותנים מקום זה לזה והו\"ע הסבלנות לבד שיהי' סובלים זא\"ז כו', והב' הוא שיהיו מקבלים זמ\"ז ומשפיעים זל\"ז וזהו בחי' התכללות והתאחדות אמיתי דמבלי אשר ימצא ראש וסוף כו' וכמשי\"ת. והנה הענין הא' שיהי' סובלים זא\"ז הוא בבחי' האור כו', דהיינו שהאור יהי' באופן כזה שיתנו מקום זל\"ז כו', דהרי נת\"ל פרמ\"ח דזה שבספי' דתהו לא הי' החסד נותן מקום לספי' הגבו' כו' הוא מצד האור שהי' בבחי' תוקף האור דאנא אמלוך לבד כו',"],[3601330695,"ובתיקון הוא שבא האור בבחי' מיעוט וחלישות שנותן מקום להספי' האחרת כו', שעז\"א לעולם יהא אדם רך כקנה ואל יהא קשה כארז דארז הוא עץ קשה ביותר שאינו יכולים להטותו לשום צד, וכמו\"כ איש הקשה במדותיו שאינם יכולים להטותו כו', דהנה ידוע דהמדות יש בהם תוקף גדול יותר מבשכל כו', שהרי השכל משתנה לפעמים כך ולפעמים כך, דעם היות ששכלו הי' מחייב באופן כזה מ\"מ יכול להיות שישכיל איזה שכל וסברא אחרת שמחייבת באופן אחר, וסיבת הדבר הוא להיות כי השכל בא בהתחלקות פרטים דוקא, כי א\"א להיות שכל פשוט בלי התחלקות פרטים (לבד מושכלות הראשונות שהן בהנחה מוחלטת בשכל וכמו שהחלק פחות מהכל ושהמרובע הוא בעל זויות וכה\"ג, וגם בזה יש ענינים שכשיבואו לידי השגה בהכרח שיהי' בהם ענינים פרטים כו'), דכל ענין שכלי בא בריבוי פרטים, וזה כל ענין השכל לפרט כל דבר שעי\"ז דוקא הוא תופס ומשיג את המושכל כו', וכידוע דבינה הוא יסוד אש שטבע האש לפרר ולחלק לפרטים שעי\"ז תופס ומשיג את המושכל, וידוע דכל תפיסת דבר הוא ע\"י הקצוות, וזה ג\"כ ע\"י שמתחלק\nלפרטים שעי\"ז ניכרים הקצוות שהו\"ע ההגבלה כו', דהשכל כמו שהוא בכללות עדיין אין הקצוות ניכרים בו וה\"ה בלתי מוגבל עדיין כו', וכמ\"ש במ\"א בענין עיגולים ויושר דעיגולים הוא כמו שהשכל הוא בד\"כ ויושר הוא כמו שבא בהתחלקות פרטים כו', וזה כל ענין השכל לפרט כל דבר בריבוי ועי\"ז דוקא תופס ומשיג הענין כו', ותפיסא כללית אינו תפיסא מפני שאינו משיג את המושכל כו' (והיינו גם כאשר התפיסא כללית אינו רק ידיעה שטחיות כו' וכמו ביסודות והנחות כלליות שיש בעניני שכליים כשאינו משיג היטב חיוב הדבר לאמיתתו ה\"ז תפיסא כללית כו' והבנת הדבר בהכרח שיבוא בכמה פרטים כו'), ולהיות שבא בהתחלקות פרטים ה\"ז נותן מקום להשתנות מפני ההתחלקות עצמה שנחלק הענין לפרטים כו', וגם דכל דבר הבא בפרטים בהכרח שיהי' פרטים שונים כו', וה\"ז נותן מקום שיוכל לפעמים להשתנות באופן אחר מכמו שהשכיל מקודם כו', כי הפרטים שונים יכול להיות שנושאים את הענין באופן אחר ועי\"ז ישכיל בהענין באו\"א מהקודם כו', וגם יכולים להטותו מהשגתו דכאשר בעל שכל אחר יסביר לו הענין\nבאופן אחר יכול להיות שיקבל מאתו וישתנה גם השגתו והיינו לפי שהשגתו שבאה בריבוי פרטים נותן מקום לזה כו', וכמו חכמים שמודים זל\"ז אם בההשגה כולה או בפרטים ממנה כו'. וענין העקשות הוא למעלה מהשכל דע\"פ השכל אין מקום לעקשות כו', ונודע דעקשות יש בזה ג\"כ טעם וכמו שתוק כך עלה במח' והיינו טעם כמוס שלמעלה מהשגה, והיינו שהמתעקש יש לו טעם בזה (א גישמאק) רק שא\"א לו לגלות אל הזולת, וזהו מפני שלא בא בבחי' התחלקות פרטים משו\"ז א\"א לו לגלות וע\"כ אינו משתנה כו', ובמ\"א מבו' שגם העקשות יוכל להשתנות מפני שיש בזה עכ\"פ איזה טעם ושכל כו' (רק הדעת הוא בתוקף ואינו משתנה והוא לפי שהדעת הוא הכרת הענין שלמעלה מהשגה ולכן אינו משתנה ומתחלף כו', וכמ\"ש מזה בד\"ה תקעו אעת\"ר), וזהו שבשכל שייך נחומים וכמ\"ש כי לא אדם הוא להנחם דדוקא בלא אדם לא יש נחומים אבל בציור אדם שעיקרו הוא השכל שייך נחומים כו' וכמשנת\"ל פקצ\"ג. משא\"כ המדות הן בתוקף גדול בעצם שאינם משתנים בעצם מהותם כו', דהמדות הן הטבע שבאדם והוא התגלות ההשרשה פשוטה שבנפש, דטבע הוא מל' טבעו בי\"ס כו', ובנפש י\"ל שהו\"ע השרשה, והרי כל הכחות"],[3601330696,"הן מושרשים בנפש, י\"ל דזהו כחות לבד רק שמושרשים ונטועים בעצם הנפש, אבל ענין הטבע הוא השרשה פשוטה דעצם הנפש, דכל עצם הנפש הוא בהשרשה זו (עס נעמט ארום דעם גאנצין עצם) שהתגלות כל הכחות הוא לפי אופן השרשה זו כו', וענין השרשה זו הוא כאשר ידוע דכללות הנפש הוא לפי אופן שרשו ומקורו אם במדת החסד או במדת הגבו' כו', ומה שנק' זה השרשה הוא מפני שהנפש בעצם הוא למעלה מזה ואין לומר בה דשרשה הוא בבחי' החסד או בבחי' הגבו' כו', וזה ששרשה בחו\"ג הוא כעין ציור בנפש (ומובן שאין זה ציור ממש כו') והו\"ע השרשה לבד רק שהוא השרשה פשוטה כו', והמדות הן התגלות השרשה פשוטה הנ\"ל. והטבעיות לא תשתנה לעולם כו', דמי שהוא איש החסד לא ישתנה לעולם לאיש הגבו' כו', וכן מי שהוא בטבע הגבורות לא ישתנה בעצם מהותו להיות בטבע מדת החסד כו', וגם כמה שמייגע א\"ע לשנות טבע המדה שלו (וכמו גם במדת החסד יכול להיות שמייגע א\"ע להיות באופן אחר מפני שהשעה או המקום צריך לכך וכה\"ג, ומכ\"ש במדת הגבו' דשייך יגיעה לשנות המדה כו') לא תשתנה המדה בעצם כו',\nרק יכול להיות התעלמות איזה כח לפי שעה ולהתנהג בהמדה הפכית, וכמו אאע\"ה שכבש את רחמיו מעל בנו יחידו והתנהג במדת הגבו' כו' שזהו רק לפי שעה שיש בכח הנפש להעלים איזה כח לגמרי כו' וכמ\"ש במ\"א, וג\"ז הי' בדרך נסיון והיינו רק לקיים רצון ה' יכול להיות התגברות כזאת כו', ובמ\"א מבו' שגם בזה הי' מדת האהבה (דאברהם אוהבי כו') והיינו להיות בחי' הקירוב והדביקות באלקות עי\"ז כו', וא\"כ הרי בעיקרו ויסודו הוא בחי' החסד והאהבה כו', ומ\"ש עתה ידעתי כי ירא אלקי' אתה היינו היראה שלא יפרד ח\"ו וכמ\"ש במ\"א, הרי שעצם הטבע אינו משתנה כו'. וכן במדת הגבו' יכול להיות שאיש הכילי יהי' כמו איש הטוב בעצם בעת השמחה כמו בשמחת בנו יחידו כו', ה\"ז ג\"כ רק לפי שעה וגם שאז הטוב הוא בתגבורת גדולה כו' והיינו שעצם טבע המדות אינו משתנה כו', ואפי' ע\"י עבודה בכח הנה\"א לשנות מדות הטבעיים דנה\"ב וע\"ז הוא ירידת הנשמה בגוף וזאת היא כל עבודת האדם כל ימי חייו לשנות הטבע דנה\"ב כו', הנה גם כאשר פועל בעבודתו לשנות ולהפך את הטבע מ\"מ עצם הטבע נשארת כמו\nשהי' כו', רק שקודם היתה המדה ברע וע\"י העבודה תהי' הטבע הזאת בטוב וכמו הכעס על ההיפך ורשפי אש בהתפעלות יתירה כו' (ובאמת הכעס על ההיפך אין זה עדיין תכלית הטוב כי מדת הכעס א\"צ להיות גם הכעס על הרע רק מה שצר לו מזה שנמצא הרע כו' וכמ\"ש במ\"א, הנה זה שצר לו (דער ניט גוט) ה\"ז ג\"כ מדת הגבו', וגם דמי שהוא במדת הגבו' הצער מההיפך הוא בתוקף ביותר כו'), וגם ע\"י התשובה שמשנה המהות מ\"מ נשאר עצם הטבע רק שבא בציור אחר, וכמו מי שהוא בטבע הגבו' הוא יותר בטבע מרירות ומרה שחורה, וטבע מדת החסד הוא בשמחה ומרה לבנה כו', וכן המדות דנה\"א בבחי' חו\"ג כמ\"ש באגה\"ק סי' ט\"ו דמדת החסד הוא שמאהבת ה' ומרוב חפצו לדבקה בו הוא חפץ חסד כדי לדבוק במדותיו כו', ומדת הגבו' הוא להפרע מן הרשעים ולענשם בעונשי התורה וכן להתגבר על יצרו ולקדש א\"ע במותר לו ולעשות גדר וסיג לתורה כו'. הרי טבע המדות האלו אינם משתנים לעולם כו', הרי שהמדות יש בהם תוקף יותר מהמוחין כו', וזהו לפי שהמדות מושרשים בעצם הנפש למעלה מן המוחין כו', כי המדות הן עצמיות הנפש שבא בהתגלות כו', דהגם שהמדות באים בבחי' כחות היינו בבחי' מציאות דבר ובבחי' תוקף המציאות"],[3601330697,"כו' וגם בכחות מחולקים דמדת החסד ומדת הגבו' כו', מ\"מ בעצם הן העצמיות של הנפש שבא בבחי' ציור כזה כו', והיינו שבעצם זהו ההשרשה הפשוטה שבנפש רק שבא בחי' ציור דחסד או גבו' כו' ובאיזה ציור שבא ה\"ז בבחי' פשיטות העצמית כו', וזהו סיבת התוקף שלהם מפני שהם פשיטות העצמות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולפי הנ\"ל יובן שהתיקון הי' בב' ענינים, הא' שהספירות יתנו מקום ויסבלו זא\"ז, וזה בתיקון האור שיהי' בבחי' מיעוט וחלישות, דהנה עיקר התוקף הוא במדות, כי השכל יכול להשתנות מפני שכל ענינו לחלק ולפרט כל ענין שעי\"ז דוקא הוא תפיסת הענין והשגת הענין, וההתחלקות היא חלישות האור, וגם משום הענינים שונים שבו, ויכולים להטותו לסברה אחרת, ועקשות להיות שזהו מטעם כמוס כללי אינו משתנה, ומ\"מ ג\"ז משתנה לפעמים, אבל המדות הן טבע הנפש והוא התגלות השרשה פשוטה שבנפש, שלמעלה גם מהכחות עצמיים, ולפי ההשרשה שבנפש (שבעצמה למעלה גם מזה) אם בחסד או בגבו', הוא התגלות הכחות, וזהו אינו משתנה, רק מתעלם לעתים לפי שעה, וגם בעבודה שהנה\"א מהפך הטבעית דנה\"ב הנה עצם ההטבעה נשארת רק שהיא בקדושה, וכן בתשובה, והרי חו\"ג הן כחות הנפש, הנה זהו ציור העצם.</span>\n<b>רנב)</b> והענין הוא דהנה נת\"ל פמ\"ט ההפרש בין רצון לחכ' דחכ' הוא כח שחוץ לעצמות הנפש משא\"כ הרצון הוא התגלות העצמות כו', כן הוא במדות שבעצם מהותם הן הרצון רק שזהו כמו שבא בבחי' מציאות היינו בבחי' כח כו', דהרצון הוא בחי' אין דגם התגלות הרצון אינו בבחי' מציאות ולא בהתחלקות פרטים כו' ובמדות הוא שבא בבחי' מציאות דבר ובמדה פרטיות דחסד או גבו' כו', אבל המציאות הוא פשיטות העצמות שבא בפרט זה בבחי' מציאות דבר כו' (וכן ברצון כמו שבא בד\"פ ברצונות פרטים עד הרצון שבמעשה ה\"ה בתוקף כמו הרצון פשוט כו' וכמשנת\"ל פ' פ\"א, ומ\"מ בהרצון גם בהפרטים אינו בבחי' מציאות ובמדות הן בבחי' מציאות כו', ובאמת ההשרשה פשוטה ה\"ז למע' מן הרצון שהרי גם התגלות הרצון הוא לפי אופן ההשרשה שבנפש כו', והמדות הן ההשרשה הנ\"ל שבאה במציאות כח כו'), ואין זה כמו השכל שבד\"כ הוא בחי' צורה שמצייר את החומר, וזהו מה שהוא כח ולא עצם היינו שהוא בחי' צורה לבד כו', וזהו הסיבה שמשתנה ומתחלף כי הצורה יכולים לשנות ולעשות צורה אחרת כו', משא\"כ\nהמדות זהו החומר העצמי שבא בציור הזה כו', דבהיותם כחות ה\"ז ג\"כ ציור אבל זהו שהחומר מצטייר בציור הזה כו', וזהו הטעם דתוקף המדות יותר על השכל שאינן משתנים כו' מפני שהן עצמות הנפש כו', וכן הוא למעלה דאו\"א במזלא אתכלילו שהן מזלות ושערות הנמשכים ממו\"ס כו' (וג\"ז רק בבחי' יניקה ומה שמלבישים הוא רק זרועות דאריך כו' כנודע), וז\"א בעתיקא אחיד ותליא הרי ז\"א שהן בחי' מדותיו ית' הן למעלה בשרשם מחו\"ב כו', ולכן האבות הן המרכבה דהאבות שהן בחי' חג\"ת ה\"ה בבחי' מרכבה לאדה\"ע בחי' חו\"ב להעלותם בבחי' כי לא אדם הוא ולהמשיך מבחי' כי לא אדם תוס' אורות בבחי' ציור אדם כו', והיינו מצד שרשן הקדום למעלה מבחי' המוחין דחו\"ב כו' וכמ\"ש בתו\"א על מא' זה. וכמו\"כ בעבודה התגלות בחי' אהבה המוסתרת בעצם טבע הנשמה היא בחי' אה\"ר ורעו\"ד שזהו בבחי' תוקף הרצוא והצמאון ביותר שזה מגיע למעלה הרבה מבחי' המוחין כו',"],[3601330698,"והו\"ע ובכל מאדך האה' הבלתי מוגבלת שמגיע למעלה בבחי' עצמות אוא\"ס הבל\"ג כו', וכמא' דלית מח' תב\"כ דבעצמות אין שום מח' והשגה תופסת כלל, אבל נתפס איהו ברעו\"ד כו', וכידוע דעבודה דמוחין אפי' במדרי' גבוה הכל הוא בבחי' האור שבא במדה וגבול דבזה שייך ענין ההתבוננות וזה הוא שממשיכים ע\"י עבודה זו כו', משא\"כ אה' דבכל מאדך שמצד עצם טבע הנשמה ה\"ז מגיע בעצמות אוא\"ס ונמשך עי\"ז תוס' אורות בבחי' המוחין כו'. והנה אחכ\"ז אנו רואין דמ\"מ המוח שליט על הלב והנהגת המדות הן ע\"פ השכל כו', שהרי גם תולדות המדות הן מהשכל כי לא יתעורר אדם באיזה מדה כ\"א ע\"י השגת השכל דוקא, ועם היות דאין התהוות מהות המדה מן השכל מ\"מ הלידה והתגלות של המדות הוא מן השכל דדוקא כאשר מתבונן ומשיג בשכלו טוב הדבר יתעורר באהבה איליו כו', וממילא לפי אופן חיוב השכל לפי אופן כזה יהי' התפעלות האהבה כו', והיינו דלפי אופן הטעם המחייב את האהבה כך יהי' שיעור התפעלות האהבה כו'. דכן אנו רואין גם במדות שבין אדם לחבירו באה' או שנאה בחסד או דין דהכל תלוי בהטעם\nושכל שיש לו בזה, דלפי אופן כזה היא האהבה או השנאה אליו, וממילא שיעור ערך האהבה תלוי' בשיעור ערך הטעם המחייבה כמו בכמות ואיכות הטובות והחסדים שעשה עמו כו' וזהו בקטנות המדות כו', וכן לפ\"ע טובת האיש מצ\"ע בטוב המדות והמעשה או בטוב השכל שלו, וכמו רבו שלמדו חכ' ומדות טובות יש לו אהבה אליו דלפ\"ע הלמוד שלמדו לפ\"ע זה הוא האהבה, דאינו דומה האהבה לרבו שלמדו קריאת אותיות לרבו שלמדו מקרא ומשנה וגמ' ושכליים עמוקים כו', וכן לפ\"ע טוב שכלו בעצם לפ\"ע זה הוא האהבה כו', וכן להיפך במי שעשה לו רעה או ששנאוי בעיניו מצד מעשיו ומדותיו הרעים או קוטן דעתו כן לפי\"ע זה תהי' השנאה אליו כו' דהכל תלוי בהשגת השכל, וכמה שיעמיק יותר באיכות ומהות טו\"ר שבחבירו כן יהי' ערך התפעלות המדה שבלב כו', וכן הוא בעבודה בהתפעלות אהוי\"ר שזהו דוקא ע\"י ההתבוננות באלקות כו', דהרי לא יתעורר באהוי\"ר בלי השגה והתבוננות אלקי כו', דאיך יהי' לו אהב' לאלקות כאשר אינו יודע את אלקות כו', והתפעלות המדות שבלא הקדמת ההתבוננות אינם אמיתיים ותומ\"י\nיתבטלו והי' כלא היו כו', כ\"א דוקא ע\"י התבוננות בהעמקת הדעת עי\"ז דוקא יהי' התפעלות אמיתי כו', וכמ\"ש בסש\"ב ח\"א פ\"ג. וזהו שאומרים ואהבת דוקא לאחר שמע ישראל כו' וברוך שם כו', דדוקא ע\"י ההתבוננות בה' אלקינו והוי' אחד כו' ובהתבוננות דבשכמל\"ו איך שהכל נתהווה רק מההארה אלקית כו' עי\"ז תהי' התעוררות האהבה בפרטי המדרי' דבכל לבבך ובכל נפשך כו', וזהו שיש זמן מיוחד להתעוררות אהוי\"ר והיינו בשעת התפלה דאז הוא זמן ההתבוננות ועי\"ז הוא מתעורר באהוי\"ר כו', וא\"א שיהי' כל היום באהוי\"ר מפני שא\"א להיות ההתבוננות תמיד כו' רק מה שנשאר על כל היום הוא הרשימו לבד כו', ובזה יש כמה חילוקי מדרי' באופן הרשימו שנשאר על כל היום, וזה תלוי באופן העבודה בתפלה דכאשר בתפלה ההתבוננות הוא בטוב ומתעורר באהוי\"ר אמיתיים אז כל היום גם כשהוא בעניני העולם הוא באופן אחר וכמ\"ש בכל דרכיך דעהו כו', וצדיקים הגדולים שהן מיוחדים ודבוקים באלקות כל היום זהו מפני שבתפלה מאיר בהם אור האלקי בנפשם בבחי' הנחה טובה במוח ולב ה\"ז נשאר על כל היום כו',\nובד\"כ העבודה היא בזמן מיוחד מפני שההתעוררות האהוי\"ר הוא ע\"י השגה והתבוננות דוקא כו' הרי דלידת המדות הוא מהמוחין ומתנהגים ע\"פ המוחין כו'."],[3601330699,"<span data-k=\"ks\"><b>קיצור.</b> והענין הוא דהמדות הן הרצון בעצם מהותן (ולמעלה מזה שהן התגלות ההשרשה עצמיות) רק שבאין במציאות, והוא שפשיטת העצמית בא בציור פרטי, ושכל הוא בחי' צורה בעצם, ולכן משתנה, ולמעלה הו\"ע ז\"א בעתיקא אחיד, ולכן האבות הן המרכבה להעלות חב\"ד, ומ\"מ הרי תולדות המדות מהמוחין דוקא, וכפי שיעור חיוב המוחין, וכן בעבודה ואהבה הוא דוקא ע\"י ההתבוננות בשמע ישראל וברוך שם, ולכן יש זמן מיוחד לתפלה, וכהי\"ו רק רשימו, ובצדיקים האור שבתפלה מאיר כהי\"ו.</span>\n<b>רנג)</b> ולכאורה כ\"ז אינו מובן מאחר שהמדות הן למעלה מן המוחין ויש תוקף גדול במדות יותר מהמוחין איך הם מתנהגים ע\"י המוחין שזהו כמו התחתון שמתנהג מן העליון וכמו הקטן שמתנהג מן האומן אותו ומדריכו כו', ובהכרח שיהי' בזה ביטול המדות לגבי המוחין דאז שייך לומר שהן מתנהגין ע\"י המוחין, ומאחר שהמדות הן למעלה מהמוחין ויש בהם תוקף יותר מהמוחין כו' איך הוא לידת והנהגת המדות ע\"י המוחין כו'. אך הענין הוא דזה שהמדות מתנהגים ע\"י המוחין זהו כשהמדות הן בבחי' חלישות דאז ה\"ה בטלים אל המוחין, והן כלים לאור המוחין להתנהג על ידן כו', דהרי לידת המדות מן המוחין והנהגתן מן המוחין זהו דוקא ע\"י התלבשות המוחין בהם כו', וכמו בהתעוררות אהוי\"ר בלב ה\"ז דוקא כאשר ההשגה והתבוננות המוח נרגשת בלב אז דוקא נתעורר בלבו כו', דאם ההתבוננות נשארת במוחו ואינו מגיע אל הלב לא יהי' ההתעוררות בלב כו', שזה הי' ענין גלות מצרים שזהו הפירוד בין המוח ללב ע\"י ג' שרי פרעה שעומדים במיצר הגרון ומעכבים שההתבוננות שבמוח לא יגיע אל הלב\nכו', דתכלית המכוון הי' שלא יהי' התגלות המדות וכמ\"ש אם בן הוא כו', וזה הי' ע\"י שלא יגיע ההתבוננות בלב כו' וכמ\"ש במ\"א. ובכדי שיהי' התעוררות הלב זהו דוקא כאשר ההתבוננות נרגשת בלב כו', שע\"ז נצטוינו וידעת היום והשבת אל לבבך כו' דהעיקר הוא שההתבוננות איך שהוי' אלקים כולא חד יהי' בבחי' השבה אל הלב שיאיר ויורגש הענין בלבו דוקא כו', וזהו ע\"י הדעת שעז\"א וידעת היום כו', וכידוע שהדעת מחבר המוחין עם המדות כו', וענין הדעת הוא ההרגשה הבאה ע\"י ההתקשרות כו' כנודע ועי\"ז דוקא הוא לידת המדות כו'. וכן הוא בגשמיות דאהבה ושנאה או חסד ודין הבאים ע\"י הטעם ושכל ה\"ז דוקא כאשר הטעם בטוב הדבר או להיפך הוא נרגש בלב כו' והוא ע\"י הדעת כו' וכמ\"ש באריכות בלק\"ת ד\"ה וידעת היום, וכן כל הנהגת המדות שע\"י המוחין וכמו בגדול שמדותיו הן בהנהגה שכליות בכל דבר ע\"פ חיוב השכל כו', ה\"ז התלבשות והתעסקות השכל להשכיל ולהשיג ולחשוב בזה איך יהי' הנהגת המדות בכל פרט כו', ואינו מתפעל מעצמו בשום דבר כ\"א ע\"פ השכל וכפי חיוב השכל כן יהי' המדות\nכו'. וכ\"ז הוא כאשר המדות הן בחלישות דאז הן כלים לאור השכל ובטלים אל השכל שמתנהגים ע\"י כו', אבל המדות בעצם מהותם ה\"ה למעלה מהמוחין ומצ\"ע יש בהם תוקף גדול יותר מהמוחין ואינם בטלים כלל אל המוחין כו', וכמו שאנו רואין גם בהמדות הנולדים מן השכל הרי יכול להיות אח\"כ תוקף התפעלות המדות הרבה יותר מהשכל המולידם כו', והיינו מצד עצם מהותם שהן בתוקף יותר מהמוחין כו', אך כאשר העבודה תחלה בבחי' המדות הנולדים מן המוחין אז גם המדות שמצ\"ע היינו בחי' תוקף המדות שהו\"ע אה\"ר כו'"],[3601330700,"ה\"ז ג\"כ בבחי' הביטול כו', ובאמת בחי' אה\"ר הוא שנותנים מלמעלה, וכידוע בפי' ואהבת שיש בזה ב' פי' הא' ל' ציווי והיא האהבה שע\"פ טו\"ד שזהו בכח האדם מעצמו לבא לידי אהבה ע\"י התבוננות כו'. והב' ואהבת ל' הבטחה שסופך לבא לידי אהבה והיא האהבה שנותנים לו מלמעלה כו', וכמו ביראה כתי' ואתנם לו מורא ע\"י ויראני כו' וע\"י הקדמת האהוי\"ר שע\"פ טו\"ד נותנים מלמעלה אהוי\"ר עליונים והן בבחי' ביטל כו' (והיינו שנותנים לו בחי' מדות דתיקון כמו שהן בשרשן כו').\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש בהעלותך את הנרות דענין העלאת הנרות הוא בחי' אה\"ר שזהו מה שאהרן כה\"ר המשיך בנש\"י בחי' אה\"ר שלמעלה מטו\"ד כו', והיינו הנרות מצ\"ע שהן בבחי' העלאה היינו בחי' האהבה שע\"פ טו\"ד והעלאת הנרות התגלות בחי' האה\"ר כו', ובכדי שתהי' התגלות אה\"ר צ\"ל תחלה העבודה שע\"פ טו\"ד כנ\"ל. וזהו שאומר אח\"כ וזה מעשה המנורה מקשה זהב דמקשה הוא ל' קושי' וכמא' שנתקשה משה כו', והנה קושי' הוא בחי' העלם והסתר כנודע. וזה שייך בכחות הנפש המלובשים בגוף שבזה שייך העלמות והסתרים מהנה\"ב כו', והעבודה שע\"פ טו\"ד היא להסיר ההעלמות וההסתרים כו', ואומר עד ירכה עד פרחה מקשה היא דיריכה זה מדרי' נמוכות ופרחה מדרי' גבוהות כמ\"ש בלקו\"ת ע\"פ זה, והיינו כנ\"ל דגם במדרי' גבוהות העבודה שע\"פ טו\"ד ה\"ז בהאור שבא בבחי' התלבשות כו'. וע\"ז נא' כאן מעשה המנורה הגם שנאמרה בזה פ' שלימה בפ' תרומה שזה שייך להעלאת הנרות שע\"י הקדמת העבודה שע\"פ טו\"ד נותנים בחי' אה\"ר שזה הי' עבודת אהרן להמשיך בנש\"י כו'. ועז\"א שלך גדולה משלהם, דהנה\nנת\"ל בפרי\"ב ואח\"ז ההפרש בין קרבנות וקטרת דקרבנות הוא העבודה דחיצוניות הלב והיינו שע\"פ טו\"ד וקטרת היא העבודה שלמעלה מטו\"ד כו', ומנורה הוא כענין הקטרת וכמשנת\"ל פר\"י מהבחיי בשם המד\"ר, וזהו שלך גדולה כו', וגם י\"ל שלך גדולה משלהם היינו שע\"י העבו' דע\"פ טו\"ד באים לבחי' אהוי\"ר העליונים כו'. וזהו בהעלותך את הנרות דהנרות הן בבחי' העלאה וזהו האהוי\"ר שע\"פ טו\"ד והעלאת הנרות הוא האהוי\"ר העליונים כו', ואו' וזה מעשה המנורה היינו העבודה שע\"פ טו\"ד ועי\"ז הוא העלאת הנרות התגלות בחי' רעו\"ד כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אך זהו כשהמדות הן בבחי' חלישות, והנהגת המדות ע\"י השכל הוא ע\"י התלבשות דוקא, ובעבודה כאשר ההתבוננות נרגשת בלב (וז\"ע גלות מצרים להפריד בין המוח והלב), ולכן העיקר הוא הדעת, וכ\"ז בחלישות המדות, ויכול להיות בהם הגדלה מצד מהות עצמן, אך ע\"י הקדמת העבודה שע\"פ השכל גם עצם המדות בבחי' ביטול, ובאמת הוא שנותנים מלמעלה אהוי\"ר עליונים. וזהו מ\"ש בהעלותך את הנרות, הנרות הן האהוי\"ר שע\"פ טו\"ד, והעלאת הנרות ע\"י אהרן גילוי בחי' אה\"ר.</span>"],[3601330701,"<h3>בס\"ד. ש\"פ שלח, תרד\"ע</h3>\n<b>ויהס</b> כלב את העם אל משה ויאמר עלה נעלה וירשנו אותה כי יכול נוכל כו', וצ\"ל מהו אומרו אל משה דהל\"ל סתם ויהס את העם, וכי הי' הדבר נוגע אל משה יותר מכולם. גם מהו\"ע כי יכול נוכל לה הלא כבר אמר וירשנו אותה מהו עוד כי יכול כו', ומשמע שזהו נתינת טעם על וירשנו אותה, וצ\"ל מהו הנתינת טעם בזה, ובגמ' דסוטה אמרו עלה נעלה אפי' משה אומר לנו לעשות סולמות ולעלות לרקיע אנו עולים, וגם זה צ\"ל מה\"ע הסולמות כו'. ולהבין זה ילה\"ק משנת\"ל דבמדות יש תוקף גדול יותר מבמוחין, דבמוחין יש שינוי דלפעמים משכיל כך ולפעמים כך והמדות אינם משתנים בעצם מהותן כו', מפני שהמדות הן התגלות הטבע שבנפש, דענין ההשרשה פשוטה שבנפש דכל העצם הוא בהשרשה זו ולפי אופן ההשרשה הוא התגלות כל הכחות, והמדות הן התגלות ההשרשה הפשוטה וע\"כ יש בהם תוקף גדול כו', ומ\"מ המוח שליט על הלב והנהגת המדות הוא ע\"י המוחין כו'. ונת' שזהו כאשר המדות הן בחלישות דאז הן כלים לאור המוחין ומתנהגים על ידן, דכשהמדות הן בתוקף אינם בטלים אל המוחין רק כשהן בחלישות ה\"ה בטלים אל המוחין ומתנהגים ע\"י כו'.\n<b>רנד)</b> וביאור הענין הנה אנו רואין דהגדלת המדות הוא מן המוחין שהרי הקטן מדותיו קטנים, והיינו גם כשהגיע לעונת המוחין, דכ\"ז שלא הגיע לעונת המוחין ה\"ה טבעי לבד, אבל גם כאשר הגיע לעונת המוחין להיות שכלו בקטנות גם המדות שלו הן בדברים קטני הערך וכשיגדל שמתגדל גם מדותיו הן בדברים גדולי הערך, הגם שהמדות הן מהות בפ\"ע מן המוחין ואין התהוות עצם המדות מן המוחין, רק שהמוחין הן כמו מראה מקום אל המדות שמראה להם מה שירצה, דהמדות הן חפץ הלב שרוצה באיזה דבר הטוב, והשכל מראה לו שזה הדבר טוב ומתעורר בלבו לרצות בו, וכמו עד\"מ כשאחד בא ומגיד לחבירו שנמצא אוצר במקום פלוני ה\"ה מתעורר במדה לזה, הרי הרצון להאוצר כבר ישנו בו מקודם רק שלא הי' בהתעוררות כלל מפני שלא ידע שנמצא כלל, וכאשר זה הודיעו שנמצא אוצר והוא במקום פלוני ה\"ה מתעורר ברצון לזה, וזהו שהשכל מראה את הדבר הטוב ועי\"ז יתעורר המדה כו', וממילא לפי אופן הגדלת השכל שמראה לו טוב הדבר לפי אופן כזה הן המדות כו'. וזהו בד\"כ שהגדלת המדות הן מן המוחין,\nאמנם עיקר ענין ההגדלה שע\"י המוחין הוא בהאור וחיות של המדה שע\"י המוחין נמשך אור וחיות בהמדה, ועי\"ז המדה היא לא בבחי' מציאות ולא בבחי' מורגש, עם היות שהמדה היא בהתגברות יותר וכמשי\"ת מ\"מ אינה בבחי' מורגש מצד האור והחיות שבה כו'. דזהו כללות ההפרש בין מדות טבעיים למדות שכליים, דמדות טבעיים הן חומריים ומורגשים ביותר בעצמן, ומדות שכליים אינם מורגשים כ\"כ כו', וכמו שהנה\"ב הוא טבעי ונה\"א הוא שכלי, להיות דנה\"ב הוא חומרי בעצם מהותו שיודע רק עצמו ומהותו במורגש ביותר, והנה\"א הוא צורי בעצם, והיינו דעצם מהותו הוא ביטול והמשכה (א ציא) למה שלמעלה ממנו, והו\"ע הרצון עצמי וטבעי שבנשמה שהיא בבחי' רצוא תמיד לאלקות (ועמשית\"ל פ'), וזהו שהוא שכלי דהשכל הוא צורה בעצם כמשנת\"ל פרנ\"ב, וכמ\"ש במ\"א דהמוחין הן בבחי' עלי' והבדלה (ונז' לעיל פרל\"ז) ובכל פרצוף הג\"ר הן בחי' השבת שבו כו' (ובלק\"ת ד\"ה אם"],[3601330702,"בחקתי הב' כ' נפש השכלית המחבר הצורה והחומר שהוא נה\"א עם הנה\"ב כו', ונפש היא בחי' נוגה מעורב טו\"ר כו', והיינו דשם הכוונה דנה\"א הוא בחי' הרצון עצמי וטבעי דנשמה לאלקות, שזהו עיקר האלקות שבנשמה וכמשנת\"ל פר\"נ. ובענין נפש השכלית מבו' במ\"א שזהו בחי' הטוב שבנוגה והיינו מה שיש בכח האדם להשכיל בשכל אנושי ג\"כ בגדולת ה' ולהתפעל במוחו ואח\"כ בלבו, והיינו עד שגם השכל מסכים עם הטבע דנה\"א כו', וזהו הגורם דהניצוץ אלקי דנשמה דהיינו הרצון שלמעלה מטו\"ד יהי' מאיר בגוף כו' וכמ\"ש במ\"א, אבל זאת ודאי דגם הנה\"א הוא שכלי, רק שיש הפרש גדול בין השכל דנה\"א להשכל דנפש השכלית, דהשכל דנה\"א הוא שכל אלקי (געטליך) וכרוח אלקי ממש, ומשגת אלקות ממש אם בבחי' ידיעת המציאות או השגת מהות ועצם אור האלקי, ע\"ד השגת אלקות דנשמות בג\"ע, וגם בנבראים השגתה הוא בבחי' הרוחניות בבחי' התהוות העולמות והנבראים מאין ליש והוא ההשכלה וההשגה בגוף ועצם האין האלקי איך ומה הוא, ובאיכות ענין ההתהוות, ואיך שכל נברא באמת הוא האין האלקי בעצם מהותו כו'.\n<b>משא\"כ</b> השכל וההשגה דנפש השכלית באלקות הוא הכל רק מצד הנבראים, וכמו גדולת ה' בענין ההתהוות שנעשה דבר מלא דבר, ובריבוי ההתהוות דמה רבו מעשיך בנבראים בריבוי עד אין שיעור, ומה גדלו מעשיך בנבראים העליונים כו' שבזה נראה ונגלה גדולתו וגבורתו ית' וכמ\"ש במ\"א, וכן בביטול הנבראים למקור חוצבם ואיך שכולם מהללים ומשבחים ובטלים לאלקות כו', וכמו שרואה בעצמו ביטול הגוף אל הנשמה שנגרר אחר החיות ובטל לגמרי אל רצונו כו', כמו\"כ יבין ביטול הנבראים אל אור וחיות האלקי המהווה ומחי' אותם כו' (ועמ\"ש בסי' ד\"ה ששת ימים הא' ובהבי' שם), ולהיות שהנבראים מנוגה ע\"כ גם השכל המשיג ביטול הנבראים הוא מבחי' הטוב דנוגה שהוא משיג רק הביטול דנוגה כו'. ויותר מזה מבו' במ\"א דגם נשמה האלקית שהיא מסט' דבעירא דכיא כמ\"ש בסבא דמשפטים ב\"נ כד אתיליד יהבין לי' נפשא מסטרא דבעירא כו', הנה השכל שבה ג\"כ מבחי' הטוב שבנוגה כו' ומבו' הענין במ\"א, אמנם כן הוא שגם הנה\"א הוא שכלי ולכן נק' אדם והרי מעלת האדם הוא בשכל כו' (ועמשנת\"ל פר\"ג) ומבו' במ\"א דגם\nבחי' הרצון פשוט דנה\"א יש בזה בחי' חכמה כו'). וכמו כללות ההפרש בין נה\"א ונה\"ב שהו\"ע שכלי וטבעי צורה וחומר כו', כן הוא ההפרש בין מדות טבעים ומדות שכלים גם בקדושה, דמדות טבעים הן בבחי' חומר שאינם בדקות והן במורגש בעצם (ועמשנת\"ל פרי\"ד), ומדות שכלים הן בבחי' דקות שהעיקר בהם האור והחיות, והן בלתי מורגשים כו', וביותר הוא בגדלות המדות בחי' מוחין שית\"ל פ' וע\"י המוחין המדה היא בהתגברות יותר היינו שהיא בריבוי האור ובבחי' פנימי ביותר כו' וכמשי\"ת. וזהו התחדשות ההגדלה שע\"י המוחין לההגדלה דמדות מעצמן שהרי כל כח מתגדל במשך הזמן וגם המדות מתגדלים מעצמן אך ההגדלה היא שנעשה יותר בבחי' מציאות ובבחי' מורגש ביותר כו', ובאמת אין זה הגדלה רק התגלות לבד, דענין ההגדלה הוא שנעשה בזה איזה התחדשות ועם ההגדלה ה\"ז לא כמו שהי' קודם כו', ובהגדלת המדות מעצמן אין בזה התחדשות וע\"כ זהו רק התגלות לבד שבא בהתגלות ובמורגש יותר, אבל בההגדלה שע\"י המוחין ה\"ז אדרבא שלא בבחי' מורגש כו', מפני שעיקר ההגדלה הוא בהאור והחיות כו'."],[3601330703,"<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע דהנה המדות הגם שאין מהותם מהמוחין, הרי הנהגתם הוא ע\"פ המוחין, שהן מראים למדות מה שירצה, וע\"כ הן כפי אופן מראת המוחין, ועיקר ההגדלה שע\"י המוחין בהאור וחיות שעי\"ז הן בלתי מורגשים, דהמדות בעצם הן טבעים וחומרים, וע\"י המוחין נעשים בבחי' צורה (ויבאר בקצרה ענין שכל דנה\"ט ודנה\"א), דהגדלת המדות מצ\"ע הוא בבחי' המציאות והמורגש יותר, וע\"י המוחין התחדשות ההגבלה בבחי' האור והביטול יותר.</span>\n<b>רנה)</b> והנה בפרטי ההגדלה יש בזה ג' מדרי' כללים עיבור יניקה ומוחין, עיבור הוא תכלית הקטנות ותכלית ההעלם שלא יש בזה עדיין גילוי המוחין, וכמו עד\"מ הולד כשהוא במעי אמו ה\"ה מקופל ראשו בין ברכיו שההתגלות הוא רק נה\"י לבד וחב\"ד וחג\"ת הן בהעלם כו', ולכן אין זה נחשב עדיין בכלל ציור אדם, דאדם הוא מוחין ומדות ובעיבור להיות שאין בזה עדיין מוחין ומדות אין זה בכלל ציור אדם עדיין כו'. וידוע דלמעלה הו\"ע האופנים שמעמדן בעשי' ששם רק בחי' נה\"י כו', הרי האופנים הן בחי' עיגולים כו', וכידוע ההפרש בין שרפים לאופנים דבשרפים כתי' בשתים יכסה פניו ובשתים יכסה רגליו כו' שהן בבחי' ציור אדם, כמו האדם שהוא בקומה זקופה ראש יד רגל שהן חב\"ד חג\"ת כו', והוא בחי' יושר כו', ובאופנים כתי' כאשר יהי' האופן בתוך האופן שזהו בחי' עיגולים כו' הרי אין זה עדיין בכלל ציור אדם כו'. ומ\"מ ה\"ז ג\"כ בכלל ההגדלה מפני שמ\"מ יש בזה קצת מוחין, וכידוע שבפרטיות יש גם בעיבור בחי' חב\"ד חג\"ת נה\"י ומאחר שיש בזה מדרי' פרטיות הרי בהכרח שיש בזה\nקצת מוחין כו', דהנה נה\"י שבנה\"י הו\"ע הודאה, דהודאה הוא כשאינו משיג את הענין דאם משיגו הרי אינו שייך הודאה שהרי הוא משיג אותו, רק כשאינו משיג אותו אז הוא בבחי' הודאה לבד כו', ומ\"מ יש בזה קצת שכל שמשיג שצריכים להודות, והיינו שמשיג שהענין כך הוא, עם היות שלא יש הענין בהשגתו שידע איך ומה הוא מ\"מ ה\"ה יודע שהוא כך, וכמו עד\"מ חכם גדול המופלא בחכמתו ומגלה שכליים נעלים מאד, הנה גם מי שאינו יודע ומשיג השכלותיו וממילא אינו משיג כלל אופן חכמתו וההפלאה שלו, מ\"מ ה\"ה יודע שהוא מופלא בחכמה, דכ\"כ יש לו עכ\"פ שייכות לענין השכל שיודע עכ\"פ שהוא מופלא הגם שאינו יודע כלל אופן ההפלאה מפני שאינו משיג את השכליים שלו כו', וכמו\"כ הוא ברוחניות מש\"א מודים אנחנו לך שאתה ה' אלקינו, דבכללות בעולמות הוא שבורא ומהווה עולמות מאין ליש כו', ובפרטיות בנש\"י הוא שישראל עלו במח' כו', הנה הגם שאין לו שום השגה בענין התהוות יש מאין מהו יש מאין ואיך הוא אופן ההתהוות (ועמשנת\"ל פק\"נ), ובפרט ההפלאה שיש בהתהוות יש מאין כו' כ\"ז אינו\nיודע ומשיג כלל כו', מ\"מ ה\"ה יודע שאלקות בורא ומהווה מאין ליש וכשבא בהענינים המדברים בזה כמו בפסוד\"ז יש לו בזה קצת הרגש בזה ומתפעל בנפשו ופועל בו הביטול כו', ועם היות שאין בזה השגה וה\"ז רק ידיעה לבד מ\"מ ה\"ה יודע ויש לו קצת שייכות לזה כו', וזהו ברוב בנ\"א שאין עוסקים בהשגת ענינים פנימיים היינו בעניני אלקות מ\"מ יודעים המה ענין בריאה יש מאין בכלל ומתפעלים בזה כו', דההודאה דהודאה הוא מודים אנחנו לך על שאנו מודים לך כו', והיינו שאין לו שום שייכות לידיעה זו ואין לו שום ידיעה והרגש כלל כו', ומ\"מ הוא בבחי' ביטול לאלקות כו', והודאה הוא שיש לו קצת ידיעה והרגש"],[3601330704,"כו' כנ\"ל, הרי שיש בזה קצת שכל כו'. וחג\"ת שבנה\"י הן המדות השייכים לפועל וכמו מי שמסכים בלבו להיות סו\"מ וע\"ט בפו\"מ בהסכם חזק וזה רק בהסכם לבד, לא שהוא בו בעצם וכמו פרומקייט טבעיות שזהו שבטבעו הוא סו\"מ כו', אבל בזה מצד העצם יכול להיות באופן אחר לגמרי רק שעשה הסכם חזק להיות סו\"מ וע\"ט ולהדר בוע\"ט וכמו\"כ לעשות זהירות בעניני סו\"מ כו', דבהכרח שיש בזה התעוררות אהוי\"ר ואיזה הרגש אלקי דאל\"כ מאין בא ההסכם כו', דהרי אהוי\"ר הן מקור מ\"ע ומל\"ת וכמ\"ש בסש\"ב והמקיימן באמת הוא האוהב ש' ה' כו', ואם הי' לו אהוי\"ר באמת הרי הי' חפץ באמת בקיום המצות כו', וכאן הרי לא יש התעוררות אהוי\"ר באמת כו', מ\"מ סיבת ההסכם החזק ובפרט להזהר בעניני סו\"מ ולהדר בוע\"ט בהכרח שיש בזה איזה התעוררות ואיזה הרגש כו', רק שזהו בקטנות מאד כו'. וחב\"ד שבנה\"י זהו האהוי\"ר שבתבונות מוחו ותעלומות לבו וכמ\"ש בסש\"ב פט\"ז שגם אין יד שכלו ורוח בינתו משגת להוליד אהבת ה' בהתגלות לבו שיהי' לבו בוער כרשפי אש כו', רק האה' מוסתרת כו', שהלב מבין גדולת א\"ס\nב\"ה דכולא קמי' כל\"ח ממש אשר ע\"כ יאתה לו ית' שתכלה אליו נפש כל חי לידבק ולהכלל באורו, וגם נפשו ורוחו כו' כך יאתה להן כו', ולית מחתב\"כ כ\"א כאשר תפיסא ומתלבשת בתורה ומצותי' כו', ואי לזאת יאתה להן לחבקו בכל לב ונפש ומאד כו' שכ\"ז אינו בבחי' השגה ממש שהרי אין יד שכלו משגת כו', ובפרט בענין דכולא קמי' כל\"ח שתהי' הידיעה בהאורות והגילוי' ואיך שכולא קמי' כל\"ח ובפרט הידיעה בהפלאת עצמותו כו'. וכידוע דבענין כולא קמי' כל\"ח יש ב' אופנים הא' כמו שכל הגילוים הם רק הארה לבד ואינם תופסים מקום כלל לגבי עצמות כו', והב' ידיעת מעלת והפלאת העצמות איך שהכל קמי' כל\"ח כו' וכמ\"ש במ\"א, דלכ\"ז אין לו שייכות כלל להשגת הענין כו', רק מה שיודע שהוא כך דכולא קמי' כל\"ח כו', וה\"ז כמו הידיעה דבריאה יש מאין שנת\"ל כמו\"כ הוא בידיעה זו כו', ומ\"מ ה\"ז אצלו בידיעה שחושב בזה ויודע שכך הוא ומרגיש את הענין קצת וג\"ז שכך יאתה לו ה\"ז בבחי' הרגש אצלו, דעם היות שאינו בבחי' אהבה ממש בהתגלות מ\"מ מורגש אצלו איך שכך יאתה לו כו', שבאם לא יהי'\nההרגש כלל (רק ידיעה חיצוני' לגמרי) לא יהי' בזה התגלות האהבה מוסתרת ג\"כ כו' כ\"א שזהו עכ\"פ בבחי' ידיעה והרגש כו', והיינו שיש בזה מבחי' המוחין ומדות כו', רק שכ\"ז הוא בקטנות מאד ובכללות הוא בחי' עיבור לבד שזהו רק נה\"י כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ופרטי ההגדלה הן עי\"מ, עיבור נה\"י תכלית הקטנות ואינו בציור אדם, והו\"ע האופנים, ומ\"מ ה\"ז הגדלה שיש קצת מוחין, דנה\"י שבנה\"י הוא שמודה מצד הידיעה כללית, וכמו הידוע לחכם מופלג מודה בשכלו הגם שאינו משיגו כלל, וכן מודים אנחנו לך שאתה מהווה הכל, הגם שאינו יודע כלל ענין ההתהוות, ומתפעל קצת. חג\"ת דנה\"י הסכם חזק בסו\"מ וע\"ט, דבהכח יש בהעלם איזה אהוי\"ר מקור מ\"ע ומל\"ת. חב\"ד דנה\"י אהוי\"ר שבתבונת מוחו ותעלומות לבו שאינו השגה ממש (ב' ענינים בכולא קמי' כל\"ח ביטול האורות והפלאת העצמית) מ\"מ יש בזה איזה הרגש בהענין ושכך יאתה לו להיבטל איליו.</span>\n<b>רנו)</b> והנה בחי' יניקה הוא שיש התגלות המדות הבאים ע\"י השגה והתבוננות כשמתבונן היטב בגדולת ה' בבריאת והתהוות העולמות, דהנה כתי'"],[3601330705,"גדול ה' ומהולל מאד בעיר אלקינו אימתי הוא גדול כשהוא בעיר אלקינו שבזה ניכר גדולת ה' ובזה אנו יכולים להשיג גדולתו כו', דגדולת ה' בעצם אין אנו יכולים להשיג רק מפעולותיו ית' כו', וזהו אימתי אנו משיגים גדולתו כשהוא בעיר אלקינו עולם הדבור העליון כו', דעיר הוא מריבוי בתים ובית נעשה מריבוי אבנים כו', דאבנים הן אותיות שתי אבנים בונות שתי בתים כו', ועיר אלקינו הוא כללות עולם הדבור בריבוי אותיות וצירופים שהן מקור כל הנבראים שנתהוו בריבוי עד אין קץ ושיעור, וכמ\"ש מה רבו מעשיך ומה גדלו מעשיך כו' מה רבו מעשיך הן ריבוי הנבראים דבכללות הן דצח\"ם ובפרטיות יש בזה ריבוי עד אין שיעור כו', וכ\"ז בעולם התחחון והרי כל דבר שלמטה יש לו שרש ומקור למעלה, וכמו כד קארי תרנגולתא מברך הנותן לשכוי כו' דבשרשו הוא מלאך גבריאל ובשרש שרשו ה\"ג דאימא כו', דבכ\"ז הרי יש ריבוי עד אין שיעור ממש כו', ומה גדלו הן גדולי הנבראים הן בכמות דמן הארץ לרקיע כו', רגלי החיות שוקי החיות כו', והן באיכות שגדולים במעלתן כו', ומכ\"ז מובן גדולת ה'\nהבורא ומהווה הכל כו', וכדאי' במד\"ר ע\"פ השמים מספרים דמאבני דהוא מתגושש בהון כו' (ועמשנת\"ל פ' צ\"ט), וכ\"ז נתהווה רק במאמר א' ורוח פיו וכמש\"א ברוך שאמר והי' העולם דבאמירה א' נבראו כל העולמות כו', ואופן ההתהוות הוא בדרך אין ערוך שז\"ע יש מאין כו', ומ\"מ יש בזה כח הא\"ס דבכדי שיהי' התהוות זהו בכח הא\"ס דוקא שאין זה בחוק הנבראים כלל כמו עו\"ע שנמצא ג\"כ בחוק הנבראים, משא\"כ בריאה יש מאין אין זה בחוק הנמצאים כלל כ\"א בכח הא\"ס שהוא לבדו בכחו ויכולתו כו', ולכן יש בענין הבריאה שני הפכים דהרי ההתהוות צ\"ל בבחי' קירוב ובבחי' שייכות האין אל היש כו', ובהיפך הוא בדרך העלם והסתר הבורא מהנברא שזהו להיות שזה כח הא\"ס לכן יש בזה דבר והיפוכו כו', וכשיתבונן בכל פרטי הדברים בזה שכ\"ז מבואר באריכות בפסוד\"ז יתפעל בנפשו מאד על גדולת ורוממות ה' בענין ההתהוות ויהי' עי\"ז קירוב נפשו שמתקרב מאד אל אלקות כו'. וכמו\"כ בענין ואתה מחי' את כולם איך שבכל דבר יש אור וחיות אלקי המחי' ושהעיקר הוא אלקות כו', ובפרט כשמתבונן באופן התלבשות\nהאור האלקי שהוא בבחי' צמצום כו' ובאופן האור האלקי בכל עולם בפרט כו', שע\"י כ\"ז יהי' התגלות האהבה שחפץ באלקות ובהגילוי אלקות כו'. וז\"ע מוחין דיניקה שיש בזה גילוי המוחין והתגלות המדות כו', ומה שנק' יניקה הוא מפני שבעת התגלות האהבה אז המוחין הן בהעלם ונשאר רק מעט מן המוחין בהמדה שז\"ע יניקה שאינו עצם הדבר כ\"א הארה לבד כו', דלהיות שההתבוננות היא בהאור האלקי השייך אל העולמות כו' דבד\"כ זהו בחי' המוחין השייכים אל המדות כו', דהשגה זו היא בלבושי השגה כו', כי השגה והתבוננות הנ\"ל צ\"ל בעניני שכליים המכריחים ומחייבים איך שהוא כך כו' וכמ\"ש במ\"א באורך, וע\"כ הגילוי כמו שהוא בהמוחין אינו מאיר בלב והתעוררות המדות הן רק מהבכן לבד כו', והיינו לפי שכללות ההשגה היא השייכה אל המדות לבד והיא בהאור האלקי השייכה אל העולמות כו', ומלובש בלבושי השגה כו' (דכ\"ז הא בהא תליא כו') ע\"כ תולדות המדות הוא מהבכן לבד כו', וע\"כ זהו בחי' יניקה דהיינו רק הארה לבד כו', ולכן באמת המדה הנולדה מזה היא מדה מורגשת מפני שאין בה אור\nוגילוי רב מהמוחין כו', ומ\"מ יש בה אור וחיות שהרי הבכן זהו הטעם של המדה שזהו בחי' המוחין שבמדות כו' וכמ\"ש במ\"א, וגם אור המוחין מרחף על המדה מלמעלה דהיינו שגם בעת התפעלות המדה נרגש בהעלם ההשגה שממנה נתפעל"],[3601330706,"באהבה כו', וזהו פועל הביטול בהמדה כו', דהרי מהמדה יכול להיות יניקה וכמ\"ש לא יחפץ כו' בהתגלות לבו דיכול להיות שיפול בהיפוך ח\"ו, דהיינו גם במדות הנולדים מן השכל להיות שזהו רק מהבכן לבד וה\"ה במדה מורגשת יכול ליפול כו', אך ע\"י הרגש ההשגה גם בהעלם ה\"ז עושה שהמדה הוא בבחי' ביטול כו' וכמ\"ש במ\"א.\n<span data-k=\"ks\"><b>קיצור.</b> ויניקה הוא שהמדות הן ע\"פ טו\"ד, התבוננות בגדולת ה', מה רבו מעשיך ומה גדלו מעשיך, ושההתהוות היא בכח הא\"ס ולכן יש בזה ב' הפכים דקירוב וריחוק, והוא ההתבוננות בהארה האלקית שבעולמות, ומאיר רק הבכן בלב, ומ\"מ יש בזה אור, וגם אור המוחין מרחף על המדות להיות בהם ביטול.</span>\n<b>רנז)</b> אמנם תכלית ההגדלה הוא בחי' מוחין והוא שההתבוננות הוא בעומק ופנימיות הענין גם בהתבוננות הנ\"ל בגדולת ה' בהתהוות העולמות כאשר ההתבוננות היא בעצם הענין בבחי' הפשטה מלבושי השגה כו', או שההתבוננות היא באוא\"ס שלמעלה מבחי' התלבשות בעולמות כו' דבזה ממילא ההשגה היא בבחי' הפשטה כו', דבהתבוננות זאת מאיר האור גם בלב דהיינו בעת ההשגה גופא שמאיר האור במוחו ה\"ז מאיר בגילוי בלב ג\"כ ומתעורר ומתפעל בלבו בעת ההשגה וההתבוננות רק שאין המדות במורגש כלל מפני עוצם הגילוי שמאיר בהמדות אינם מורגשים כלל כו', ועם היות שהמדה היא בתגבורת גדולה שלבו בוער ביותר מפני שהיא קרובה יותר אל המוחין כו', שהרי לידת המדה היא מן המוח וממילא אינו דומה אם המדה היא רק מהבכן שהיא מרוחקת מן המוחין או שהיא בעת ההתבוננות ומעצם ההתבוננות שהיא בקירוב מאד אל המוחין כו', רק להיות שאור ההשגה (והוא האור האלקי המושג כו') מאיר בה בגילוי ממש כו', אינה בבחי' מציאות ובבחי' מורגש כלל כו'. ובדוגמא כזאת מצינו בסודות ורזין דאורייתא\nגבי הרשב\"י כששמע רזין עילאין מרע\"מ גחין ר\"ש ונשיק לעפרא כו' שזהו מהתפעלות הלב כו', ואין זה כמו זלגו עיניו דמעות האמור גבי רע\"ק כששמע סודות התורה מר\"א, וכן ברשב\"י כששמע מר' נהוראי שזהו מהתפעלות המוח שעושה כיווץ בהמוח ומזה הוא סיבת הדמעות כו', אבל ענין גחין ונשיק לעפרא זהו מהתפעלות הלב, והרי אין זה במורגש כלל הגם שההתפעלות היא גדולה ביותר כו', וכן הוא בהתפעלות המדות הבאים בדרך ממילא מהמוחין אינם במורגש כלל כו', וזהו תכלית הגדלת המוחין שמאיר בהם גילוי אור רב דאז אינם במציאות ובמורגש כלל כו'. וכמו\"כ היא הדוגמא למעלה בהגדלת ז\"א בג' מדרי' דעי\"מ כו', דעיקר ענין ההגדלה הוא בבחי' הגילוי כו', ובחי' עיבור הוא בתכלית הקטנות וההעלם כו', ומוחין דיניקה הוא שמאיר בהם גילוי אור אך הוא בחי' מוחין שבמדות לבד כו', ובחי' מוחין הוא שמאיר גילוי אור בז\"א כמו באו\"א כו' (ועמשית\"ל באורך ענין ההגדלה דעי\"מ), וזהו ההפרש בין זה\"ג לזה\"ב, דבזה\"ג גילוי המדות הוא בבחי' נה\"י לבד, וכידוע שהגלות נק' עיבור כו' בגלותא קוב\"ה\nסליק לעילא כו' בחי' סילוק האור מז\"א כו', וזהו סיבת ריבוי ההעלמות וההסתרים וכמו אותותינו לא ראינו אלביש שמים כו', ועיקר ההנהגה בזה\"ג הוא מבחי' מל', וכנודע שגם במל' יש ז' מדות רק שהן בבחי' אספקלרי' דלא נהרא בחי' העלם כו', ומה שנמשך מז\"א הוא"]]});
